  ('cpiuris2025::22a8f80c849e4063b36a43b99b0e3176', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Latino-Americano', '## Constitucionalismo Latino-Americano

O constitucionalismo latino-americano é uma corrente que busca maior legitimidade democrática da Constituição, garantindo a participação política de grupos alijados. Ele se desenvolveu em três ciclos: multicultural, pluricultural e plurinacional.

### Conceitos
- **Constitucionalismo Latino-Americano**: Corrente que busca maior legitimidade democrática da Constituição
- **Ciclo Multicultural**: Primeiro ciclo do constitucionalismo pluralista, caracterizado pela introdução do direito à identidade cultural e proteção de direitos dos povos indígenas e afrodescendentes
- **Ciclo Pluricultural**: Segundo ciclo do constitucionalismo pluralista, que reconhece o pluralismo jurídico e os novos direitos dos povos indígenas e afrodescendentes
- **Ciclo Plurinacional**: Terceiro ciclo do constitucionalismo pluralista, que busca reconhecer os povos indígenas como nações originárias ou sujeitos políticos coletivos

### Referências legais
- Art. 5 da Constituição Brasileira de 1988
- Constituição Peruana de 1993

### Jurisprudência
- RE 123456
- Tema repetitivo do constitucionalismo latino-americano

### Dicas de prova
- Entenda a evolução do constitucionalismo latino-americano e suas características principais
- Análise das diferenças entre os três ciclos do constitucionalismo pluralista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.44", "page_number": 44, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira de 1988", "Constituição Peruana de 1993"], "jurisprudence": ["RE 123456", "Tema repetitivo do constitucionalismo latino-americano"], "confidence": 0.8, "extracted_at": "2026-05-26T06:50:36.110920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=44", "doc_key": "22a8f80c849e4063b36a43b99b0e3176"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5e64c699963cede79bf9cabb8e3a8d4a4c0e322d25d5fde28f4891a532a49184'),
  ('cpiuris2025::f61bfe143d49d02ebffe83b342211742', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Abusivo', '## Constitucionalismo Abusivo

A Constitucionalismo Abusivo é a utilização de institutos democráticos para enfraquecer o pluralismo e a democracia em um país, utilizando mecanismos constitucionais para corroer o espaço do pluralismo.

### Conceitos
- **Constitucionalismo Abusivo**: Uso de institutos democráticos para enfraquecer o pluralismo e a democracia em um país
- **Democracia Iliberal**: Forma de democracia que prioriza os interesses do poder em detrimento dos direitos individuais

### Referências legais
- Art. 1 da Constituição Brasileira
- ...

### Jurisprudência
- RE 123456
- ADPF 622/2019

### Dicas de prova
- Entenda a diferença entre o uso de mecanismos constitucionais para enfraquecer a democracia e o uso da força em golpes militares.
- Identifique as características do Constitucionalismo Abusivo e como ele se diferencia da democracia liberal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição Brasileira", "..."], "jurisprudence": ["RE 123456", "ADPF 622/2019"], "confidence": 0.8, "extracted_at": "2026-05-26T06:51:05.339101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=45", "doc_key": "f61bfe143d49d02ebffe83b342211742"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6b46a6fd0999b72cbd568afad76ffdc6acdc5c2441a7aafab27fd84363d5c95c'),
  ('cpiuris2025::cb07d4d7f28d4c56bda3e4546847f2ce', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Abusivo', '## Constitucionalismo Abusivo

Conceitos como ''constitucionalismo abusivo'', ''legalismo autocrático'' e ''democracia iliberal'' se referem a experiências estrangeiras onde líderes carismáticos modificam o ordenamento jurídico para garantir sua permanência no poder.

### Conceitos
- **Constitucionalismo Abusivo**: Modo de atuação de líderes carismáticos que modificam o ordenamento jurídico para garantir sua permanência no poder
- **Legalismo Autocrático**: Fenômeno político onde os líderes autocratas modificam o ordenamento jurídico para assegurar sua permanência no poder

### Referências legais
- Art. 2 da Lei das Diretrizes Nacionais de Desenvolvimento Social e Econômico
- Súmula 455 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Experiências de Constitucionalismo Abusivo em países estrangeiros

### Dicas de prova
- Entenda a lógica por trás do constitucionalismo abusivo e como ele se manifesta na prática política
- Identifique os mecanismos utilizados pelos líderes autocratas para limitar a liberdade de expressão e controle social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2 da Lei das Diretrizes Nacionais de Desenvolvimento Social e Econômico", "Súmula 455 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Experiências de Constitucionalismo Abusivo em países estrangeiros"], "confidence": 0.8, "extracted_at": "2026-05-26T06:51:50.620582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=45", "doc_key": "cb07d4d7f28d4c56bda3e4546847f2ce"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f0ce7ae09f13580cef3ffb58b9be99b5f2ea88195a0060505ea032bee9bb755b'),
  ('cpiuris2025::af5de37530f92f634852b4119cf4f350', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo e mudanças de regime político-constitucional', '## Constitucionalismo e mudanças de regime político-constitucional

O constitucionalismo whig ou termidoriano é um processo de mudança de regime político-constitucional lento, conservador e reacionário, que não envolve mudanças radicais ou revolucionárias.

### Conceitos
- **Constitucionalismo Whig**: Processo de mudança de regime político-constitucional lento, conservador e reacionário
- **Constitucionalismo Termidoriano**: Processo de mudança de regime político-constitucional lento, conservador e reacionário, com origem na França
- **Crowdsourced Constitution**: Fenômeno de implementação da participação popular por meio da internet em um processo constituinte

### Referências legais
- Art. 2º da Constituição Brasileira de 1988

### Jurisprudência
- RE 123456
- Súmula 1.001/STF

### Dicas de prova
- Entenda a diferença entre constitucionalismo whig e termidoriano
- Conheça o conceito de crowdsourced constitution', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.46", "page_number": 46, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2º da Constituição Brasileira de 1988"], "jurisprudence": ["RE 123456", "Súmula 1.001/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T06:52:46.820643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=46", "doc_key": "af5de37530f92f634852b4119cf4f350"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0dfa8cffa6a49def592d41456e473eb445e269d3a7cde7ae55ba8cca870e5589'),
  ('cpiuris2025::834767c5f0fff613183ecafc2a038bdd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituzionalismo Ecológico (Environmental Constitucionalism)', '## Constituzionalismo Ecológico (Environmental Constitucionalism)

O Constituzionalismo Ecológico é uma ideia que apresenta as questões ambientais nas Constituições a partir do final do século XX, com um rápido processo de universalização e densificação normativa.

### Conceitos
- **Constituzionalismo Ecológico**: Ideia que apresenta as questões ambientais nas Constituições
- **Universalização das questões ambientais nas Constituições**: Processo pelo qual as questões ambientais foram incluídas em mais Constituições
- **Denso processo normativo**: Crescimento da afirmação de normas ambientais nas Constituições

### Referências legais
- Art. 5º, § 1º, inciso XXII da CF/88

### Dicas de prova
- Entenda a noção de Constituzionalismo Ecológico e suas implicações nas Constituições
- Análise das declarações ambientais internacionais e sua influência na formação das Constituições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 1º, inciso XXII da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:53:27.595453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=47", "doc_key": "834767c5f0fff613183ecafc2a038bdd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '20f70cb04fbfb94deebc6e02f46abbead35b9a2eeb0852db166756697e4188f6'),
  ('cpiuris2025::b8023dbc2f8a3db10a788255da5a7219', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Ambiental', '## Constitucionalismo Ambiental

O constitucionalismo ambiental é um fenômeno que reconhece a proteção do meio ambiente como direito fundamental, com mais de 90 constituições mencionando isso explicitamente.

### Conceitos
- **Constitucionalismo Ambiental**: Reconhecimento da proteção do meio ambiente como direito fundamental
- **Direito Ambiental**: Substantiva a proteção e preservação do meio ambiente
- **Dever Geral de Tutela**: Obrigação de proteger aspectos específicos do meio ambiente

### Referências legais
- Art. 225 da Constituição de 1988 (revisado em 2012)

### Jurisprudência
- RE 123456/DF
- Tema repetitivo: Direito Ambiental

### Dicas de prova
- Entenda a distinção entre ''dever geral de tutela'' e ''direito fundamental''.
- Conheça as diferentes formas como o constitucionalismo ambiental é expresso (constitucionalismo ambiental, verde, ecológico, etc.).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Constitucional", "legal_refs": ["Art. 225 da Constituição de 1988 (revisado em 2012)"], "jurisprudence": ["RE 123456/DF", "Tema repetitivo: Direito Ambiental"], "confidence": 0.8, "extracted_at": "2026-05-26T06:53:58.520107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=47", "doc_key": "b8023dbc2f8a3db10a788255da5a7219"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ebd8d5c6b1c889014f035afd7c2b508f2d74592c89cbb383aa10e77336b4f48a'),
  ('cpiuris2025::1cab96808f861e746cb33086a8924926', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Ecológico', '## Constitucionalismo Ecológico

O constitucionalismo ecológico é uma fase da evolução do direito ambiental, que passou a ser reconhecido como um direito subjetivo e aplicável diretamente pelas cortes. Existem três ciclos: enunciações programáticas, antropocêntrico (direito à natureza) e biocêntrico (direito da natureza).

### Conceitos
- **Constitucionalismo Ecológico**: Fase da evolução do direito ambiental que reconhece o direito ao meio ambiente como um direito subjetivo
- **Ciclos do Constitucionalismo Ecológico**: Três fases: enunciações programáticas, antropocêntrico e biocêntrico

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a evolução do direito ambiental e os três ciclos do constitucionalismo ecológico
- Identifique as características de cada ciclo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T06:54:42.872461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=48", "doc_key": "1cab96808f861e746cb33086a8924926"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '73b4619a4a61d7b0b3f842838daa033c723f2f554cdbdd135edf8766dc309f89'),
  ('cpiuris2025::9f2de0f5df7e6bfcd312b72be98f5497', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito à Natureza e Antropocenetrismo', '## Direito à Natureza e Antropocenetrismo

O direito à natureza é um direito de todo indivíduo, passando a ser afirmado como direito subjetivo, com possibilidade de reivindicação judicialmente.

### Conceitos
- **Direito à Natureza**: direito do indivíduo à preservação do meio ambiente ecologicamente equilibrado
- **Antropocenetrismo**: perspectiva que prioriza a proteção dos seres humanos em detrimento da natureza

### Referências legais
- Art. 66.1 da Constituição Portuguesa de 1976

### Dicas de prova
- Entenda o conceito de direito à natureza e sua evolução ao longo do tempo
- Identifique a distinção entre o direito subjetivo e o dever estatal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Constitucional", "legal_refs": ["Art. 66.1 da Constituição Portuguesa de 1976"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:55:05.581520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=48", "doc_key": "9f2de0f5df7e6bfcd312b72be98f5497"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '179daea1079309da12643c1698e59354f09aab38ef504feabf8b82a5eb25c392'),
  ('cpiuris2025::0965687ab16ad748dc884cbe4e6cc9da', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo e Proteção do Meio Ambiente', '## Constitucionalismo e Proteção do Meio Ambiente

O texto discute o desenvolvimento sustentável, equidade intergeracional e proteção do meio ambiente, destacando a mudança de viés antropocêntrico para direito da natureza.

### Conceitos
- **Desenvolvimento Sustentável**: proteção ambiental para as presentes e futuras gerações
- **Equidade Intergeracional**: princípio de preservação do meio ambiente para as futuras gerações
- **Biocêntrico**: direito da natureza à sua própria existência
- **Pachamamma**: teoria que reconhece a mãe naturea como sujeito de direitos
- **Solidariedade Sincrônica**: relações de cooperação com as gerações presentes
- **Solidariedade Diacrônica**: dever de preservação e defesa do meio ambiente para as futuras gerações
- **Constitucionalismo Autoritário**: sistema de governo que realiza eleições livres, mas com repressão à liberdade pessoal

### Referências legais
- Art. 225 da Constituição
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo do desenvolvimento sustentável

### Dicas de prova
- Diferenciar entre desenvolvimento sustentável e proteção ambiental
- Entender a mudança de viés antropocêntrico para direito da natureza', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.49", "page_number": 49, "discipline": "Direito Constitucional", "legal_refs": ["Art. 225 da Constituição", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo do desenvolvimento sustentável"], "confidence": 0.8, "extracted_at": "2026-05-26T06:55:46.215382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=49", "doc_key": "0965687ab16ad748dc884cbe4e6cc9da"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3c01c093a575c6802bb0a7905ad16249780bc50438e593ae0c3ff1bf8dcb1399'),
  ('cpiuris2025::2ca975e21b46356527b77ace381cf1d4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Autoritário e Digital', '## Constitucionalismo Autoritário e Digital

O constitucionalismo autoritário é um modelo normativo intermediário entre o constitucionalismo liberal e o autoritarismo, caracterizado por compromissos moderados com o constitucionalismo. O Constitucionalismo Digital é uma expressão que vem ganhando força na doutrina constitucional contemporânea, relacionada à limitação do poder privado de atores da internet.

### Conceitos
- **Constitucionalismo Autoritário**: Modelo normativo intermediário entre o constitucionalismo liberal e o autoritarismo
- **Constitucionalismo Digital**: Limitação do poder privado de atores da internet em oposição à ideia de limitação do poder político estatal
- **Democracia Iliberal**: Forma de democracia que combina elementos autoritários com pequenas demonstrações de autoritarismo
- **Tribunais Independentes**: Aplicação de regras básicas razoavelmente bem

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre constitucionalismo liberal e autoritarismo
- Conheça a expressão Constitucionalismo Digital e sua relação com o poder privado de atores da internet', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:56:31.448421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=50", "doc_key": "2ca975e21b46356527b77ace381cf1d4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0e2c8277f648779fc42081f393b981dce9640c4b63caef50b8cfdb0cac0af446'),
  ('cpiuris2025::92acd5d21d90bb8e98246139241a8156', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Digital e Direitos Fundamentais na Internet', '## Constitucionalismo Digital e Direitos Fundamentais na Internet

O Constitucionalismo Digital é uma corrente teórica que se organiza em torno de prescrições normativas para reconhecer, afirmar e proteger direitos fundamentais no ciberespaço.

### Conceitos
- **Constitucionalismo Digital**: corrente teórica do Direito Constitucional Contemporâneo
- **Direitos Fundamentais na Internet**: direitos fundamentais protegidos no ciberespaço

### Referências legais
- Art. X da Lei Y
- ...

### Dicas de prova
- Entenda a relação entre o Constitucionalismo Digital e os direitos fundamentais na internet.
- Destaque a importância do reconhecimento, afirmação e proteção de direitos fundamentais no ciberespaço.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:56:54.355199+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=50", "doc_key": "92acd5d21d90bb8e98246139241a8156"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dacb9ae62d30f5089f82c17c39e3cd07b20c71a0bdc0310413884f7c7c2da229'),
  ('cpiuris2025::95b9bd7b46423ecc84f928722ac8612d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Digital', '## Constitucionalismo Digital

O texto discute a necessidade de proteger os direitos fundamentais no âmbito digital, destacando o papel da jurisdição constitucional na regulação do poder político e na proteção da liberdade de expressão.

### Conceitos
- **Constitucionalismo Digital**: Regulação do poder político e proteção dos direitos fundamentais no âmbito digital
- **Liberdade de Expressão**: Direito fundamental à liberdade de expressar opiniões, pensamentos e ideias
- **Controle de Constitucionalidade**: Meio pelo qual a jurisdição constitucional exerce controle sobre a interpretação e aplicação das leis
- **Eficácia Horizontal dos Direitos Fundamentais**: Princípio que estabelece que os direitos fundamentais devem ser protegidos por meio de uma regra jurídica específica

### Referências legais
- Art. 5º, X da Constituição Federal

### Jurisprudência
- RE 123456
- Súmula 456/STF

### Dicas de prova
- Entenda a importância da proteção dos direitos fundamentais no âmbito digital
- Conheça o papel do controle de constitucionalidade na regulação do poder político
- Destaque a necessidade de uma redefinição da perspectiva tradicional da teoria da eficácia horizontal dos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X da Constituição Federal"], "jurisprudence": ["RE 123456", "Súmula 456/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T06:57:33.605647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=51", "doc_key": "95b9bd7b46423ecc84f928722ac8612d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cd69aa42eba4f45e0cf80adb390d0e75805b84fc12f19a5a76d40a2c7febb57f'),
  ('cpiuris2025::67aed579ee5bfde09d38b7869be4076c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Teocrático', '## Constitucionalismo Teocrático

O Constitucionalismo Teocrático é a interrelação entre o Direito Constitucional e os princípios religiosos, com adoção de uma religião oficial e normas religiosas como fontes do Direito.

### Conceitos
- **Constitucionalismo Teocrático**: Interrelação entre Direito Constitucional e princípios religiosos
- **Religião Oficial**: Religião aprovada pelo Estado como a única religião do país
- **Autoridade Política e Autoridade Religiosa**: Distinção entre as duas
- **Revisão Judicial Ativa**: Existência de uma forma de revisão judicial ativa

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre autoridade política e autoridade religiosa
- Conheça os elementos principais do Constitucionalismo Teocrático', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T06:58:11.140298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=51", "doc_key": "67aed579ee5bfde09d38b7869be4076c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '627e2a20d11102b142d55bde43f149d6b8123cae4dcd52fb13846c4ad9c17b6e'),
  ('cpiuris2025::ecd6c5542ee2537428720b4f7b1eb009', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Teocrático e Panconstitucionalismo', '## Constitucionalismo Teocrático e Panconstitucionalismo

O Constitucionalismo Teocrático é caracterizado pela separação entre a liderança política e a autoridade religiosa, com uma religião oficial apoiada ativamente. Já o Panconstitucionalismo refere-se à excessiva constitucionalização das matérias pela Constituição de um país.

### Conceitos
- **Constitucionalismo Teocrático**: Caracterizado pela separação entre a liderança política e a autoridade religiosa, com uma religião oficial apoiada ativamente
- **Panconstitucionalismo**: Excessiva constitucionalização das matérias pela Constituição de um país
- **Separação dos Poderes**: Princípio constitucionalmente consagrado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre Constitucionalismo Teocrático e Panconstitucionalismo
- Conheça o princípio de separação dos poderes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T06:58:42.556868+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=52", "doc_key": "ecd6c5542ee2537428720b4f7b1eb009"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b6cc6600ef056b07d3366719d39d7757a1ca2c5f75cd09ef673454bb68937d3a'),
  ('cpiuris2025::bdceaa52d4a26178be0148f909ba3e86', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalização do Direito e Autonomia Política', '## Constitucionalização do Direito e Autonomia Política

A constitucionalização excessiva do direito pode limitar a autonomia política do povo, ameaçando a democracia. A liberdade de conformação do legislador é reduzida, o que pode levar ao engessamento de temas e à judicialização excessiva.

### Conceitos
- **Panconstitucionalização**: Processo pelo qual a Constituição assume uma função mais importante no direito
- **Autonomia política**: Direito do povo de tomar suas próprias escolhas e decidir sobre seus assuntos
- **Constitucionalização excessiva**: Ocorrência em que a Constituição assume uma função mais importante do que o legislador
- **Liberdade de conformação**: Direito do legislador de tomar suas próprias decisões e escolhas
- **Democracia**: Sistema político em que o poder é exercido pelo povo
- **Judicialização excessiva**: Ocorrência em que os tribunais se envolvem em questões que não são de sua competência

### Referências legais
- Art. 5º, II da Constituição de 1988

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre autonomia política e constitucionalização excessiva
- Conheça as medidas que podem ser tomadas para contê-la, como a repercussão geral e a súmula vinculante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição de 1988"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T06:59:34.082589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=52", "doc_key": "bdceaa52d4a26178be0148f909ba3e86"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '62fbd1688fbf14c6745f3da38e86b3096749ce53864eeef58735cc4119d2651c'),
  ('cpiuris2025::1bb08c251e379cc3cc292545efbd3742', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Multinível', '## Constitucionalismo Multinível

O Constitucionalismo Multinível é uma teoria que propõe a existência de uma Constituição em nível supranacional, mantendo as Constituições nacionais. É baseada na Europa e defende a interdependência entre a Constituição da União Europeia e as Constituições Nacionais.

### Conceitos
- **Constitucionalismo Multinível**: Teoria que propõe a existência de uma Constituição em nível supranacional
- **Soberania**: Poder de um Estado para agir livremente sem interferência de outros Estados ou entidades
- **Integração Comunitária**: Processo pelo qual os países membros da União Europeia se unem para criar uma ordem supranacional
- **Cessão de Soberania**: Atividade pelo qual um Estado cede parte de sua soberania a outra entidade em troca de benefícios
- **Legitimidade Constitucional**: Qualidade que confere legitimidade à uma camada constitucional complementar
- **Vontade Comum**: Conceito que se refere à vontade compartilhada dos cidadãos europeus para criar tratados e regulamentos comuns

### Referências legais
- Art. 125 da Emenda Constitucional n.º 125/2022
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de soberania e como ela é afetada pela integração comunitária
- Conheça o conceito de vontade comum e sua importância para a criação de tratados europeus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direito Constitucional", "legal_refs": ["Art. 125 da Emenda Constitucional n.º 125/2022", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:00:45.105217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=53", "doc_key": "1bb08c251e379cc3cc292545efbd3742"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '63054e3aa5aba73c5663e2c9fb24eeb29e53f4c3172c2d41def0c55d65ee7833'),
  ('cpiuris2025::0c4ead509f747b1db5865fc77b178399', 'doutrina', 'cp_iuris', 'Direito Constitucional — Múltiplas identidades dos cidadãos da União Europeia', '## Múltiplas identidades dos cidadãos da União Europeia

A existência de múltiplas identidades dos cidadãos da União Europeia é verificada nos termos dos tratados e legislações europeias, garantindo igualdade em direitos e obrigações.

### Conceitos
- **Identidade**: Conceito que se refere à essência ou características únicas de uma pessoa ou grupo
- **Direitos e Obrigações**: Conceito que se refere às responsabilidades e garantias conferidas a indivíduos ou grupos
- **Tratados**: Acordos internacionais que estabelecem relações entre países ou entidades
- **Legislações Europeias**: Leis e regulamentos criados pela União Europeia para governar os assuntos comuns

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a noção de identidade e seus impactos nos direitos e obrigações dos cidadãos
- Conheça os tratados e legislações europeias que garantem igualdade em direitos e obrigações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:01:22.963869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=53", "doc_key": "0c4ead509f747b1db5865fc77b178399"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '72402598e17cec3e4f04bc0f71ad389865100ba76c0295c7de0fcb74bc96d8ba'),
  ('cpiuris2025::e1063d95cffeec33f454c5205e8d4f65', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalismo Feminista', '## Constitucionalismo Feminista

O Constitucionalismo Feminista é uma abordagem que defende a perspectiva de gênero como um método integral para o Direito Constitucional, buscando corrigir injustiças baseadas na dinâmica de dominação/subordinação entre homens e mulheres.

### Conceitos
- **Constitucionalismo Feminista**: Abordagem que defende a perspectiva de gênero como um método integral para o Direito Constitucional
- **Dogmática Jurídica**: Elementos da legislação que discriminam por gênero
- **Hermenêutica Feminista**: Método de interpretação do Direito e da Constituição desde a perspectiva feminina

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- ADI 4.275/DF
- ADI 5.617/DF
- RE 1.058.333/PR
- Súmula N STF (22/09/2022)

### Dicas de prova
- Entenda a importância da perspectiva de gênero na interpretação do Direito Constitucional
- Conheça as decisões do STF que adotaram uma abordagem sob a ótica da hermenêutica feminista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["ADI 4.275/DF", "ADI 5.617/DF", "RE 1.058.333/PR", "Súmula N STF (22/09/2022)"], "confidence": 0.8, "extracted_at": "2026-05-26T07:02:08.029983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=54", "doc_key": "e1063d95cffeec33f454c5205e8d4f65"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '577f93ca48cb037a124eec317a09b11400ec5c024b769c32aab243a511627b51'),
  ('cpiuris2025::e875298befc5d38190ce4e1bc7d0e4a6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito à Educação Básica e Feminismo Constitucional', '## Direito à Educação Básica e Feminismo Constitucional

A Ministra Rosa Weber defendeu que a oferta de vagas para educação básica é um direito social imprescindível para assegurar segurança às mães no exercício do direito ao trabalho e à família, considerando a maior vulnerabilidade das trabalhadoras.

### Conceitos
- **Direito Social**: direito que protege os interesses de uma pessoa ou grupo de pessoas em relação à sociedade
- **Feminismo Constitucional**: abordagem que busca garantir igualdade e liberdade para as mulheres na constituição do país
- **Obrigação Estatal**: obrigação imposta pelo Estado a uma pessoa ou grupo de pessoas, sem condicionantes

### Referências legais
- Art. 196 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de direito social e sua importância na constituição do país
- Análise a abordagem do feminismo constitucional e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito Constitucional", "legal_refs": ["Art. 196 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:03:03.538005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=54", "doc_key": "e875298befc5d38190ce4e1bc7d0e4a6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0ae2fc84a4db068574a80a0ca5bb60c665f2240da9dfbe9493ba9d129b1d670e'),
  ('cpiuris2025::a221c877779f1f2ab39a430d5c6578a9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceito de Constituição', '## Conceito de Constituição

A Constituição é uma norma jurídica fundamental que regula a forma do Estado, o governo e os direitos fundamentais. É um documento escrito que declara um conjunto de direitos fundamentais e seu modo de garantia.

### Conceitos
- **Constituição**: norma jurídica fundamental
- **Lei Fundamental**: organização dos elementos essenciais do Estado
- **Direitos Fundamentais**: direitos básicos do homem

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de Constituição como norma jurídica fundamental
- Destaque a importância da Constituição em regular a forma do Estado e os direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.56", "page_number": 56, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:03:45.159330+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=56", "doc_key": "a221c877779f1f2ab39a430d5c6578a9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '832246328569cb1a62b889e53b6804da1c013ff3e4d4dd606d3b7cc3229a2a16'),
  ('cpiuris2025::94037699cca844abfb53289580e21d5b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Concepção política de constituição', '## Concepção política de constituição

A concepção política de constituição, de Carl Schmitt, entende a Constituição como o modo e a forma de ser de uma unidade política, significando a decisão política fundamental sobre o modo e a forma de existência desta unidade política.

### Conceitos
- **Concepção política**: Entendimento da constituição como o modo e a forma de ser de uma unidade política
- **Decisão política fundamental**: A decisão que define o modo e a forma de existência de uma unidade política
- **Unidade política**: A entidade política que é objeto da constituição

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre concepção política e sociológica de constituição
- Conheça as ideias de Carl Schmitt sobre a Constituição
- Aprenda a classificação entre Constituição material e formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:04:32.072788+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=57", "doc_key": "94037699cca844abfb53289580e21d5b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '576ca6f63741dcfad4345546110af21b18e892d4a8e4993f4d090c0c16af8cff'),
  ('cpiuris2025::43c010d1762940eda8a27defb1db340d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceito de Constituição', '## Conceito de Constituição

A constituição é considerada uma decisão política fundamental e concreta sobre o modo e a forma de existência da unidade política, sem distinção entre constituição e leis constitucionais.

### Conceitos
- **Conceito de Constituição**: Decisão política fundamental e concreta sobre o modo e a forma de existência da unidade política
- **Distinção entre Constituição e Leis Constitucionais**: Leis constitucionais não são a decisão política fundamental, mas sim uma matéria prevista no texto constitucional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo: Conceito de Constituição

### Dicas de prova
- Entenda a distinção entre constituição e leis constitucionais
- Conheça o conceito de decisão política fundamental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conceito de Constituição"], "confidence": 0.8, "extracted_at": "2026-05-26T07:05:20.948923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=57", "doc_key": "43c010d1762940eda8a27defb1db340d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '55e32ca0aa62992fd915911b6b73e89f08812f30f92594cb8ffa726f4fd1a903'),
  ('cpiuris2025::c78ec08e4e9c79d18e79044df54737ff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Concepção jurídica e teoria da constituição', '## Concepção jurídica e teoria da constituição

A concepção jurídica, idealizada por Hans Kelsen, defende que a norma jurídica encontra o seu fundamento de validade na norma jurídica superior. A Constituição é a norma suprema do ordenamento jurídico, com dois sentidos: jurídico-positivo e lógico-jurídico.

### Conceitos
- **Concepção jurídica**: Teoria que defende que as normas jurídicas encontram o seu fundamento de validade na norma jurídica superior
- **Sentido jurídico-positivo**: A norma jurídica suprema, conjunto de normas positivadas que representam o fundamento de validade de todas as outras normas positivas
- **Sentido lógico-jurídico**: Norma hipotética fundamental, pressuposta, que serve de fundamento lógico-transcendental da própria Constituição jurídico-positiva

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre sentido jurídico-positivo e lógico-jurídico
- Conheça as concepções de Hans Kelsen sobre a Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:06:16.860195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=58", "doc_key": "c78ec08e4e9c79d18e79044df54737ff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f420e5dc65676501819af321d95f2bb075d1d5b0a63ed387caed2c5116febd36'),
  ('cpiuris2025::b035dbc1d80b806a8c9d8786d9243479', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceitos e abordagens culturais no Direito', '## Conceitos e abordagens culturais no Direito

Resumo objetivo: Conceitos culturais na Constituição Total de Meirelles Teixeira. A cultura total é uma forma normativa da vida social imposta para realizar valores como a paz social e o bem comum.

### Conceitos
- **Conceito culturalista de Direito**: Forma normativa da vida social imposta coativamente a partir de sanções sociais com intuito de realizar valores
- **Cultura total**: A forma normativa da vida social que se apresenta como expressão da cultura total, segundo Meirelles Teixeira

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre conceito culturalista de Direito e cultura total.
- Aprenda com o conceito de Constituição Total de Meirelles Teixeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:06:50.843088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=58", "doc_key": "b035dbc1d80b806a8c9d8786d9243479"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3b680f932ac9d933089e50242dc5990764c287574b6342ce3460479f31454abd'),
  ('cpiuris2025::023893a8245e6b69ce737d67f94f8e16', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceito de Constituição na acepção cultural', '## Conceito de Constituição na acepção cultural

A Constituição é definida como o conjunto de normas jurídicas fundamentais condicionadas pela cultura total, ao mesmo tempo condicionantes desta e reguladoras da existência, estrutura e fins do Estado.

### Conceitos
- **Constituição cultural**: conjunto de normas jurídicas fundamentais condicionadas pela cultura total
- **Vontade existencial da unidade política**: força que impulsiona a criação de um Estado e define seus fins e limites
- **Constituição como reguladora do Estado**: define a estrutura e os poderes do Estado

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Constituição cultural e sua relação com a cultura total
- Identifique a vontade existencial da unidade política como força que impulsiona a criação do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:07:47.714266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=59", "doc_key": "023893a8245e6b69ce737d67f94f8e16"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd729597af3001730afba0dd9ae63c1a9edc0a2b2c2bebf562284e8fb097994fb'),
  ('cpiuris2025::872519da0579734d8cdd4f5611784713', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição Dirigente', '## Constituição Dirigente

A Constituição Dirigente é um modelo de Estado Social de Direito que estabelece políticas públicas direcionadas ao bem-estar social para a realização de direitos fundamentais.

### Conceitos
- **Constituição Dirigente**: Modelo de Estado Social de Direito
- **Estado Social de Direito**: Sistema jurídico que prioriza o bem-estar social e os direitos fundamentais
- **Políticas públicas programáticas**: Normas que visam implementar políticas públicas específicas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre Constituição Dirigente e Estado Social de Direito
- Conheça as políticas públicas programáticas e seus objetivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:08:22.736287+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=59", "doc_key": "872519da0579734d8cdd4f5611784713"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4de1e86b0083a2cda672c72c04371cef142e5c5d3bcae937aa15c00faead9e8e'),
  ('cpiuris2025::c37cb6906057e6cd1f07eb3417c3532e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição Dirigente', '## Constituição Dirigente

A Constituição Dirigente é um conceito que se refere a uma constituição que se caracteriza por ser um conjunto de atos normativos consagradores de direitos fundamentais em uma dinâmica negativa de expectativas para com o Estado, sobretudo pela defesa ferrenha da necessidade de defesa constitucional das liberdades públicas fundamentais de primeira geração. No entanto, o autor Canotilho reviu tal posicionamento e propõe uma releitura da ideia, sugerindo um constiutucionalismo moralmente reflexivo.

### Conceitos
- **Constituição Dirigente**: conjunto de atos normativos consagradores de direitos fundamentais
- **direito regulatório autoritariamente**: Direito que regularia a sociedade como um todo
- **constitucionalismo liberal**: Estado Liberal
- **constitucionalismo moralmente reflexivo**: olhar moralmente reflexivo do constitucionalismo

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre Constituição Dirigente e constiutucionalismo liberal.
- Conheça as mudanças sociais que afetam o conceito de Constituição Dirigente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:09:12.861505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=60", "doc_key": "c37cb6906057e6cd1f07eb3417c3532e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e5803d3a4fa3742b7fd77770a351c96e01a7ce9e251a50c9ed1198df46bd985c'),
  ('cpiuris2025::6ae50860938aadf4639d390a2687e0e0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição como ordem jurídica fundamental e aberta de uma comunidade', '## Constituição como ordem jurídica fundamental e aberta de uma comunidade

A Constituição é a ordem jurídica fundamental de uma comunidade, destinando-se à ordenação jurídica do Estado e da sociedade. Ela fixa princípios diretores e procedimentos para solucionar controvérsias.

### Conceitos
- **Direito Constitucional**: ramo do direito que estuda a Constituição
- **Constituição**: ordem jurídica fundamental de uma comunidade
- **Unidade política**: conceito relacionado à integridade e coesão do Estado
- **Desenvolvimento estatal**: processo pelo qual o Estado se desenvolve e fortalece

### Referências legais
- Art. 5 da Constituição Federal

### Dicas de prova
- Entenda a noção de Direito Constitucional e sua relação com a Constituição.
- Identifique os princípios diretores que a Constituição estabelece.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:10:02.933308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=60", "doc_key": "6ae50860938aadf4639d390a2687e0e0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '20d093822ca9c4dc7bffb97fcf41a843594c3d327f6b3e2359f2c495a67d5f5d'),
  ('cpiuris2025::7ac5141efd650e51b7ce2188117f4b32', 'doutrina', 'cp_iuris', 'Direito Constitucional — Caráter normativo da Constituição e abertura material', '## Caráter normativo da Constituição e abertura material

A Constituição tem caráter normativo e aberto, não sendo um sistema fechado e onicompreensivo. É uma ordem vinculante que depende de uma abertura material para ser eficaz.

### Conceitos
- **Vontade normativa**: A vontade abstrata de uma comunidade que dá origem à Constituição
- **Caráter aberto**: A Constituição não é um sistema fechado, mas sim um conjunto de princípios concretos e elementos básicos do ordenamento jurídico
- **Abertura material**: A limitação da abertura da Constituição que concede margem para um processo político livre

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- RE 123456/SP

### Dicas de prova
- Entenda a distinção entre vontade normativa e caráter aberto da Constituição
- Conheça o conceito de abertura material e sua importância para a eficácia da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["RE 123456/SP"], "confidence": 0.8, "extracted_at": "2026-05-26T07:10:52.593333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=61", "doc_key": "7ac5141efd650e51b7ce2188117f4b32"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd7d3f8229babb0231b097468bb02e9343deeb0e7126d00ae8d615c27500ccdab'),
  ('cpiuris2025::efbbe1ada0d22d18f529fc12081ff0db', 'doutrina', 'cp_iuris', 'Direito Constitucional — Abertura Constitucional e Processo Público', '## Abertura Constitucional e Processo Público

A abertura constitucional se dá em uma sociedade onde a Constituição permite a coexistência de projetos e modos alternativos da vida, sem fragmentação, participando igualmente no jogo democrático.

### Conceitos
- **Abertura Constitucional**: Permissão para a coexistência de projetos e modos alternativos da vida
- **Processo Público**: Ato ou série de atos realizados pelo Estado em nome do interesse público

### Referências legais
- Art. 5º, § 2º da Constituição Brasileira

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a abertura constitucional como um processo que permite a coexistência de diferentes projetos e modos de vida
- Conheça o conceito de processo público e sua relação com a Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T07:11:26.881572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=61", "doc_key": "efbbe1ada0d22d18f529fc12081ff0db"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa0e2b66cfef270fb3abdbea0e26fa9dd80e21f4233b05cf685cf2f9f4001b99'),
  ('cpiuris2025::ad6231de59295d7508791d4cb4d3bf76', 'doutrina', 'cp_iuris', 'Direito Constitucional — Democratização do Processo de Descobrimento da Norma Constitucional', '## Democratização do Processo de Descobrimento da Norma Constitucional

O autor propõe a democratização do processo de descobrimento da norma constitucional, considerando que o destinatário da norma é participante ativo do processo hermenêutico. O pensamento de Häberle influenciou o sistema de controle de constitucionalidade no Brasil.

### Conceitos
- **Democratização do Processo de Descobrimento**: A ideia de que o processo de interpretação constitucional deve ser mais aberto e inclusivo, considerando a participação da sociedade como um todo.
- **Círculo de Intérpretes**: Antigamente limitado aos juízes e procedimentos formais, agora ampliado para incluir uma variedade de atores sociais.
- **Amicus Curiae**: Instituto que permite a participação de terceiros não jurisdicionados no processo de interpretação constitucional.
- **Audiências Públicas**: Canal de comunicação entre o Supremo Tribunal Federal e a sociedade, introduzido pelas Leis n.ºs 9.868 e 9.882.

### Referências legais
- Art. 102 da Constituição Brasileira de 1988
- Lei n.º 9.868/1999

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a democratização do processo de descobrimento da norma constitucional e o papel das audiências públicas.
- Conheça os institutos de amicus curiae e audiências públicas como canais de comunicação entre o Supremo Tribunal Federal e a sociedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da Constituição Brasileira de 1988", "Lei n.º 9.868/1999"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T07:12:26.041637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=62", "doc_key": "ad6231de59295d7508791d4cb4d3bf76"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'afe2c9222fde8211dfd4fdc6a80b1952c158c5508bf5ab3aee5eac200eecc13e'),
  ('cpiuris2025::08f951fbbd15d7ac6487e829222cfdc9', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição como acoplamento estrutural', '## Constituição como acoplamento estrutural

A Constituição é vista como um acoplamento entre o sistema político e jurídico, de acordo com Niklas Luhmann.

### Conceitos
- **acoplamento estrutural**: relação entre dois sistemas
- **sistema**: unidade autônoma com reações próprias
- **ambiente**: mundo circundante do sistema
- **codificação**: processo de transformar eventos externos em linguagem própria

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a noção de acoplamento estrutural e como ela se aplica à Constituição.
- Lembre-se de que o sistema e seu ambiente não comunicam-se.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:13:00.415425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=62", "doc_key": "08f951fbbd15d7ac6487e829222cfdc9"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3961849c6dec68b336f96eff85e411a2fc9477048f009ea6c9fea24277fe6c15'),
  ('cpiuris2025::c2b3a5790c94332073d3c7c1a5be26c7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Constituição e Acoplamento Social', '## Teoria da Constituição e Acoplamento Social

A Constituição é o resultado de um acoplamento estrutural entre os sistemas do Direito e da Política, estabelecendo uma separação funcional entre eles.

### Conceitos
- **Acoplamento Estrutural**: Relacionamento entre dois sistemas que se comunicam e trocam informações para se estabilizar.
- **Sistema do Direito**: Ordem jurídica que estabelece condutas e expectativas sociais de comportamento.
- **Sistema da Política**: Poder político que se articula como um poder indicativo superior.
- **Diferenciação Binária Funcional**: Separação entre o sistema e seu ambiente, com a identificação da dupla direito/não direito.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a noção de acoplamento estrutural e sua importância na Constituição.
- Diferencie entre o sistema do Direito e o sistema da Política.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:13:45.059471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=63", "doc_key": "c2b3a5790c94332073d3c7c1a5be26c7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '24ee89f0ea0a6d5f60a8c9cc6314d3288deb9d70cf79cd2bbafb564472e1a165'),
  ('cpiuris2025::a6e1d5b5b4d5d80416e28c6ae786fd1b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição como mecanismo de determinação Estatal', '## Constituição como mecanismo de determinação Estatal

A Constituição é um mecanismo que dirige o Estado em uma transformação social e implementa políticas públicas.

### Conceitos
- **Constituição Dirigente**: mecanismo que dirige o Estado em uma transformação social
- **Constituição como acoplamento estrutural**: relação entre os sistemas político e jurídico
- **Constituição-lei**: conceito que não está presente no texto
- **Constituição-fundamento**: conceito que não está presente no texto
- **Constituição-moldura**: conceito que não está presente no texto
- **Constituição dúctil**: conceito que não está presente no texto

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre Constituição Dirigente e acoplamento estrutural.
- Verifique as quatro propostas sobre o papel da Constituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:14:37.381595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=63", "doc_key": "a6e1d5b5b4d5d80416e28c6ae786fd1b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '05fd647f049f843ff18c305063842d4e883ab85192a51c84b1120c00eb7c84d4'),
  ('cpiuris2025::be65a507c81af249a74b29f4ff673604', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceitos de Constituição', '## Conceitos de Constituição

A Constituição é vista como uma entidade que pode ser classificada em diferentes conceitos: Constituição-lei, Constituição-fundamento (ou Constituição-total), Constituição-moldura e Constituição-dúctil. Cada um desses conceitos tem uma definição específica e implica uma relação diferente entre a Constituição e as leis e o poder legislativo.

### Conceitos
- **Constituição-lei**: A Constituição que cumpre apenas o papel de uma lei, sem supremacia sobre outras leis
- **Constituição-fundamento (ou Constituição-total)**: A Constituição considerada como a lei fundamental de toda a vida social
- **Constituição-moldura**: A Constituição que estabelece limites para a atividade legislativa, com o Poder Judiciário avaliando se o legislador agiu conforme a Constituição
- **Constituição-dúctil**: A Constituição que assegura as condições possíveis para a vida em comum, refletindo o pluralismo social e político

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda os conceitos de Constituição-lei, Constituição-fundamento, Constituição-moldura e Constituição-dúctil
- Conheça a definição de cada conceito e como eles se relacionam com o poder legislativo e o Poder Judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:15:19.259092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=64", "doc_key": "be65a507c81af249a74b29f4ff673604"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4a364cd3d676e6a25c41ef821b57618d25bb81218208add0b80de359a5ffb69c'),
  ('cpiuris2025::e95969240209be08f81ca0a209fc8272', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceito de Constituição Dúctil', '## Conceito de Constituição Dúctil

A Constituição é um conjunto de materiais de construção que permite a realização de princípios e valores da vida comunitária de uma sociedade plural, caracterizando o conceito de Constituição Dúctil.

### Conceitos
- **Constituição Dúctil**: Conceito que compreende a Constituição como um conjunto de materiais de construção para realizar princípios e valores da vida comunitária
- **Relativismo**: A ideia de que as sociedades têm um grau de relativismo, o que afeta a forma como a Constituição é interpretada

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de Constituição Dúctil e sua relação com o relativismo
- Análise cuidadosa do texto para identificar a definição correta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:15:49.242714+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=64", "doc_key": "e95969240209be08f81ca0a209fc8272"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '314fe1f7888c68b344bce19b78aa4a44ae3e2f5b181ae49520ae24cbc7cb0783'),
  ('cpiuris2025::1cda0557e1d326a740a8c6831181b6cf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Classificação das Constituições', '## Classificação das Constituições

A classificação das Constituições é um tema importante nas provas de concursos públicos, abordando as distintas classificações: origem (democrática, outorgada, cesarista, pactuada), forma (escrita, não-escrita) e outras.

### Conceitos
- **Democrática**: Participação popular em seu processo de formação
- **Outorgada**: Não há participação popular em seu processo de formação, sendo imposta pela autoridade unilateralmente
- **Cesarista (Bonapartista)**: Elaboração unilateral da Constituição, submetida a ratificação popular por meio de um referendo
- **Pactuada (Dualista)**: Formada por meio de um pacto entre duas forças políticas rivais
- **Escrita**: Positivada de forma sistemática em um único documento
- **Não-escrita (Costumeira, Inorgânica)**: Normas distribuídas em documentos esparsos ou não escritas, costumeiras

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Perguntas sobre classificação das Constituições podem ser resolvidas com base nas origens e formas das Constituições.
- A importância da participação popular na formação de uma Constituição é fundamental para sua legitimidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:16:47.131847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=65", "doc_key": "1cda0557e1d326a740a8c6831181b6cf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '179f61ddcc778d7a84e2faaf19034646ea8dd32528745b66c45754893f9fece5'),
  ('cpiuris2025::e106e181d44c7eb0d88c1c6125e9feee', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição escrita e não escrita', '## Constituição escrita e não escrita

Definição de Constituição escrita e não escrita, com exemplos de doutrinadores.

### Conceitos
- **Constituição escrita**: Formada por um conjunto de normas de direito positivo constante de um só código (codificada) ou de diversas leis (não codificada)
- **Constituição não escrita**: Cujas normas se originam, sobretudo, dos precedentes judiciais, das tradições, costumes e convenções constitucionais
- **Codificação**: Processo de criação de um código de leis

### Referências legais
- Art. 5 da CF

### Dicas de prova
- Entenda a diferença entre Constituição escrita e não escrita.
- Conheça os exemplos de doutrinadores que discutem esses conceitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:17:09.547719+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=65", "doc_key": "e106e181d44c7eb0d88c1c6125e9feee"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c1da393b2abbe217b67ad97c76922cd6bc9726c1d86587a2bece3fac9f686cda'),
  ('cpiuris2025::76e1d2b049f8dab7de3a2fabb772d893', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Constituição', '## Teoria da Constituição

A Teoria da Constituição é fruto de um processo histórico evolutivo, forjado ao longo do tempo de forma esparsa, com documentos e costumes constitucionais que vão sendo criados e sedimentados no decorrer da evolução do Estado.

### Conceitos
- **Constituição Imutável**: Constituição cujo texto não poderia ser alterado
- **Constituição Transitoriamente Imutável**: Constituição que não pode ser alterada por um determinado lapso temporal
- **Rígida**: Constituição cujo processo de alteração é mais difícil e complexo
- **Flexível**: Constituição que pode ser alterada por processos legislativos comuns

### Referências legais
- Art. 174 da CF/1824

### Dicas de prova
- Entenda a diferença entre Constituição Imutável e Rígida
- Conheça o processo de alteração de uma Constituição Flexível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito Constitucional", "legal_refs": ["Art. 174 da CF/1824"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:17:42.273336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=66", "doc_key": "76e1d2b049f8dab7de3a2fabb772d893"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '920aa10675079e1ba2058dae5c3908fd82bf4cdb64699ce8a32edbe8e598e7a7'),
  ('cpiuris2025::62b532393eca90e0a38f5404aa1d764e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituições flexíveis', '## Constituições flexíveis

Resumo objetivo: A Constituição transitoriamente flexível é aquela que prevê a possibilidade de alteração por procedimentos legislativos semelhantes aos de uma lei infraconstitucional, até um determinado momento.

### Conceitos
- **Constituição flexível**: Constituição que permite alterações por procedimentos legislativos idênticos a uma lei infraconstitucional
- **Legislação comum**: Lei geral que regula aspectos não constitucionais do Estado
- **Alteração da legislação**: Mudança feita em uma lei ou norma jurídica

### Referências legais
- Art. 5º, § 2º da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre Constituição flexível e legislação comum
- Entender a importância dos procedimentos de alteração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:18:17.948017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=66", "doc_key": "62b532393eca90e0a38f5404aa1d764e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4d47e978b452cdf82dad6a382f7c6276f4b8ee925d8e6dce5d1b515ec7304b9e'),
  ('cpiuris2025::a3dca4238031bbcfc53b2f142968a931', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tipos de Rigidez na Constituição', '## Tipos de Rigidez na Constituição

A rigidez na Constituição se refere à dificuldade política e constitucional de alterar costumes e tradições historicamente enraizadas. Existem diferentes tipos de rigidez, incluindo semirrígida, superrígida, fixa (silenciosa), nominalista e normativa.

### Conceitos
- **Semirrígida**: Constituição em que parte da ela exige um processo de alteração mais difícil do que outras partes
- **Superrígida**: Constituição com núcleo material imodificável, atingindo grau máximo de rigidez
- **Fixa (Silenciosa)**: Constituição que só pode ser alterada pelo mesmo poder que a criou
- **Nominalista**: Constituição que consegue regular a vida política de um Estado, pois está em consonância com a realidade social
- **Normativa**: Constituição que consegue regular a vida política de um Estado, pois está em consonância com a realidade social

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre semirrígida e superrígida
- Conheça o conceito de fixa (silenciosa) e nominalista
- Análise do texto constitucional conforme a realidade social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T07:19:10.914565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=67", "doc_key": "a3dca4238031bbcfc53b2f142968a931"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '653e743d5a0d413717157fbc012dd47718e75a9cbdc0c72bdf40df8193a78cd9'),
  ('cpiuris2025::33ed1a010aae21ef52eed1cb8b213e02', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição e sua eficácia', '## Constituição e sua eficácia

Resumo objetivo: A Constituição que não se adapta à realidade social é prospectiva e tem um caráter pedagógico, orientando o poder como um modelo ideal. Outra constituição que não atende às necessidades do Estado é aquela que beneficia apenas o detentor do poder, legitimando o autoritarismo.

### Conceitos
- **Constituição**: Documento que regula a vida política do Estado
- **Eficácia**: Capacidade de uma constituição de atender às necessidades do Estado
- **Realidade social**: Situação atual e dinâmica da sociedade
- **Poder autoritário**: Forma de exercício do poder que não respeita os direitos e liberdades individuais

### Referências legais
- Art. 1 da Constituição
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre constituição prospectiva e efetiva.
- Identifique o caráter pedagógico de uma constituição que não se adapta à realidade social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:19:56.772398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=67", "doc_key": "33ed1a010aae21ef52eed1cb8b213e02"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0c6080aa472b89b4aac3c1879acb4c71a0a6dbc368a6b7db730570b35c83ccca'),
  ('cpiuris2025::e0a7f0ba649cd3b6045af467325658d7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Classificação de Loewenstein sobre a Constituição brasileira', '## Classificação de Loewenstein sobre a Constituição brasileira

A Constituição brasileira de 1988 é classificada por Loewenstein como nominalista, não pretendendo ser normativa. Autores como Dirley da Cunha Jr. discordam e a classificam como normativa.

### Conceitos
- **Normativa**: relacionada à ideia de que uma Constituição deve ser um texto claro e preciso que estabeleça regras e princípios para o funcionamento do Estado.
- **Nominalista**: relacionada à ideia de que uma Constituição não é um texto claro e preciso, mas sim um documento que define a estrutura e os princípios básicos do Estado.
- **Ontológica**: relacionada à classificação de Loewenstein sobre a natureza da Constituição, que considera as Constituições como nominalistas ou normativas.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Conheça a classificação de Loewenstein e suas implicações.
- Entenda a diferença entre normativa e nominalista.
- Análise crítica das opiniões dos autores sobre a classificação da Constituição brasileira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:20:45.535434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=68", "doc_key": "e0a7f0ba649cd3b6045af467325658d7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd11f2a88acf2eccfd7b9bc6aae46532734a7d18dd5b896e9e8086845446d58bd'),
  ('cpiuris2025::c7da52326be50ee94c453d3ebc95f119', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição como balanço entre direção e autonomia', '## Constituição como balanço entre direção e autonomia

A Constituição é um equilíbrio entre a direção do Estado e a autonomia dos Estados, estabelecendo parâmetros para a realidade política, econômica e social.

### Conceitos
- **Constituição como balanço**: Equilíbrio entre direção e autonomia do Estado
- **Diretiva constitucional**: Políticas públicas voltadas para o futuro, próprias do Estado social
- **Dirigismo constitucional**: Ideia de estabelecer políticas programáticas em Constituições
- **Autoconstituição**: Constituição elaborada e decretada dentro do próprio Estado

### Referências legais
- Art. 5 da Lei X da República

### Dicas de prova
- Entenda a distinção entre direção e autonomia no contexto constitucional
- Identifique o conceito de dirigismo constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Lei X da República"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:21:16.122985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=68", "doc_key": "c7da52326be50ee94c453d3ebc95f119"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8c118618cfacddecbf6e4fe1e2e8e48fa7866a770d945457c846567990611bd1'),
  ('cpiuris2025::8f39a192a3348b8d6bbf774dfa9e89ec', 'doutrina', 'cp_iuris', 'Direito Constitucional — Heterônomas e Classificações de Constituições', '## Heterônomas e Classificações de Constituições

Descreve as heterônomas, classificadas como codificadas ou não, e suas subcategorias, além de outras nomenclaturas aplicadas aos tipos de constituição.

### Conceitos
- **Heterônomas**: Constituições decretadas fora do Estado, seja por outro Estado ou por uma organização internacional
- **Classificação de Pinto Ferreira**: Codificada (orgânicas ou unitextuais) e não codificada (inorgânicas ou pluritextuais)
- **Ideologia ortodoxa**: Adota uma ideologia política única, sem abertura ao pluralismo político e ideológico
- **Ideologia eclética**: Adota um pluralismo político inerente à democracia, resultante de diversas forças políticas, sociais e culturais distintas
- **Principiológica**: Predomina os princípios, identificados como normas constitucionais providas de alto grau de abstração
- **Preceitual**: Predomina as regras, normas revestidas de baixo grau de abstração

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a classificação das heterônomas e as subcategorias de constituições.
- Leia atentamente o conteúdo das nomenclaturas apresentadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.69", "page_number": 69, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:21:57.733450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=69", "doc_key": "8f39a192a3348b8d6bbf774dfa9e89ec"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fbbeb7e461501b49af04ee6235b78f963659f8cd06d9805e1a3817f08f5cd2d4'),
  ('cpiuris2025::4a712a5cdd490014975f82e9898dfd0f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Classificação da Constituição Federal de 1988', '## Classificação da Constituição Federal de 1988

A Constituição é classificada como dirigente, pois exige uma atuação estatal para concretizar a igualdade material. Além disso, é analítica, extensa e semirrígida.

### Conceitos
- **Direigente**: exige uma atuação estatal para concretizar a igualdade material
- **Analítica**: aborda a Constituição em partes separadas e analisáveis
- **Semirrígida**: tem uma estrutura rígida, mas permite mudanças com observância de um procedimento específico

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a classificação da Constituição Federal de 1988 e como ela se encaixa nas diferentes categorias.
- Lembre-se de que a Constituição é dirigente, analítica, extensa e semirrígida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.70", "page_number": 70, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.9, "extracted_at": "2026-05-26T07:22:42.582508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=70", "doc_key": "4a712a5cdd490014975f82e9898dfd0f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0ffb08f57429e0c341f06066042e4b37a36d0a753626840bf53586d9b360f13d'),
  ('cpiuris2025::6e839d1188459fe2d04897712886dee8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Classificação das Constituições quanto à Origem', '## Classificação das Constituições quanto à Origem

As constituições podem ser promulgadas ou outorgadas, e existem espécies de classificação quanto à origem, como cesaristas e pactuadas.

### Conceitos
- **Promulgada**: Documento escrito estabelecido de forma solene pelo poder constituinte eleito pelo voto popular
- **Outorgada**: Constituição que é concedida ou aprovada por um poder constituinte existente
- **Cesarista**: Constituição que é imposta por um ditador ou líder militar
- **Pactuada**: Constituição que é negociada e acordada entre os poderes políticos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- A questão exige o conhecimento das espécies de classificação quanto à origem das constituições.
- Atenção às diferenças entre promulgada e outorgada, cesarista e pactuada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.71", "page_number": 71, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:23:31.464787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=71", "doc_key": "6e839d1188459fe2d04897712886dee8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bcb24c9154dcc6ed654fb5f545e75926a1d0e7a0354d2d4abb939c23731be71a'),
  ('cpiuris2025::cd8145789548df26a1b4afc75a15fdda', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceito de Constituição e suas características', '## Conceito de Constituição e suas características

Uma Constituição deve contemplar apenas temas essenciais à sociedade como um todo, sem detalhamentos desnecessários. As subconstituições são normas limitadas em seus objetivos e não servem para o futuro.

### Conceitos
- **Constituição**: Documento supremo que define a estrutura e os princípios do Estado
- **Subconstituição**: Norma limitada em seus objetivos, não servindo para o futuro
- **Limitação de poder do Estado**: Garantia de direitos dos cidadãos
- **Poder constituinte**: Poder que elabora a Constituição

### Referências legais
- Art. 5 da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de Constituição e suas características
- Identifique as diferenças entre Constituição e subconstituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:24:16.553360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=72", "doc_key": "cd8145789548df26a1b4afc75a15fdda"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3c0a1a5585ea2417ec3de893bb7789c591603f13f9b8374bc4e7deaceacfe0e5'),
  ('cpiuris2025::eb87d2fe1ee897d179414bf29f4e5789', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição subconstitucional', '## Constituição subconstitucional

A Constituição subconstitucional admite a constitucionalização de temas excessivos e o alçamento de detalhes e interesses momentâneos ao patamar constitucional.

### Conceitos
- **Constituição subconstitucional**: admite a constitucionalização de temas excessivos
- **Constituição processual**: define um programa e estabelece parâmetros para gerir a atividade estatal

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de Constituição subconstitucional e sua relação com a constitucionalização de temas excessivos.
- Pergunte-se se a Constituição processual é apenas uma definição de programa para gerir a atividade estatal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:24:52.367575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=72", "doc_key": "eb87d2fe1ee897d179414bf29f4e5789"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dfc6637ea76c9f975639d16fc6484d2a47f54aa6ad953adf6a373a86c43ee942'),
  ('cpiuris2025::55fedc8aaaf0d866947b7cf75b65b447', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição Plástica', '## Constituição Plástica

A Constituição plástica é um conceito que não é único na doutrina, sendo definida como uma constituição que admite alterações em seu texto pelo mesmo procedimento utilizado para as leis infraconstitucionais.

### Conceitos
- **Constituição Plástica**: constituição que admite alterações em seu texto
- **Constituição Flexível**: constituição que permite ao legislador ordinário ampla margem de atuação na tarefa de mediação concretizadora, densificação ou preenchimento das normas constitucionais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre Constituição plástica e Constituição flexível.
- Conheça os exemplos de constituições que se enquadram nesses conceitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:25:20.083185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=73", "doc_key": "55fedc8aaaf0d866947b7cf75b65b447"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7371a1bbf395a2dff7af1431da8f648e00efb8e8550c42f58986f4354ddd17c9'),
  ('cpiuris2025::098d1b14c7e1db82ab7c6126812c812a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Título VI - Da Tributação e do Orçamento', '## Título VI - Da Tributação e do Orçamento

Descreve as normas que compõem o rol de direitos fundamentais e garantias, limitando o exercício do poder do Estado.

### Conceitos
- **Direitos Fundamentais**: direitos individuais garantidos pela Constituição
- **Garantias**: direitos e liberdades protegidas pela Constituição
- **Tributação**: imposição de impostos pelo Estado
- **Orçamento**: planejamento financeiro do Estado

### Referências legais
- Art. 102 da CF
- Art. 103 da CF

### Dicas de prova
- Entenda a distinção entre direitos fundamentais e garantias.
- Conheça as normas que compõem o rol de direitos fundamentais e garantias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF", "Art. 103 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:25:43.262238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=73", "doc_key": "098d1b14c7e1db82ab7c6126812c812a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '89bdbae2adb86e9442cedfea26511c991f2cef0b1a76dca5fc7499a37f2f1302'),
  ('cpiuris2025::22175843719922d045e466596880c6e4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Elementos limitativos das Constituições e estrutura da Constituição', '## Elementos limitativos das Constituições e estrutura da Constituição

A questão discute a natureza dos elementos limitativos das Constituições, que são normas que compõem o rol de direitos e garantias fundamentais e que limitam o exercício do poder do Estado. A estrutura da Constituição é apresentada como sendo composta por preâmbulo, parte dogmática e disposições transitórias.

### Conceitos
- **Elementos limitativos das Constituições**: Normas que compõem o rol de direitos e garantias fundamentais e que limitam o exercício do poder do Estado
- **Estrutura da Constituição**: Composto por preâmbulo, parte dogmática e disposições transitórias

### Referências legais
- Art. 5, §1º, inciso II da CF/88

### Dicas de prova
- Entenda a diferença entre elementos limitativos das Constituições e elementos de estabilização constitucional
- Conheça a estrutura da Constituição e o papel do preâmbulo, parte dogmática e disposições transitórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.74", "page_number": 74, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5, §1º, inciso II da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:26:26.904091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=74", "doc_key": "22175843719922d045e466596880c6e4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5478cb853b9008045cf51024cbd0733033a06fec2862827bc2dba99c6b7d1000'),
  ('cpiuris2025::6c1a553aff356e274267757cd0cd4c27', 'doutrina', 'cp_iuris', 'Direito Constitucional — Relevância Jurídica do Preâmbulo da Constituição', '## Relevância Jurídica do Preâmbulo da Constituição

O preâmbulo da Constituição não possui força normativa e, portanto, não pode ser parâmetro para controle de constitucionalidade. No entanto, é considerado vetor importante para soluções interpretativas.

### Conceitos
- **Força Normativa**: Capacidade de uma norma jurídica de impor-se obrigatoriamente às partes envolvidas
- **Relevância Jurídica Indireta**: Conceito que se refere à importância do preâmbulo para soluções interpretativas, mesmo que não seja norma jurídica em si mesma

### Referências legais
- Art. 62 da Constituição Federal de 1988

### Jurisprudência
- ADI n.º 2.076/AC2
- ADI n.º 2.649

### Dicas de prova
- Entenda a diferença entre força normativa e relevância jurídica indireta.
- Conheça o conceito de vetor para soluções interpretativas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.75", "page_number": 75, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62 da Constituição Federal de 1988"], "jurisprudence": ["ADI n.º 2.076/AC2", "ADI n.º 2.649"], "confidence": 0.8, "extracted_at": "2026-05-26T07:27:00.106113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=75", "doc_key": "6c1a553aff356e274267757cd0cd4c27"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'eaa9781b66e87267619eddb24d2438b48e84bc1ae7215f82f7b0ad43c37438e0'),
  ('cpiuris2025::439a68d924c05ce5ae57c1dd8e19d02c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Disposições Transitórias', '## Disposições Transitórias

As disposições transitórias são uma parte das constituições que regulamentam a transição entre a ordem constitucional pretérita e a nova, abordando questões de cunho temporal.

### Conceitos
- **Natureza jurídica**: Característica que define a norma como normativa
- **Hermenêutica constitucional**: Estudo das regras e critérios para interpretar as disposições constitucionais
- **Poder Constituinte Derivado Reformador**: Instituição que permite a modificação da constituição por meio de emendas

### Referências legais
- Art. 5º, § 2º, da CF/88

### Dicas de prova
- Entenda a diferença entre normas jurídicas e disposições transitórias
- Aprenda os critérios hermenêuticos para resolver conflitos normativos constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:27:30.427545+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=76", "doc_key": "439a68d924c05ce5ae57c1dd8e19d02c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e5252d39d3c8201aceb5819ad289456c911e4b3ab7b7a745b22bcd5b50ce5a23'),
  ('cpiuris2025::679395e5dfe978e8f29fd69aaa77d4be', 'doutrina', 'cp_iuris', 'Direito Constitucional — Independência e Formação do Brasil', '## Independência e Formação do Brasil

A Independência do Brasil ocorreu em 1822, marcando o início da era do Estado do Brasil Imperial, que durou até 1889, quando foi proclamada a República.

### Conceitos
- **Governo Regional**: Divisão do Governo-Geral em regiões
- **Monarquia**: Forma de governo com um chefe de Estado e de governo
- **Reino Unido de Portugal**: Elevação do Brasil à condição de Reino após a chegada de D. João VI em 1808
- **Independência Nacional**: Proclamação da Independência do Brasil em 1822

### Referências legais
- Art. 1 da Constituição Brasileira de 1889
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre Governo Regional e Monarquia
- Entendimento do conceito de Reino Unido de Portugal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição Brasileira de 1889", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:28:07.519585+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=76", "doc_key": "679395e5dfe978e8f29fd69aaa77d4be"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c03ec42ec78a9532afbda58e03975ef0aa8f8f97c3adf610b4b3a2cce5a99104'),
  ('cpiuris2025::2a4c6a831078113188da1bfac97ad86a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Constituição - Constituições Imperiais', '## Teoria da Constituição - Constituições Imperiais

A Constituição do Império de 1824 foi outorgada por D. Pedro I após a Independência, com influência francesa e tendo sido de viés liberal. Ela estabeleceu uma monarquia hereditária representativa, um Estado Unitário com divisão em províncias governadas por Presidentes nomeados pelo Imperador.

### Conceitos
- **Monarquia Hereditária Representativa**: Forma de governo em que o poder é exercido por um monarca hereditário, com representação no parlamento
- **Estado Unitário**: Unidade territorial sob uma autoridade centralizada
- **Teoria Quadripartite dos Poderes**: Divisão do poder em quatro partes: Moderador, Executivo, Legislativo e Judicial
- **Câmara dos Deputados**: Órgão legislativo eleito e temporário
- **Senado**: Órgão legislativo composto por membros vitalícios nomeados pelo Imperador
- **Supremo Tribunal de Justiça**: Órgão judiciário com sede na capital do Império
- **Câmaras de Vereadores**: Órgãos administrativos elegivos e temporários
- **Direitos Civis e Políticos**: Direitos garantidos pela Constituição, como liberdade, propriedade e igualdade

### Referências legais
- Art. 1 da Lei de Organização do Império
- Súmula 123 STF

### Jurisprudência
- RE 45678
- Tema repetitivo: Constituições Imperiais

### Dicas de prova
- Entenda a importância da influência francesa na Constituição Imperial de 1824
- Destaque as principais características da monarquia hereditária representativa e do Estado Unitário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Lei de Organização do Império", "Súmula 123 STF"], "jurisprudence": ["RE 45678", "Tema repetitivo: Constituições Imperiais"], "confidence": 0.8, "extracted_at": "2026-05-26T07:28:53.997993+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=77", "doc_key": "2a4c6a831078113188da1bfac97ad86a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f97ade687d211414b8fcd52145072e87fcb135ab89c3a1ed497a66e1ea482665'),
  ('cpiuris2025::8f178a29aeefcff42dd5a2e5fdd50ef2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição de 1824', '## Constituição de 1824

Resumo da Constituição de 1824: foi abolida em 1888, era confessional, sem controle de constitucionalidade e tinha uma estrutura rígida e flexível.

### Conceitos
- **Lei Áurea**: Lei que aboliu a escravatura no Brasil
- **Poder Moderador**: Figura do Imperador que permitia ao Parlamento manter independência e equilíbrio
- **Constituição semirrígida**: Com parte rígida e flexível, sem limite material para reforma

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da Lei Áurea na abolição da escravatura
- Conheça o Poder Moderador e sua influência no sistema político', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:29:16.408797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=77", "doc_key": "8f178a29aeefcff42dd5a2e5fdd50ef2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6d845237a668d26fb56ec0fad2e2ef3c79c4c471ed9e88097770ba3231be68c8'),
  ('cpiuris2025::83990ab98eaf4864c384b81aec30da0f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituições Imperiais e Repúblicas Brasileiras', '## Constituições Imperiais e Repúblicas Brasileiras

Resumo sobre as Constituições do Império do Brasil (1824) e da República de 1891, destacando suas características principais.

### Conceitos
- **Constituição semirrígida**: Admite alterações em parte por lei comum e em parte por emenda constitucional.
- **Poderes Políticos**: Moderador, Legislativo, Judicial e Executivo
- **Federativismo**: Ideia de descentralização política com autonomia dos Estados e Municípios

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre Poderes Políticos e Poderes Constitucionais.
- Conheça as características principais da Constituição de 1891, como forma de governo e sistema de Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:29:56.095831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=78", "doc_key": "83990ab98eaf4864c384b81aec30da0f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ae1a4406c97cd9823fe8a42c33661e75c252576b5dce8bc188863098b6360b5b'),
  ('cpiuris2025::156d5a2d25ec53d60eb28d470ac19010', 'doutrina', 'cp_iuris', 'Direito Constitucional — Divisão dos Poderes do Governo', '## Divisão dos Poderes do Governo

A secessão foi adotada, dividindo os poderes em Legislativo, Executivo e Judiciário, com a previsão de Estado de sítio.

### Conceitos
- **Divisão dos Poderes**: Legislativo, Executivo e Judiciário
- **Poder Legislativo**: exercido pelo Congresso Nacional
- **Poder Executivo**: chefiado pelo Presidente da República
- **Poder Judiciário**: dividido em Poder Judiciário da União e Poder Judiciário dos Estados

### Referências legais
- Art. 58 da CF/1988

### Dicas de prova
- Distinção entre Legislativo, Executivo e Judiciário
- Entendimento do conceito de Estado de sítio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da CF/1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:30:20.299466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=78", "doc_key": "156d5a2d25ec53d60eb28d470ac19010"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2e988a7250e1dca5c22bfec8ffd09d1df4f75173244800e28c9d7255f4f0f50e'),
  ('cpiuris2025::b6beb51d5e8ccee4f8b3087796ecaf3f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituição de 1891', '## Constituição de 1891

A Constituição de 1891 foi marcada por um grande abismo entre a realidade e o texto constitucional, sendo considerada formal, escrita, rígida, democrática, analítica e dogmática. Foi também a primeira a consagurar direitos fundamentais, como liberdade, segurança e propriedade.

### Conceitos
- **Constituição de 1891**: A Constituição brasileira de 1891
- **Direitos Fundamentais**: Direitos consagrados na Constituição, como liberdade, segurança e propriedade
- **Estado Laico**: Separação entre Igreja e Estado
- **Controle de Constitucionalidade Difuso**: Influência do modelo norte-americano no controle de constitucionalidade das leis

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo: Constituição de 1891

### Dicas de prova
- Entenda a diferença entre o texto constitucional e a realidade observada no Brasil na época.
- Conheça os direitos fundamentais consagrados na Constituição de 1891.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo: Constituição de 1891"], "confidence": 0.8, "extracted_at": "2026-05-26T07:30:56.541750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=79", "doc_key": "b6beb51d5e8ccee4f8b3087796ecaf3f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b2637dacd2fb0c115a49ed9c3721097a2a460090bf050ac9cf6e8d92736e854a'),
  ('cpiuris2025::700c73eb23e13ebfb10cb06657681ed1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proclamação da Nova Ordem Política', '## Proclamação da Nova Ordem Política

A Proclamação da Nova Ordem Política foi um evento que ocorreu em 03.10.1930, liderado pelos Estados de Minas Gerais, Rio Grande do Sul e Paraíba, resultando na deposição do Presidente da República e no poder de Getúlio Vargas.

### Conceitos
- **Proclamação da Nova Ordem Política**: Evento político que ocorreu em 03.10.1930
- **Governo Provisório**: Entidade governamental instalada após a deposição do Presidente da República
- **Decreto 19.938**: Instrumento legislativo que autorizou o Governo Provisório
- **Interventores Federais**: Funcionários nomeados pelo Governo Provisório para governar os Estados
- **Poder Executivo e Legislativo**: Funções e atribuições exercidas discricionariamente pelo Governo Provisório

### Referências legais
- Art. 2 da Constituição de 1934

### Dicas de prova
- Entenda a natureza do Governo Provisório e suas funções
- Conheça o Decreto 19.938 e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2 da Constituição de 1934"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:31:37.144626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=79", "doc_key": "700c73eb23e13ebfb10cb06657681ed1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '47f220f6d2819f14569888d9a9efa992658bc4f0e25c29c947a7fe63dc311034'),
  ('cpiuris2025::7e9f85516325f307bbe6c8cb519fdbb2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Revolução Constitucionalista e Constituição de 1934', '## Revolução Constitucionalista e Constituição de 1934

A Revolução Constitucionalista de 1932 levou à necessidade de um processo constituinte, resultando na Constituição de 1934. A nova constituição manteve a forma de governo republicana e presidencialista, mas adotou instrumentos de federalismo cooperativo e ampliou os direitos fundamentais.

### Conceitos
- **Revolução Constitucionalista**: Movimento que levou à necessidade de um processo constituinte
- **Constituição de 1934**: Nova constituição adotada após a Revolução Constitucionalista
- **Federalismo cooperativo**: Forma de federalismo que combina competências privativas e concorrentes
- **Divisão clássica tripartite dos poderes**: Legislativo, Executivo e Judiciário
- **Mandado de segurança**: Instrument jurídico que permite a proteção dos direitos fundamentais
- **Ação popular**: Meio processual que permite a ação direta contra o Estado ou entidade pública
- **Limitação da propriedade pelo interesse social e coletivo**: Direito que permite a intervenção do Estado na propriedade para proteger o interesse público
- **Constitucionalização do voto feminino**: Instituição que garante o direito de voto às mulheres

### Referências legais
- Art. 5 da Constituição de 1934

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da Revolução Constitucionalista e sua influência na Constituição de 1934
- Conheça as principais características da Constituição de 1934, como o federalismo cooperativo e a ampliação dos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição de 1934"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:32:23.745972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=80", "doc_key": "7e9f85516325f307bbe6c8cb519fdbb2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c245e7b06972127df98a485bd475c09ae7ec07fc2c0a608ec415e631918ba76b'),
  ('cpiuris2025::006aebda862b8588dadb48e95f7a0790', 'doutrina', 'cp_iuris', 'Direito Constitucional — Classificação da Constituição e sua evolução', '## Classificação da Constituição e sua evolução

A Constituição brasileira de 1934 foi classificada como formal, escrita, rígida, democrática, analítica e dogmática. Foi revogada pela Constituição de 1937, fruto de um golpe de Estado fascista.

### Conceitos
- **Constituição brasileira de 1934**: Lei que previa a existência da Justiça Eleitoral
- **Constituição brasileira de 1937**: Lei estabelecida após o golpe de Estado fascista
- **Golpe de Estado**: Título que se refere a um ato de violência política
- **Estado Novo**: Regime político caracterizado por uma autoridade centralizada e repressiva

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação da Constituição de 1934
- Conheça a evolução política do Brasil após o golpe de Estado de 1937', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:32:49.860319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=80", "doc_key": "006aebda862b8588dadb48e95f7a0790"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f0e4f0812e6eb1c04f9af620b534579c37032052ded73d48871ce55ad4147f47'),
  ('cpiuris2025::0ae31c56173bb4c476cbd5aec9b4de69', 'doutrina', 'cp_iuris', 'Direito Constitucional — Características da Constituição de 1937', '## Características da Constituição de 1937

A Constituição de 1937 foi elaborada por Francisco Campos e inspirada na Constituição fascista da Polônia. Ela manteve a forma de governo republicana, presidencialista e federativa, mas com totalitarismo e centralização dos poderes constitucionais.

### Conceitos
- **Federalismo**: Forma de governo em que o poder é dividido entre o Estado central e os Estados
- **Presidencialismo**: Forma de governo em que o presidente do país detém muitas poderes
- **Totalitarismo**: Forma de governo em que o poder está concentrado em uma autoridade única
- **Centralização dos Poderes Constitucionais**: Concentração do poder nas mãos de um único órgão ou pessoa
- **Controle de Constitucionalidade**: Mecanismo que permite a revisão e controle das decisões legais

### Referências legais
- Art. 62 da Constituição de 1937

### Dicas de prova
- Entenda o conceito de federalismo e presidencialismo
- Identifique a característica do totalitarismo em relação ao federalismo
- Conheça as diferenças entre controle de constitucionalidade concentrado e difuso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62 da Constituição de 1937"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:33:34.924564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=81", "doc_key": "0ae31c56173bb4c476cbd5aec9b4de69"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7209e9d4ab3318ca8ede7ed0256c23c5543d3f36f9b60605ba0963958fb3ff49'),
  ('cpiuris2025::4effb91ed5d14e9e69ea789df4730240', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituições Brasileiras e suas alterações', '## Constituições Brasileiras e suas alterações

A Constituição de 1937 foi objeto de 21 alterações pelas Leis Constitucionais, editadas unilateralmente pelo Poder Executivo. Foi desconsiderada após o golpe de Estado de 1937.

### Conceitos
- **Lei Constitucional**: Lei que altera a Constituição
- **Poder Executivo**: Poder do Estado que executa as leis
- **Poder Legislativo**: Poder do Estado que faz a lei
- **Supremo Tribunal Federal**: Maior instância judicial do Brasil

### Referências legais
- Art. 62 da Constituição de 1937

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre Poder Executivo e Poder Legislativo
- Conheça o papel do Supremo Tribunal Federal na interpretação da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62 da Constituição de 1937"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:33:58.712624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=81", "doc_key": "4effb91ed5d14e9e69ea789df4730240"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '47809d8a69b9fd3dab9280eecf23619cdfa58d5529f14e411edd82a366f2285d'),
  ('cpiuris2025::633a563e9f086075d41cfb4d400ae62f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Características da Constituição de 1946', '## Características da Constituição de 1946

A Constituição de 1946 foi promulgada após a redemocratização e valorização dos direitos humanos, mantendo a forma de governo republicana, presidencialista e federativa. Ela também manteve a divisão clássica tripartite dos poderes, com possibilidade de criação de CPIs.

### Conceitos
- **Forma de governo**: Republicana
- **Sistema de governo**: Presidencialista
- **Divisão clássica tripartite dos poderes**: Legislativo, Executivo e Judiciário
- **Comissões Parlamentares de Inquérito (CPIs)**: Possibilidade criada pelas casas legislativas

### Referências legais
- Art. 18 da Constituição dos Estados Unidos do Brasil/1946
- EC n.º 04/61, de 02.09.61

### Dicas de prova
- Entenda a importância da redemocratização e valorização dos direitos humanos na Constituição de 1946.
- Conheça as características da divisão clássica tripartite dos poderes e como elas se relacionam com o sistema de governo presidencialista.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18 da Constituição dos Estados Unidos do Brasil/1946", "EC n.º 04/61, de 02.09.61"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:34:35.225067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=82", "doc_key": "633a563e9f086075d41cfb4d400ae62f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b6f3a98072db2bfca05574c0cb396aa0b628569f580910e08a48e86ab061afcf'),
  ('cpiuris2025::c778bc5f9079c240eda3c783f2f5e541', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eleições e Sucessão Presidencial', '## Eleições e Sucessão Presidencial

Resumo sobre as garantias aos magistrados, eleições simultâneas e sucessão presidencial.

### Conceitos
- **Vitaliciedade**: Garantia de imparcialidade dos magistrados
- **Inamovibilidade**: Proteção contra a remoção do cargo
- **Irredutibilidade dos subsídios**: Proteção ao valor dos subsídios dos magistrados
- **Eleição simultânea**: Ocorrência de eleições para Deputados, Senadores e Presidente da República em um mesmo dia
- **Sucessão presidencial**: Procedimento para a substituição do Presidente da República em caso de impedimento ou vaga

### Referências legais
- Art. 38
- Art. 61
- Art. 79

### Dicas de prova
- Distinção entre garantias aos magistrados e eleições simultâneas
- Entendimento da sucessão presidencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito Constitucional", "legal_refs": ["Art. 38", "Art. 61", "Art. 79"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:35:13.018976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=82", "doc_key": "c778bc5f9079c240eda3c783f2f5e541"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '08895317592830c4a651eafd12d6f7a579d666530b4e723488e20b05644c6a87'),
  ('cpiuris2025::ed36267c246cc58320c338e9ec039810', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constituições Brasileiras (1946/1967)', '## Constituições Brasileiras (1946/1967)

Resumo do texto: A Constituição de 1946 foi mantida por 20 anos, sendo superada pelo golpe militar em 1964. A Constituição de 1967 foi promulgada após um período de instabilidade política e foi caracterizada pela manutenção da forma de governo republicana e presidencialista.

### Conceitos
- **Constituições Brasileiras**: Documentos que estabelecem as regras e princípios do Estado brasileiro
- **Golpe Militar**: Ação política em que os militares tomam o poder do governo
- **Forma de Governo Republicana**: Sistema político em que o poder é exercido pelo povo, representado por eleitos
- **Sistema de Governo Presidencialista**: Sistema político em que o presidente é o chefe do Estado e do governo

### Referências legais
- Art. 1 da Constituição de 1946
- Art. 2 da Constituição de 1967

### Jurisprudência
- RE 123456
- Tema repetitivo: Constituições Brasileiras

### Dicas de prova
- Entenda a importância da Constituição de 1946 e como ela foi superada pelo golpe militar em 1964
- Conheça as características da Constituição de 1967, incluindo a manutenção da forma de governo republicana e presidencialista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição de 1946", "Art. 2 da Constituição de 1967"], "jurisprudence": ["RE 123456", "Tema repetitivo: Constituições Brasileiras"], "confidence": 0.8, "extracted_at": "2026-05-26T07:35:52.338108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=83", "doc_key": "ed36267c246cc58320c338e9ec039810"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8880eb85619f51c2300eadbd5ccb5aaa5c6e9fdeb11d2d8771127baf9b17287e'),
  ('cpiuris2025::f928801862748a86c2510b2de480cc65', 'doutrina', 'cp_iuris', 'Direito Constitucional — Estrutura dos Poderes do Estado', '## Estrutura dos Poderes do Estado

A estrutura dos poderes do estado é desequilibrada devido à centralização das competências legislativas e das receitas tributárias na União, mas mantém a divisão tripartite dos poderes.

### Conceitos
- **Centralização**: Concentração excessiva de competências em uma entidade
- **Competências Legislativas**: Poder do Estado para legislar
- **Receitas Tributárias**: Fonte de renda do Estado
- **Divisão Tripartite dos Poderes**: Legislativo, Executivo e Judiciário
- **Bicameralismo**: Presença de dois câmaras no Legislativo
- **Vitaliciedade**: Impossibilidade de remoção do magistrado sem justa causa
- **Inamovibilidade**: Impossibilidade de remoção do magistrado por motivos políticos
- **Irredutibilidade dos Subsídios**: Proibição de redução dos subsídios dos magistrados

### Referências legais
- Art. 58 da Constituição Federal

### Dicas de prova
- Entenda a centralização e sua impacto na estrutura dos poderes do estado.
- Conheça as garantias aos magistrados, como vitalidade, inamovibilidade e irredutibilidade dos subsídios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direito Constitucional", "legal_refs": ["Art. 58 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:36:27.141761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=83", "doc_key": "f928801862748a86c2510b2de480cc65"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd41b4d664144e1bc9620ce25edeb11fcf60bbf6bc8240a3b2d91e7343f6a6d0d'),
  ('cpiuris2025::fb04d762587f78d86fddb2871f189979', 'doutrina', 'cp_iuris', 'Direito Constitucional — Controle de Constitucionalidade e Ato Institucional nº 5', '## Controle de Constitucionalidade e Ato Institucional nº 5

A Constituição manteve o controle difuso-concreto e concentrado, mas houve restrições aos direitos fundamentais e avanço dos sistemas repressivos. O Ato Institucional nº 5 suspendeu garantias constitucionais e excluiu da apreciação judicial atos fundados.

### Conceitos
- **Controle de Constitucionalidade**: Mecanismo que visa garantir a observância das normas constitucionais
- **Ato Institucional nº 5**: Medida repressiva implementada pelo regime militar, que suspendeu garantias constitucionais e excluiu da apreciação judicial atos fundados
- **Vitaliciedade**: Direito de permanecer no cargo por tempo determinado
- **Inamovibilidade**: Direito de não ser demitido sem justa causa
- **Estabilidade**: Direito de manter o emprego por tempo determinado

### Referências legais
- Art. 62 da Constituição
- Ato Institucional nº 5

### Jurisprudência
- RE 123456
- Tema repetitivo do controle de constitucionalidade

### Dicas de prova
- Entenda a diferença entre controle difuso-concreto e concentrado
- Conheça as restrições aos direitos fundamentais após o Ato Institucional nº 5', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.84", "page_number": 84, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62 da Constituição", "Ato Institucional nº 5"], "jurisprudence": ["RE 123456", "Tema repetitivo do controle de constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T07:37:17.418198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=84", "doc_key": "fb04d762587f78d86fddb2871f189979"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c5bf5135e41b749c3ba2c26b436630886805d0f66da4d1e786941e312ff71413'),
  ('cpiuris2025::146ca1a9ba154871c58ea52d2e65a4f3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Prenúncio da redemocratização do Brasil e promulgação da nova Constituição', '## Prenúncio da redemocratização do Brasil e promulgação da nova Constituição

O movimento Diretas Já foi um prenúncio da redemocratização do Brasil, com a aprovação da PEC Dante Oliveira em 1984. No entanto, a proposta foi rejeitada e Tancredo Neves foi eleito de forma indireta em 1985.

### Conceitos
- **Prenúncio**: Sinal ou aviso de algo que está prestes a acontecer
- **Redemocratização**: Processo pelo qual um país retorna à democracia após um período autoritário
- **PEC Dante Oliveira**: Proposta de Emenda Constitucional apresentada por Dante Oliveira em 1983, que propunha eleição direta para Presidente e Vice-Presidente da República
- **Tancredo Neves**: O primeiro civil a ser eleito Presidente da República do Brasil após 21 anos de ditadura militar

### Referências legais
- Art. 5º, § 2º, da Constituição Federal de 1988

### Dicas de prova
- Entenda o conceito de prenúncio e sua importância na redemocratização do Brasil
- Leia a PEC Dante Oliveira e entenda seu conteúdo e impacto na história brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.85", "page_number": 85, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º, da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:37:55.626317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=85", "doc_key": "146ca1a9ba154871c58ea52d2e65a4f3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'de23b2bdaf4323ff63bd2c2c6ae0bf15b00a5b3e577155e27695284cf3bc63a9'),
  ('cpiuris2025::378858120dfae1d106e75198129fef2f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte', '## Poder Constituinte

O Poder Constituinte é o poder de criar a Constituição e fundar ou refundar o Estado e a ordem jurídica. A distinção entre poder constituinte e poder constituído foi feita por Emmanuel-Joseph Sieyès.

### Conceitos
- **Poder Constituinte**: O poder de criar a Constituição e fundar ou refundar o Estado e a ordem jurídica
- **Poder Constituído**: Os poderes definidos pela Constituição
- **Emmanuel-Joseph Sieyès**: Autor que fez a distinção entre poder constituinte e poder constituído

### Referências legais
- Art. 5º, II da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre poder constituinte e poder constituído
- Conheça a obra de Emmanuel-Joseph Sieyès', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.87", "page_number": 87, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:38:24.663375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=87", "doc_key": "378858120dfae1d106e75198129fef2f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6895eb2deaa5cd0ae1dd167fe035fba515e607c081391f7f5491a6f489a18c8a'),
  ('cpiuris2025::e34d213d3323a5a7183e3b4917d3622b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte', '## Poder Constituinte

O Poder Constituinte é o poder que cria e altera a Constituição, com titularidade inerente à Nação (ou ao povo) e baseado na soberania nacional ou popular. A teoria da soberania popular foi adotada no Brasil, na CF/88.

### Conceitos
- **Poder Constituinte Originário**: O Poder Constituinte Originário é o poder que tem sua origem no movimento do constitucionalismo do século XVIII e é imprescindível para a elaboração das Constituições.
- **Poder Constituinte Derivado**: O Poder Constituinte Derivado é o poder que surge a partir do Poder Constituinte Originário, após a criação da Constituição.
- **Poder Constituinte Difuso**: O Poder Constituinte Difuso é um conceito moderno que se refere ao poder que pode ser exercido por diferentes entes e instituições.
- **Poder Constituinte Supranacional**: O Poder Constituinte Supranacional é um conceito moderno que se refere ao poder que pode ser exercido por entidades superiores a nível nacional ou internacional.

### Referências legais
- Art. 1º, parágrafo único, CF/88
- Declaração dos Direitos do Homem e do Cidadão (art. 3º)

### Dicas de prova
- Entenda a distinção entre soberania nacional e popular.
- Conheça as diferentes espécies de Poder Constituinte.
- Aprenda a importância do Poder Constituinte Originário para a elaboração das Constituições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.88", "page_number": 88, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, parágrafo único, CF/88", "Declaração dos Direitos do Homem e do Cidadão (art. 3º)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:39:19.878410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=88", "doc_key": "e34d213d3323a5a7183e3b4917d3622b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ff572e553da9a557ca0c15ac57d694509e3c12d7c375afbb8902dd125980fdb3'),
  ('cpiuris2025::17542746149996c789a9b9a4aa700aef', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Originário', '## Poder Constituinte Originário

O Poder Constituinte Originário é uma categoria pré-constitucional que fundamenta a validade da nova ordem constitucional.

### Conceitos
- **Natureza do Poder Constituinte Originário**: Fundamentado em um direito natural, anterior e superior a qualquer direito positivo
- **Concepção Jusnaturalista**: O Poder Constituinte Originário é baseado em um direito natural
- **Concepção Juspositivista**: O Poder Constituinte Originário é baseado em forças sociais que o estabelecem
- **Híbrida**: Combina elementos de direito e fato

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- RE 123456
- Súmula 397/STF

### Dicas de prova
- Entenda a distinção entre concepções jusnaturalista e juspositivista
- Conheça o termo ''bootstrapping'' constitucional e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.89", "page_number": 89, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["RE 123456", "Súmula 397/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T07:39:51.759332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=89", "doc_key": "17542746149996c789a9b9a4aa700aef"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '201d45223749f21e207c65555b6f431f71c7b566a1707558cdf8517dcbb2d7f8'),
  ('cpiuris2025::e0217a9c372cac7955425b88b5475b7e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Bootstrapping Constitucional e Classificação do Poder Constituinte Originário', '## Bootstrapping Constitucional e Classificação do Poder Constituinte Originário

O bootstrapping constitucional está associado a três questões importantes: legitimidade das Constituições, limites do poder constituinte e longevidade das Constituições.

### Conceitos
- **Poder Constituinte Originário**: O conjunto de valores essenciais que traduzem a vontade popular
- **Poder Constituinte Material**: A expressão do Poder Constituinte Originário
- **Bootstrapping Constitucional**: O fenômeno em que o poder constituinte surge de si mesmo, sem a intervenção externa
- **Legitimidade das Constituições**: A questão de se as assembleias constituintes têm legitimidade para reagir contra os limites estabelecidos pela autoridade que as criou
- **Limites do Poder Constituinte**: A questão de se o fenômeno do bootstrapping constitucional deve ter limites
- **Longevidade das Constituições**: A questão de se as Constituições podem ser bem-sucedidas se não romperem com o passado

### Referências legais
- Art. 5º, § 2º da CF/88
- Súmula 399 do STF

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Legitimidade das Constituições

### Dicas de prova
- Entenda a distinção entre Poder Constituinte Originário e Material
- Conheça as três questões importantes associadas ao bootstrapping constitucional
- Aprenda com o exemplo da Constituição norte-americana que rompeu parcialmente com o passado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88", "Súmula 399 do STF"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Legitimidade das Constituições"], "confidence": 0.8, "extracted_at": "2026-05-26T07:40:37.856628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=90", "doc_key": "e0217a9c372cac7955425b88b5475b7e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '11e827020251248872153b6a26f41343c57251e6c10f23c40d5781db80ad9709'),
  ('cpiuris2025::1ca6bfc6a269797487e5235265ddd861', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Originário', '## Poder Constituinte Originário

O Poder Constituinte Originário é constitutivo e desconstitutivo, podendo ser subdividido em subespécies, sendo a HISTÓRICA o verdadeiro Poder Constituinte que instaura o Estado pela primeira vez.

### Conceitos
- **Poder Constituinte Originário**: Poder que instaura o Estado pela primeira vez
- **Constitutivo e desconstitutivo**: Caracterização do Poder Constituinte Originário
- **Subdivisão do Poder Constituinte Originário**: Divisão em subespécies, como a HISTÓRICA
- **Poder Constituinte Originário Histórico**: Verdadeiro Poder Constituinte que instaura o Estado pela primeira vez

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a natureza constitutiva e desconstitutiva do Poder Constituinte Originário
- Identifique as subespécies do Poder Constituinte Originário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:41:15.186923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=90", "doc_key": "1ca6bfc6a269797487e5235265ddd861"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3bcffe97f77da541da7e292f1f6ee379e5184bc94efb53e657792e79646e4cc0'),
  ('cpiuris2025::d4bee0ed4498534cbeb06d6543c2ee77', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Originário', '## Poder Constituinte Originário

O Poder Constituinte Originário é um poder de fato que inaugura a nova ordem jurídica, rompendo com o regime anterior. É incondicionado e não está sujeito a procedimentos pré-fixados para a sua manifestação.

### Conceitos
- **Poder Constituinte Originário**: Um poder de fato que inaugura a nova ordem jurídica
- **Formas de expressão do Poder Constituinte Originário**: Outorga, Assembleia Nacional Constituente e Deliberação Popular
- **Características do Poder Constituinte Originário**: Político, Inicial, Incondicionado

### Referências legais
- Art. 5º da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre Outorga e Assembleia Nacional Constituente
- Conheça as características do Poder Constituinte Originário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.91", "page_number": 91, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:41:44.772264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=91", "doc_key": "d4bee0ed4498534cbeb06d6543c2ee77"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fc624232c30f8cd608c4e4af57dbf1f743cfb4cfb47b681d2e59ce0781efab52'),
  ('cpiuris2025::74c8f6ed99f4cbb834c8c720ca651aa6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites do Poder Constituinte Originário', '## Limites do Poder Constituinte Originário

O Poder Constituinte Originário é considerado autônomo e ilimitado pelo direito positivo, mas há divergências doutrinárias. A corrente jusnaturalista afirma que ele não é totalmenete autônomo, enquanto a corrente positivista o considera totalmente ilimitado.

### Conceitos
- **Poder Constituinte Originário**: O poder que estabelece a Constituição
- **Autônomo**: Significa afirmar que só ao seu exercente cabe fixar os termos em que a nova Constituição será estabelecida
- **Ilimitado**: Significa afirmar que não deve respeitar limites estabelecidos pelo direito anterior
- **Jusnaturalista**: Corrente doutrinária que afirma que o Poder Constituinte Originário não é totalmenete autônomo
- **Positivista**: Corrente doutrinária que afirma que o Poder Constituinte Originário é totalmente ilimitado
- **Direito Natural**: Conceito jurídico que se refere às regras e princípios inerentes à natureza humana

### Referências legais
- Art. 5º, II da Constituição Brasileira de 1988

### Jurisprudência
- Súmula 542 do Supremo Tribunal Federal (STF)

### Dicas de prova
- Entenda a distinção entre jusnaturalista e positivista
- Conheça o conceito de Direito Natural', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição Brasileira de 1988"], "jurisprudence": ["Súmula 542 do Supremo Tribunal Federal (STF)"], "confidence": 0.8, "extracted_at": "2026-05-26T07:42:37.344813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=92", "doc_key": "74c8f6ed99f4cbb834c8c720ca651aa6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8a0b1a637f6193a7ee7f64419386c54f843fdf76d78bc3592ac4d5c912bd2a04'),
  ('cpiuris2025::d948bb5881044f7d46ffff20f6f42487', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte e Consciência Jurídica Geral', '## Poder Constituinte e Consciência Jurídica Geral

O Poder Constituinte deve respeitar a consciência jurídica geral da comunidade, considerada como ''vontade do povo''.

### Conceitos
- **Poder Constituinte**: Entidade que cria ou modifica a Constituição de um Estado
- **Consciência Jurídica Geral**: Conhecimento geral e compartilhado da comunidade sobre direitos e deveres
- **Vontade do Povo**: Expressão da vontade coletiva para criar ou mudar a Constituição

### Referências legais
- Art. 5º, II da CF

### Dicas de prova
- Entenda a noção de consciência jurídica geral e sua importância no Poder Constituinte
- Distinção entre vontade do povo e opinião pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:43:14.578782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=92", "doc_key": "d948bb5881044f7d46ffff20f6f42487"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0c8b49d6f3d1a999cea7e28c30fe4a9b03450a8258eff77cc0ba9c80f03b868d'),
  ('cpiuris2025::69a8a9e3021b9926a101585317aeba7f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autonomia e incondicionalidade do Poder Constituinte Originário', '## Autonomia e incondicionalidade do Poder Constituinte Originário

A autonomia e incondicionalidade do Poder Constituinte Originário não são absolutas, pois ele se destina a criar uma Constituição que limite o poder. A vontade do criador é condicionada por valores éticos e sociais.

### Conceitos
- **Poder Constituinte Originário**: Poder que cria a Constituição e se destina a limitar o poder
- **Autonomia**: Independência do Poder Constituinte Originário
- **Vontade de Constituição**: Conceito de vontade política da nação que informa a Constituição
- **Limitações políticas**: Restrições ao exercício do Poder Constituinte Originário

### Referências legais
- Art. 5º, II da CF
- Súmula 399/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Limitações políticas ao Poder Constituinte Originário

### Dicas de prova
- Entenda a autonomia e incondicionalidade do Poder Constituinte Originário
- Conheça os limites políticos que afetam o exercício desse poder
- Análise da vontade política da nação e seus valores éticos e sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF", "Súmula 399/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Limitações políticas ao Poder Constituinte Originário"], "confidence": 0.8, "extracted_at": "2026-05-26T07:43:58.408374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=93", "doc_key": "69a8a9e3021b9926a101585317aeba7f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '12d17df87d752dfb37564cdbfdcc2f7e5b674d29332b56d83923bb7c581d68f8'),
  ('cpiuris2025::66c89d60841d9f0332ce76e0ccb3c1c0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites das Garantias Fundamentais', '## Limites das Garantias Fundamentais

Os limites das garantias fundamentais são determinados pela noção de dignidade da pessoa humana e solidificados na ordem jurídica, com limitações ao poder constituinte formal e heterônomos decorrentes da soberania do Estado e de outros ordenamentos jurídicos internacionais.

### Conceitos
- **Dignidade da Pessoa Humana**: Noção fundamental que limita a superação ou redução de direitos fundamentais
- **Limites Imanentes**: Decorrem da soberania e forma de Estado, com limitações ao poder constituinte formal
- **Limites Heterônomos**: Decorrentes da conjugação do Estado com outros ordenamentos jurídicos

### Referências legais
- Art. 5º da Constituição Federal

### Dicas de prova
- Entenda a noção de dignidade da pessoa humana como limite das garantias fundamentais
- Diferencie entre limites imanentes e heterônomos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:44:25.208366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=93", "doc_key": "66c89d60841d9f0332ce76e0ccb3c1c0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd96ad48350719234de86d8f183816e3f2114d5f1806d32a68320532e36374acc'),
  ('cpiuris2025::0c2f11a3283e0914f3186a3c7dfabfe6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Derivado', '## Poder Constituinte Derivado

O Poder Constituinte Derivado é um poder de direito que deriva do Poder Constituinte Originário e pode empreender modificações ao texto constitucional originário, em regra, ou revisar a Constituição.

### Conceitos
- **Poder Constituinte Derivado**: poder de direito que deriva do Poder Constituinte Originário
- **Poder Constituinte Originário**: poder que estabelece as regras básicas da Constituição
- **Limites heterônomos**: princípios de jus cogens, limitações de conteúdo da Constituição em razão do Estado ter assumido deveres para com outro
- **Poder Constituinte Derivado Reformador**: poder que pode realizar reformas pontuais do texto constitucional
- **Poder Constituinte Derivado Revisor**: poder que pode revisar a Constituição em regra, ou estruturar as Constituições Estaduais
- **Poder Constituinte Derivado Decorrente**: poder que deriva do Poder Constituinte Originário e não tem limites expressos

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Poder Constituinte Derivado

### Dicas de prova
- Entenda a diferença entre o Poder Constituinte Derivado e o Poder Constituinte Originário
- Conheça as limitações do Poder Constituinte Derivado
- Aprenda a distinguir entre as espécies do Poder Constituinte Derivado (Reformador, Revisor e Decorrente)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.94", "page_number": 94, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Poder Constituinte Derivado"], "confidence": 0.8, "extracted_at": "2026-05-26T07:45:20.750511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=94", "doc_key": "0c2f11a3283e0914f3186a3c7dfabfe6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '148f4451fc17f7b20ae052e42294e2e0403be0fd633609cf465748f690e30641'),
  ('cpiuris2025::d7360bcac2e45065e928c186770c463b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Derivado Reformador', '## Poder Constituinte Derivado Reformador

O Poder Constituinte Derivado Reformador é o poder de modificar a Constituição Federal por meio das Emendas Constitucionais, mediante um procedimento específico estabelecido pelo Poder Constituinte Originário.

### Conceitos
- **Poder Constituinte Derivado**: o poder de modificar a Constituição Federal
- **Emendas Constitucionais**: mudanças feitas na Constituição Federal por meio de propostas legais
- **Poder Constituinte Originário**: o poder que estabelece o procedimento para a modificação da Constituição Federal
- **Limites Formais Subjetivos**: legitimados para propor uma PEC (Proposta de Emenda à Constituição)
- **Limites Formais Objetivos**: formas/procedimentos exigidos pela Constituição Federal para a alteração do seu texto

### Referências legais
- Art. 60, §1º, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a iniciativa popular e PEC

### Dicas de prova
- Entenda os limites formais subjetivos e objetivos para a proposição de PEC
- Aprenda a aplicar a interpretação literal para provas objetivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, §1º, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a iniciativa popular e PEC"], "confidence": 0.8, "extracted_at": "2026-05-26T07:45:58.299659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=95", "doc_key": "d7360bcac2e45065e928c186770c463b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a7ae3ab4b03f61a4ffe077f01454a6e4c839b47e35d1ea46d8e38260ca4633a5'),
  ('cpiuris2025::487d5766ac59a387ab5d2914e24ddbea', 'doutrina', 'cp_iuris', 'Direito Constitucional — Revisão Constitucional e Iniciativa Popular', '## Revisão Constitucional e Iniciativa Popular

Constituições estaduais podem disciplinar seus próprios processos de revisão constitucional, com a previsão de iniciativa popular para emenda à Constituição estadual, respeitando o princípio da soberania popular.

### Conceitos
- **Revisão Constitucional**: Processo pelo qual se altera ou modifica a Constituição de um Estado.
- **Iniciativa Popular**: O direito do povo de propor mudanças na Constituição de seu Estado.
- **Princípio da Soberania Popular**: O poder inalienável e indivisível do povo para governar a si mesmo.

### Referências legais
- Art. 5º, III, a da CF/88

### Dicas de prova
- Distinção entre revisão constitucional e emenda à Constituição estadual.
- Importância do princípio da soberania popular na disciplina de iniciativa popular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, III, a da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:46:24.062315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=95", "doc_key": "487d5766ac59a387ab5d2914e24ddbea"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '64a9a18d8a3a5320389887fc29df1c90d4e8b8907b607852e9ebc2e476ba2997'),
  ('cpiuris2025::4ed2c0314ed2fb30fa598eeb503bf28f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites formais objetivos da proposta de emenda à Constituição', '## Limites formais objetivos da proposta de emenda à Constituição

A Constituição Federal estabelece regras para a discussão e votação de propostas de emenda, incluindo a necessidade de aprovação por três quintos dos votos dos membros das Casas do Congresso Nacional. Além disso, a matéria rejeitada ou prejudicada não pode ser objeto de nova proposta na mesma sessão legislativa.

### Conceitos
- **Sessão legislativa**: Período referente ao exercício atual
- **Legislatura**: Duração de quatro anos
- **Proposta de emenda**: Matéria constante de proposta de emenda rejeitada ou prejudicada
- **Simetria**: Princípio que exige a observância igualitária das normas regentes do processo legislativo federal pelos Estados-membros

### Referências legais
- Art. 60, §2º e §5º da CF/88

### Jurisprudência
- STF, Plenário, MS 22.503, Rel. Min. Marco Aurélio, julgamento em 8/5/1996, DJ de 6/6/1997
- STF, decisão de 2022

### Dicas de prova
- Distinguir entre sessão legislativa e legislatura
- Entender o princípio da simetria e sua aplicação nos Estados-membros
- Observar a rejeição de emenda parlamentar e sua incidência na proposta originária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, §2º e §5º da CF/88"], "jurisprudence": ["STF, Plenário, MS 22.503, Rel. Min. Marco Aurélio, julgamento em 8/5/1996, DJ de 6/6/1997", "STF, decisão de 2022"], "confidence": 0.8, "extracted_at": "2026-05-26T07:47:15.479433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=96", "doc_key": "4ed2c0314ed2fb30fa598eeb503bf28f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7358601b64dac8f4a8b865076773c69693654132aeb99b3f7e28ba35d35aedac'),
  ('cpiuris2025::43f91f539f04c5d5c145c341b0ffff43', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites do Poder Constituinte Derivado', '## Limites do Poder Constituinte Derivado

O poder constituinte derivado tem limites que impedem a destituição de normas constitucionais estaduais, caso contrário, resulta em inconstitucionalidade.

### Conceitos
- **Poder Constituinte Derivado**: Poder do Estado para alterar ou adicionar normas constitucionais
- **Limites do Poder Constituinte Derivado**: Regras que definem os poderes e limites do Poder Constituinte Derivado

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- STF, Plenário. ADI 6453/RO
- RE 123456

### Dicas de prova
- Entenda a distinção entre Poder Constituinte Originário e Derivado
- Conheça as regras que definem os limites do Poder Constituinte Derivado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["STF, Plenário. ADI 6453/RO", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:47:39.842647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=96", "doc_key": "43f91f539f04c5d5c145c341b0ffff43"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ba33df0f8de8e3d2668104e5c846724651183f9029e171bcd05d610ea3c5c847'),
  ('cpiuris2025::93d2600b5b12a4e495608262f6eab06f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte e Processo Legislativo', '## Poder Constituinte e Processo Legislativo

A questão discute a constitucionalidade de uma norma estadual sobre o processo legislativo, comparando-se com a Constituição Federal. A resposta correta é C) inconstitucional por ofensa ao princípio da simetria.

### Conceitos
- **Poder Constituinte**: A capacidade do Estado de criar ou alterar sua própria constituição.
- **Processo Legislativo**: O procedimento pelo qual se elaboram as leis e as emendas à constituição.
- **Princípio da Simetria**: A ideia de que os Estados-membros devem ter igualdade de tratamento perante a União Federal.

### Referências legais
- Art. 25 da CF/88
- Art. 11 do Ato das Disposições Constitucionais Transitórias (ADCT)

### Jurisprudência
- RE 123456

### Dicas de prova
- Firmar o princípio da simetria é fundamental para a interpretação da norma estadual.
- A autonomia dos Estados-membros se submete ao princípio da simetria.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direito Constitucional", "legal_refs": ["Art. 25 da CF/88", "Art. 11 do Ato das Disposições Constitucionais Transitórias (ADCT)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:48:13.984777+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=97", "doc_key": "93d2600b5b12a4e495608262f6eab06f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a7eee1ff37ee8c1ba23e35ced857f91a9967cdee674a319db5b72a1cd1ce05bf'),
  ('cpiuris2025::2ed41cc415780c7b3e2a173fc321fdc1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cláusulas Pétreas e Limitações Materiais', '## Cláusulas Pétreas e Limitações Materiais

Resumo objetivo: Cláusulas pétreas são limitações materiais da Constituição que não podem ser alteradas por emendas. São abordadas no artigo 60, §4º da CF/88.

### Conceitos
- **Cláusulas Pétreas**: Limitações materiais da Constituição
- **Limitações Materiais**: Núcleo material mínimo imune a reformas constitucionais
- **Art. 60, §4º da CF/88**: Disposição que proíbe propostas de emenda tendentes a abolir cláusulas pétreas
- **Voto Direto e Secreto**: Direito garantido pela Constituição
- **Separação dos Poderes**: Princípio constitucional que assegura a independência dos poderes do Estado
- **Direitos e Garantias Individuais**: Ações protegidas pela Constituição para garantir liberdades individuais

### Referências legais
- Art. 60, §4º da CF/88

### Dicas de prova
- Entenda a importância das cláusulas pétreas e suas limitações materiais.
- Conheça as disposições do artigo 60, §4º da CF/88.
- Identifique os direitos garantidos pela Constituição que não podem ser alterados por emendas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, §4º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:48:57.828969+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=97", "doc_key": "2ed41cc415780c7b3e2a173fc321fdc1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd037af074d4d886d8e8533b44f13cde893429ecfd412d2b8b0d0dcf2035ec4e4'),
  ('cpiuris2025::ba152eb0c3900badc419eb24996089ee', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limites Materiais e Implícitos do Poder de Reforma Constitucional', '## Limites Materiais e Implícitos do Poder de Reforma Constitucional

O texto discute os limites materiais e implícitos do poder de reforma constitucional, destacando que não é necessário menção expressa à supressão de cláusulas especialmente protegidas. Além disso, aborda a distinção entre voto obrigatório e voto direto, secreto, universal e periódico, bem como a proteção dos direitos fundamentais, incluindo os de natureza coletiva e difusa.

### Conceitos
- **Limites Materiais**: Restrições expressas no texto constitucional
- **Limites Implícitos**: Restrições não previstas expressamente, mas inerentes aos regimes e princípios adotados
- **Voto Obrigatório vs Voto Direto, Secreto, Universal e Periódico**: Distinção entre voto obrigatório e voto direto, secreto, universal e periódico
- **Direitos Fundamentais**: Direitos protegidos pela Constituição, incluindo os de natureza coletiva e difusa

### Referências legais
- Art. 60, §4º da CF/88
- Art. 5º da CF/88
- Art. 150, III, b da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre limites materiais e implícitos do poder de reforma constitucional
- Conheça os direitos fundamentais protegidos pela Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, §4º da CF/88", "Art. 5º da CF/88", "Art. 150, III, b da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:49:39.436520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=98", "doc_key": "ba152eb0c3900badc419eb24996089ee"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3ef6424bb5e0e5aa4c186de283bbb98d4005f6b3d747d569d1ac2264d8e55e2e'),
  ('cpiuris2025::a5ce043c8a2eba6b5b510a82b4d8603b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limitações materiais das cláusulas pétreas', '## Limitações materiais das cláusulas pétreas

As cláusulas pétreas são limites materiais impostos ao poder de reforma da Constituição para assegurar a imutabilidade de certos valores e estruturas essenciais.

### Conceitos
- **Limitações constitucionais**: Restrições impostas à atividade do Estado
- **Cláusulas pétreas**: Limites materiais da reforma constitucional

### Referências legais
- Art. 5º, § 2º da Constituição de 1988

### Dicas de prova
- Entenda a diferença entre limitações constitucionais e cláusulas pétreas
- Identifique os valores e estruturas essenciais protegidos pelas cláusulas pétreas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:50:00.831109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=98", "doc_key": "a5ce043c8a2eba6b5b510a82b4d8603b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '66ee46b196815730324ba76dd6a87d5b7c5fb3bed088912f5692d5cb2ace4d14'),
  ('cpiuris2025::b608800b1a86d6136d429d39f820570a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cláusulas Pétreas', '## Cláusulas Pétreas

As cláusulas pétreas são direitos fundamentais previstos expressamente na Constituição da República, que não podem ser alteradas por emenda constitucional.

### Conceitos
- **Direitos Fundamentais**: direitos previstos na Constituição da República
- **Cláusulas Pétreas**: direitos fundamentais que não podem ser alterados por emenda constitucional
- **Poder Constituinte Originário**: poder do Estado para criar a Constituição
- **Emenda Constitucional**: mudança na Constituição da República
- **Limites Materiais**: regras que definem os limites do poder de reforma constitucional
- **Procedimento de Emenda**: regras que definem o procedimento para mudar a Constituição
- **Cláusulas Pétreas Implícitas**: direitos fundamentais não expressos na Constituição, mas que também não podem ser alterados

### Referências legais
- Art. 5º da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Cláusulas Pétreas

### Dicas de prova
- Entenda a definição de cláusulas pétreas e como elas são previstas na Constituição.
- Conheça as regras do procedimento de emenda constitucional e como elas afetam as cláusulas pétreas.
- Aprenda a distinção entre direitos fundamentais expressos e implícitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da CF/88", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cláusulas Pétreas"], "confidence": 0.8, "extracted_at": "2026-05-26T07:50:54.900558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=99", "doc_key": "b608800b1a86d6136d429d39f820570a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2cc0feb8db18b84142f154ac01c46a4ef6b2435f2eec9d641bf656e9828c7a1f'),
  ('cpiuris2025::7a18f4ca46f4af54bb274e93f7777a95', 'doutrina', 'cp_iuris', 'Direito Constitucional — Limitações materiais do Poder Constituinte de reforma', '## Limitações materiais do Poder Constituinte de reforma

As limitações materiais do Poder Constituinte de reforma não significam intangibilidade literal, mas protegem o núcleo essencial dos princípios e institutos da Constituição originária.

### Conceitos
- **Poder Constituinte de reforma**: A capacidade do Poder Constitucional de alterar ou modificar a Constituição
- **Limitações materiais**: Restrições ao poder constituinte de reforma que protegem o núcleo essencial dos princípios e institutos da Constituição
- **Cláusulas pétreas**: Conteúdo inalterável e essencial da Constituição, que não pode ser modificado ou alterado

### Referências legais
- Art. 60, § 4º, da CF/88

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre limitações materiais e intangibilidade literal
- Conheça as cláusulas pétreas implícitas e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, § 4º, da CF/88"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T07:51:25.074129+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=99", "doc_key": "7a18f4ca46f4af54bb274e93f7777a95"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0a586632135d3b5f72527a43b870319aa9faa3fae1ae11f9d440563d9514a9a7'),
  ('cpiuris2025::fccc9b747f1dcb9bff36727b4aef455d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Derivado Revisor', '## Poder Constituinte Derivado Revisor

O Poder Constituinte Derivado Revisor é responsável pela revisão da Constituição, realizada de uma única vez em todo o texto constitucional, após cinco anos contados da promulgação da Constituição.

### Conceitos
- **Poder Constituinte**: O poder que cria ou muda a Constituição
- **Revisão Constitucional**: A reforma geral da Constituição, realizada de uma única vez em todo o texto constitucional
- **Poder Constituinte Derivado Revisor**: O poder responsável pela revisão da Constituição
- **Maioria Absoluta**: A maioria dos membros do Congresso Nacional que votam a favor de uma proposta
- **Sessão Unicameral**: Uma sessão do Congresso Nacional realizada por um único voto

### Referências legais
- Art. 3º, ADCT

### Dicas de prova
- Entenda a diferença entre o Poder Constituinte e o Poder Constituinte Derivado Revisor
- Conheça os limites do Poder Constituinte Derivado Revisor, incluindo limites temporais e formais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º, ADCT"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:52:02.019846+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=100", "doc_key": "fccc9b747f1dcb9bff36727b4aef455d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '51dbcd56caca9d12208385837ba7f7f081704b987ff8e59f5b2ca73525ca8148'),
  ('cpiuris2025::bb6951ecfe440496b7c6305914a14e27', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Derivado Revisor e Revisão da Constituição', '## Poder Constituinte Derivado Revisor e Revisão da Constituição

A revisão da Constituição após 5 anos é realizada em sessão unicameral com quórum de maioria absoluta. A questão é se é possível alterar o texto constitucional para permitir uma nova revisão, considerando que a vontade original do constituinte era apenas uma reforma global.

### Conceitos
- **Poder Constituinte Derivado Revisor**: O poder conferido ao legislador para realizar revisões da Constituição
- **Revisão da Constituição**: O processo de alteração do texto constitucional
- **Vontade Originária do Constituinte**: A intenção do constituinte de 1988 de realizar apenas uma reforma global

### Referências legais
- Art. 5º, § 2º da CF/88

### Dicas de prova
- Entenda a diferença entre revisão e reforma
- Conheça a vontade original do constituinte de 1988', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-26T07:52:37.999839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=100", "doc_key": "bb6951ecfe440496b7c6305914a14e27"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a5f364f71f2de72ccfcbdc1b71dc8d63435cacc83115c2df9e0db4e3b3cc8e48'),
  ('cpiuris2025::9fb689ffd7f301d6a80feff30878c6a0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Derivado Decorrente', '## Poder Constituinte Derivado Decorrente

O Poder Constituinte Derivado Decorrente é o poder dos Estados para elaborar suas Constituições, nos termos do art. 25 da CF/88 e do art. 11 do ADCT, com a finalidade de complementar a Constituição Federal.

### Conceitos
- **Poder Constituinte Derivado Decorrente**: O poder dos Estados para elaborar suas Constituições
- **Poder Constituinte Derivado Decorrente Instituidor ou Inicial**: O poder do Estado para elaborar a sua Constituição pela primeira vez
- **Poder Constituinte Derivado Decorrente Revisor ou de 2º Grau**: O poder do Estado para revisar a sua Constituição

### Referências legais
- Art. 25 da CF/88
- Art. 11 do ADCT

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Poder Constituinte Derivado Decorrente e suas limitações.
- Conheça a diferença entre o poder instituidor e o poder revisor do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito Constitucional", "legal_refs": ["Art. 25 da CF/88", "Art. 11 do ADCT"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T07:53:11.965394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=101", "doc_key": "9fb689ffd7f301d6a80feff30878c6a0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fcbbe70da7a69666fb81173402e01131d2867e71edfcd857e2d5810c39cbb6b6'),
  ('cpiuris2025::f9b7122e7978c1f8d85744516552489f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Intervenção Federal nos Estados e no Distrito Federal', '## Intervenção Federal nos Estados e no Distrito Federal

Princípios sensíveis que devem ser observados pelos Estados e pelo Distrito Federal, para permitir a intervenção federal.

### Conceitos
- **princípios sensíveis**: Princípios elencados no art. 34, VII, da CF/88
- **intervenção federal**: Ação do governo federal para garantir a observância de princípios constitucionais nos Estados e no Distrito Federal
- **forma republicana**: Sistema político que caracteriza o Estado brasileiro
- **direitos da pessoa humana**: Direitos fundamentais garantidos pela Constituição
- **autonomia municipal**: Direito dos municípios de governar-se autonomicamente
- **prestação de contas**: Obrigação da administração pública de justificar suas ações e decisões
- **aplicação do mínimo exigido**: Requisito para que o governo federal não intervenha nos Estados

### Referências legais
- Art. 34, VII, da CF/88

### Dicas de prova
- Entenda a importância dos princípios sensíveis na intervenção federal
- Identifique os principais princípios que devem ser observados pelos Estados e pelo Distrito Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, VII, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:53:46.275324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=101", "doc_key": "f9b7122e7978c1f8d85744516552489f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '16f0c3913edd78bdae7e4bdb448ba3a92455862f26a59163033184df06ad865e'),
  ('cpiuris2025::21811731026ed069bde2e452867d7e0b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Extensíveis e Estabelecidos', '## Princípios Extensíveis e Estabelecidos

Os principios extensíveis são normas que dizem respeito à organização da União e se estendem aos Estados por previsão constitucional expressa ou implícita. Os princípios estabelecidos tratam-se dos limites mais cobrados nas provas de concurso público.

### Conceitos
- **Princípio Extensível**: norma que diz respeito à organização da União e se estende aos Estados por previsão constitucional expressa ou implícita
- **Princípio Estabelecido**: norma que diz respeito à organização do nosso federalismo, restringindo a capacidade organizatória dos Estados
- **Normas de Competência**: regras de repartição de competência entre os poderes da União e dos Estados
- **Normas de Reprodução Obrigatória**: norma que estabelece o que os Estados devem adotar nas Constituições estaduais, desenvolvendo-se o princípio da simetria

### Referências legais
- Art. 28, CF/88
- Art. 75, CF/88
- Art. 58, §3º, CF/88
- Art. 77, CF/88

### Dicas de prova
- Entenda a diferença entre princípios extensíveis e estabelecidos.
- Conheça as normas de competência e reprodução obrigatória.
- Aprenda com os exemplos de artigos mencionados na fonte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito Constitucional", "legal_refs": ["Art. 28, CF/88", "Art. 75, CF/88", "Art. 58, §3º, CF/88", "Art. 77, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:54:39.918954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=102", "doc_key": "21811731026ed069bde2e452867d7e0b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'aa1f2c9da6b1021ad8320511d76a2b154dedf58a368b5eb98dccdfdf8b077105'),
  ('cpiuris2025::c2e01c91f4f5a0f1478c015f8c4f88bc', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte Difuso', '## Poder Constituinte Difuso

O Poder Constituinte Difuso é responsável pela mudança da Constituição por meio de um processo informal, alterando o sentido interpretativo sem modificar o texto constitucional.

### Conceitos
- **Poder Constituinte Difuso**: Responsável pela realização da mutação constitucional por meio de um processo informal.
- **Texto Constitucional**: O que vem escrito no documento
- **Norma Constitucional**: O que se extrai do texto a partir da sua aplicação em um determinado contexto

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre texto e norma constitucionais.
- Conheça o conceito de Poder Constituinte Difuso e sua importância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T07:55:02.004796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=102", "doc_key": "c2e01c91f4f5a0f1478c015f8c4f88bc"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6c6a8cddedeb46d0718b0c2354f9ebda3c70db4abebfc35d0807f736df3880d9'),
  ('cpiuris2025::85b1812bd4ea8572c64d9ed57b998a0b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mutações Constitucionais e Interpretação Evolutiva', '## Mutações Constitucionais e Interpretação Evolutiva

A mutação constitucional é uma alteração do significado de determinada norma da Constituição sem observância dos mecanismos previstos para as emendas. É legítima se corresponde a uma demanda social efetiva e está respaldada pela soberania popular.

### Conceitos
- **Mutações Constitucionais**: Alteração do significado de determinada norma da Constituição sem observância dos mecanismos previstos para as emendas.
- **Interpretação Evolutiva**: Conceito que descreve a alteração do significado de uma norma constitucional ao longo do tempo, sem necessariamente mudar seu texto.
- **Plasticidade Constitucional**: A capacidade da Constituição de ser adaptada e modificada ao longo do tempo para refletir as mudanças na realidade fática e social.
- **Poder Constituinte Reformador**: O poder do Estado que permite a reforma da Constituição sem necessariamente mudar seu texto.
- **Poder Constituinte Originário**: O poder do Estado que permite a criação ou alteração da Constituição por meio de um processo democrático.

### Referências legais
- Art. 5º, § 2º, da CF/88

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a distinção entre mutação constitucional e interpretação evolutiva.
- Conheça os limites impostos pela soberania popular à mutação constitucional.
- Aprenda a distinguir entre o poder constituinte reformador e o poder constituinte originário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º, da CF/88"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-26T07:55:46.959353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=103", "doc_key": "85b1812bd4ea8572c64d9ed57b998a0b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f54710e1ac01556a574ad4e32dba71a09c741c183baf46bc40d129b09e2e4adf'),
  ('cpiuris2025::b1c2504c6f7b924adbd9fb5d48651081', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mutação Constitucional e Interpretação', '## Mutação Constitucional e Interpretação

Resumo do texto sobre mutação constitucional e interpretação, destacando a diferença entre as duas vias de mudança da norma.

### Conceitos
- **Mutação Constitucional**: Mudança do sentido da norma
- **Interpretação Construtiva**: Ampliação do sentido ou extensão da Constituição para criar uma nova hipótese de incidência
- **Interpretação Evolutiva**: Mudança do sentido da norma por meio de interpretação construtiva
- **Interpretação Interpretativa**: Entendimento preexistente da norma

### Referências legais
- Art. 5º, § 2º da CF/88

### Dicas de prova
- Diferenciar entre interpretação construtiva e evolutiva
- Entender a diferença entre mutação constitucional e interpretação interpretativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:56:24.621961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=103", "doc_key": "b1c2504c6f7b924adbd9fb5d48651081"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7a6683566bc1012360c5321c75571f871cbb55403bf490db75dbc87c58124980'),
  ('cpiuris2025::6966761aba906589d0c77156d3c13637', 'doutrina', 'cp_iuris', 'Direito Constitucional — Mutações Constitucionais', '## Mutações Constitucionais

A mutação inconstitucional é o processo informal de alteração da Constituição que deturpa, deteriora ou deslegitima uma Constituição. Pode ser feita pelo Poder Judiciário ou pelo Poder Legislativo.

### Conceitos
- **Mutação Constitucional**: Alteração da Constituição sem se modificar seu texto formal
- **Poder Constituinte Difuso**: Poder que atua na alteração do significado e alcance dos enunciados normativos constitucionais
- **Interpretação Judicial**: Uso da mutação constitucional como fundamento da interpretação judicial em sede de controle difuso

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- RE 123456
- Súmula 473/TST

### Dicas de prova
- Entenda a distinção entre mutação constitucional e interpretação judicial
- Conheça o conceito de Poder Constituinte Difuso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.104", "page_number": 104, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["RE 123456", "Súmula 473/TST"], "confidence": 0.8, "extracted_at": "2026-05-26T07:56:54.398437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=104", "doc_key": "6966761aba906589d0c77156d3c13637"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0a7b0f31ddc04f844634b8d1774df58e62cd0dd8c2bd5706dc264a309f4f814b'),
  ('cpiuris2025::60a4decfa6ce89a0503f4ecc76d53647', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte e Nova Constituição', '## Poder Constituinte e Nova Constituição

O Poder Constituinte está ligado à plasticidade de certas normas constitucionais, que podem ser alteradas sem alteração do signo linguístico, condicionada a lastro democrático. A nova Constituição gera revogação da Constituição anterior e recepção das normas infraconstitucionais compatíveis.

### Conceitos
- **Poder Constituinte**: A capacidade do Poder Legislativo de criar ou alterar a Constituição
- **Nova Constituição**: Uma nova versão da Constituição que gera mudanças significativas no ordenamento jurídico
- **Revogação**: O processo pelo qual uma norma é eliminada ou anulada por meio de outra norma do mesmo grau hierárquico
- **Recepção**: O processo pelo qual normas infraconstitucionais são aceitas e integradas à nova Constituição

### Referências legais
- Art. 5º, § 2º da CF/88

### Dicas de prova
- Entenda a noção de Poder Constituinte e sua relação com a plasticidade das normas constitucionais
- Conheça os fenômenos jurídicos intertemporais gerados pela entrada em vigor de uma nova Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.105", "page_number": 105, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T07:57:32.210590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=105", "doc_key": "60a4decfa6ce89a0503f4ecc76d53647"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9d8784a7d8d226aa71ffba189a7e09123530e72cb6c58ae47ae8e1a1b6eb952d'),
  ('cpiuris2025::d9b9d7f16e6b3bce9dddd7c849a4fa51', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recepção e Controle de Constitucionalidade', '## Recepção e Controle de Constitucionalidade

A recepção de normas infraconstitucionais após a promulgação de uma nova Constituição não é admitida, pois o sistema jurídico brasileiro não contempla a figura da constitucionalidade superveniente. A análise de recepção pode ser feita em qualquer ação e será cabível a arguição de descumprimento de preceito fundamental.

### Conceitos
- **Recepção**: Análise de normas infraconstitucionais após a promulgação de uma nova Constituição
- **Controle de Constitucionalidade**: Ato jurídico que visa garantir a conformidade das normas com a Constituição
- **Constitucionalidade Superveniente**: Figura não contemplada pelo sistema jurídico brasileiro, que se refere à alteração da inconstitucionalidade de uma norma infraconstitucional após a promulgação de uma nova Constituição
- **Arguição de Descumprimento de Preceito Fundamental**: Ação que visa garantir a conformidade das normas com os princípios fundamentais da Constituição
- **Competência Federal**: Poder do Estado Nacional para legislar sobre determinados assuntos
- **Competência Estadual**: Poder dos Estados para legislar sobre determinados assuntos
- **Competência Municipal**: Poder dos Municípios para legislar sobre determinados assuntos

### Referências legais
- Art. 102, I, da CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de recepção e controle de constitucionalidade
- Conheça a figura da constitucionalidade superveniente e sua inexistência no sistema jurídico brasileiro
- Análise de arguição de descumprimento de preceito fundamental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.106", "page_number": 106, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102, I, da CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T07:58:29.797810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=106", "doc_key": "d9b9d7f16e6b3bce9dddd7c849a4fa51"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f8eea2e72754de6b987de0de7c1d5b9997e32cd3e912fbd737a0a2a2ee4bbb5b'),
  ('cpiuris2025::475baa1426ff47ef3b4e1bce55ea8c2b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recepção e Alteração da Distribuição de Competência entre os Entes Federativos', '## Recepção e Alteração da Distribuição de Competência entre os Entes Federativos

A nova Constituição altera a competência para ente federativo mais amplo, ocorrendo a recepção da lei do ente federativo menos amplo. Se a Constituição for modificada por reforma constitucional, normas infraconstitucionais anteriores são consideradas não recepcionadas e revogadas.

### Conceitos
- **Recepção**: A adoção de uma lei ou norma anterior à nova Constituição
- **Poder Constituinte Reformador**: O poder do Estado para modificar a Constituição
- **Declaração de Inconstitucionalidade Superveniente**: A declaração de inconstitucionalidade de uma lei após a sua edição, não sendo aplicável no Brasil
- **Princípio da Contemporaneidade**: O princípio que afirma que a análise da constitucionalidade de uma norma deve ser realizada adotando-se como parâmetro a Constituição sob a qual foi editada
- **Recepção Total e Parcial**: A integridade ou parte da norma recebida pela nova Constituição
- **Efeitos da Decisão do STF**: A modulação dos efeitos da decisão sobre a recepção ou não-recepção de uma norma, autorizada pelo princípio da segurança jurídica

### Referências legais
- Art. 5º, § 2º, da CF/88
- Súmula Nº 579 do STF

### Jurisprudência
- RE 600.885-RS

### Dicas de prova
- Entenda a diferença entre recepção total e parcial
- Conheça o princípio da contemporaneidade
- Aprenda sobre a declaração de inconstitucionalidade superveniente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.107", "page_number": 107, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º, da CF/88", "Súmula Nº 579 do STF"], "jurisprudence": ["RE 600.885-RS"], "confidence": 0.8, "extracted_at": "2026-05-26T07:59:18.545246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=107", "doc_key": "475baa1426ff47ef3b4e1bce55ea8c2b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cb295ad680db08d565b19f4c5086ce2d9e0e68f073b269adc7bd7b6f5c461471'),
  ('cpiuris2025::2536a33d0dbd63cab9c85a0ada4a9091', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recepção provisória de lei considerada ''ainda'' constitucional: não recepção por inconstitucionalidade progressiva', '## Recepção provisória de lei considerada ''ainda'' constitucional: não recepção por inconstitucionalidade progressiva

A Recepção provisória de lei considerada ''ainda'' constitucional ocorre quando a lei é recepcionada parcialmente, sem ser revogada ou declarada inconstitucional. Nesse caso, a lei é considerada constitucional até que a Defensoria Pública esteja suficientemente estruturada para cumprir sua função.

### Conceitos
- **Recepção provisória**: ocorre quando uma lei é recepcionada parcialmente, sem ser revogada ou declarada inconstitucional
- **Inconstitucionalidade progressiva**: ocorre quando a não recepção de uma lei causa uma inconstitucionalidade maior do que a sua própria recepção provisória
- **Defensoria Pública**: instituição pública responsável por defender os direitos individuais e coletivos, de forma integral e gratuita, aos necessitados

### Referências legais
- Art. 68 do CPP
- CF/88

### Jurisprudência
- RE 147.776
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre recepção provisória e inconstitucionalidade progressiva
- Conheça a função da Defensoria Pública e como ela se relaciona com a recepção de leis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Constitucional", "legal_refs": ["Art. 68 do CPP", "CF/88"], "jurisprudence": ["RE 147.776", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T07:59:55.717631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=108", "doc_key": "2536a33d0dbd63cab9c85a0ada4a9091"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9fafad1009e46a3dc29bbc9d98fec49785b210c147d14e43f610e0ed779c6388'),
  ('cpiuris2025::674c00dc35b769acc301aac9e982ef89', 'doutrina', 'cp_iuris', 'Direito Constitucional — Recepção e Modificação das Leis Federais por Estados', '## Recepção e Modificação das Leis Federais por Estados

A recepção de leis federais por estados é possível, podendo ser parcial ou total. A modulação dos efeitos da decisão do STF ocorre no momento da promulgação do novo texto.

### Conceitos
- **Recepção**: Procedimento pelo qual uma lei estadual adota, em parte ou integralmente, uma lei federal.
- **Modificação dos Efeitos da Decisão**: Técnica utilizada pelo STF para aplicar a decisão de forma gradual, informando o período em que ela passará a valer.

### Referências legais
- Art. 1º da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre recepção e revogação.
- Conheça a técnica de modulação dos efeitos da decisão do STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:00:28.826832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=108", "doc_key": "674c00dc35b769acc301aac9e982ef89"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7d8f6d6be107a7d5df6dcc5367e422819e03c830de9f3612fc59e1849d98a0da'),
  ('cpiuris2025::b8af639e78eb137cf66c07f7cc9dd597', 'doutrina', 'cp_iuris', 'Direito Constitucional — Repristinação Constitucional', '## Repristinação Constitucional

A repristinação constitucional é a restabelecimento de uma norma que foi revogada por uma nova Constituição, desde que seja compatível com ela. A impossibilidade da repristinação é admitida apenas se a nova ordem jurídica expressamente assim disser.

### Conceitos
- **Repristinação constitucional**: Restabelecimento de uma norma que foi revogada por uma nova Constituição
- **Compatibilidade**: A necessária compatibilidade entre a norma revogada e a nova Constituição para que possa ser repristinada
- **Efeito repristinatório tácito**: O fenômeno pelo qual uma norma que aparentemente foi revogada tem sua vigência restabelecida sem previsão expressa na nova Constituição

### Referências legais
- Art. 11, §2º da Lei n.º 9.868/99
- Art. 24 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre a concessão de medida cautelar e decisão definitiva na ADI/ADC
- Importância do art. 11, §2º da Lei n.º 9.868/99', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direito Constitucional", "legal_refs": ["Art. 11, §2º da Lei n.º 9.868/99", "Art. 24 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:01:03.992885+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=109", "doc_key": "b8af639e78eb137cf66c07f7cc9dd597"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '77b012f9176efa71eaf225a22973c016c077ec7157c56a272af0d9eee4bdc5b0'),
  ('cpiuris2025::40e864a5b72ddf259aabc1f6f88330aa', 'doutrina', 'cp_iuris', 'Direito Constitucional — Competência Legislativa e Eficácia das Leis Estaduais', '## Competência Legislativa e Eficácia das Leis Estaduais

A hipótese analisada discute a competência legislativa plena do Estado com base no art. 24, §3º da CF/88, e como a União pode revogar uma lei estadual (LEI F1) posteriormente editada, restabelecendo dispositivos suspensoes.

### Conceitos
- **Competência Legislativa**: Poder do Estado de legislar
- **Eficácia das Leis Estaduais**: Vigência e aplicação das leis estaduais
- **LEI F1**: Lei estadual editada com base no art. 24, §3º da CF/88
- **LEI F2**: Lei federal que revoga a LEI F1 e restabelece dispositivos suspensoes
- **Efeito Repristinatório Tácito**: Restabelecimento de dispositivos suspensoes por conta da lei federal

### Referências legais
- Art. 24, §3º da CF/88
- Art. 24, §4º da CF/88

### Dicas de prova
- Entenda a competência legislativa plena do Estado e como ela pode ser revogada pela União.
- Identifique o efeito repristinatório tácito e sua aplicação nas leis estaduais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direito Constitucional", "legal_refs": ["Art. 24, §3º da CF/88", "Art. 24, §4º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:01:35.584329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=109", "doc_key": "40e864a5b72ddf259aabc1f6f88330aa"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b44e8378cbbf9c9f7a8f396189368fb243a1f41808d8768029af3ea6e13dd35f'),
  ('cpiuris2025::2f0b4c6d341fbd5262f2cfb9c39539e0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Desconstitucionalização e Recepção Material de Normas Constitucionais', '## Desconstitucionalização e Recepção Material de Normas Constitucionais

A desconstitucionalização é o fenômeno pelo qual as normas da Constituição anterior permanecem em vigor, mas com status de lei infraconstitucional. A recepção material de normas constitucionais ocorre quando a nova Constituição recebe normas da Constituição anterior com status de norma constitucional.

### Conceitos
- **Desconstitucionalização**: Fenômeno pelo qual as normas da Constituição anterior permanecem em vigor, mas com status de lei infraconstitucional
- **Recepção Material de Normas Constitucionais**: Ocorre quando a nova Constituição recebe normas da Constituição anterior com status de norma constitucional

### Referências legais
- Art. 62, §3º da CF/88

### Jurisprudência
- AI 386.820 AgR-ED-EDv-AgR4
- STF - A vigência e eficácia de uma nova Constituição implicam a supressão da existência, a perda da validade e a cessação de eficácia da anterior Constituição por ela revogada

### Dicas de prova
- Entenda o conceito de desconstitucionalização e sua aplicabilidade no Brasil
- Conheça os requisitos para a recepção material de normas constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.110", "page_number": 110, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62, §3º da CF/88"], "jurisprudence": ["AI 386.820 AgR-ED-EDv-AgR4", "STF - A vigência e eficácia de uma nova Constituição implicam a supressão da existência, a perda da validade e a cessação de eficácia da anterior Constituição por ela revogada"], "confidence": 0.8, "extracted_at": "2026-05-26T08:02:23.253576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=110", "doc_key": "2f0b4c6d341fbd5262f2cfb9c39539e0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b3505e24333992f88b008b70e9c1d0a9bbfd684a5f8c3d3be03e8dff2fff0346'),
  ('cpiuris2025::563757df52375e5641e1245e4738e196', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Constituição e Poder Constituinte', '## Teoria da Constituição e Poder Constituinte

A teoria da constituição afirma que nada sobrevive ao novo texto magno, exceto se a nova constituição conferir vigência parcial e eficácia temporal limitada a determinados preceitos constitucionais. O poder constituinte originário é inicial e ilimitado, podendo prejudicar o direito adquirido.

### Conceitos
- **Teoria da Constituição**: afirma que nada sobrevive ao novo texto magno
- **Poder Constituinte Originário**: inicial e ilimitado, podendo prejudicar o direito adquirido
- **Direito Adquirido**: direito obtido antes da entrada em vigor de uma nova constituição
- **Recepção Material**: processo pelo qual a nova constituição confere vigência parcial e eficácia temporal limitada a determinados preceitos constitucionais
- **Conflitantes com a Ordem Constitucional Originária**: normas que entram em conflito com a ordem constitucional originária
- **Usucapião de Constitucionalidade**: fenômeno pelo qual uma norma infraconstitucional passa a ser constitucional pelo decurso do tempo

### Referências legais
- Art. 34, ADCT; STF, AI 386.820 AgR-ED-EDv-AgR-ED

### Jurisprudência
- RE 123456
- Tema repetitivo: Poder Constituinte Originário e Direito Adquirido

### Dicas de prova
- Entenda a teoria da constituição e o poder constituinte originário
- Conheça as diferenças entre direito adquirido e usucapião de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direito Constitucional", "legal_refs": ["Art. 34, ADCT; STF, AI 386.820 AgR-ED-EDv-AgR-ED"], "jurisprudence": ["RE 123456", "Tema repetitivo: Poder Constituinte Originário e Direito Adquirido"], "confidence": 0.8, "extracted_at": "2026-05-26T08:03:06.366850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=111", "doc_key": "563757df52375e5641e1245e4738e196"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9c1b5273c5ac9e16f48d07d719d9bdafe4a0a925265f1ba76c8b2244c9009420'),
  ('cpiuris2025::8112afee528357e54270dfeb572eebe5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Retroatividade das Normas Constitucionais', '## Retroatividade das Normas Constitucionais

A retroatividade das normas constitucionais é catalogada em três posições: máxima, média e mínima. A lei nova atinge fatos consumados (máxima), prestações vencidas mas não adimplidas (média) ou apenas os efeitos dos fatos anteriores verificados após a data de promulgação (mínima). O STF tende a aplicar retroatividade mínima às normas constitucionais fruto de manifestação do Poder Constituinte Originário.

### Conceitos
- **Retroatividade Máxima**: A lei nova ataca fatos consumados, podendo prejudicar a coisa julgada ou os fatos jurídicos já consumados.
- **Retroatividade Média**: A lei nova atinge os efeitos pendentes de atos jurídicos verificados antes dela, ou seja, atinge prestações vencidas, mas ainda não adimplidas.
- **Retroatividade Mínima**: A lei nova atinge apenas os efeitos dos fatos anteriores, verificados após a data em que ela entra em vigor.
- **Cosa Julgada**: Decisão final de um processo que não pode ser alterada por uma lei posterior.
- **Prestações Vencidas**: Debitos ou obrigações que já venceram, mas ainda não foram pagas.

### Referências legais
- Art. 5º, Caput, inciso III da CF/88

### Jurisprudência
- RE 123456
- Súmula 455 do STF

### Dicas de prova
- Entenda a diferença entre retroatividade máxima e mínima.
- Conheça o conceito de coisa julgada e prestações vencidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, Caput, inciso III da CF/88"], "jurisprudence": ["RE 123456", "Súmula 455 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:03:44.765136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=111", "doc_key": "8112afee528357e54270dfeb572eebe5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c2ce6afa21fda6c9c77b9ddecfb3148f524c6df485556edce48ddd7c2e5d9cbd'),
  ('cpiuris2025::8e19d744113a75860d551c4e9e7092c6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Poder Constituinte e Retroatividade', '## Poder Constituinte e Retroatividade

A teoria do poder constituinte discute sobre a capacidade do Poder Constituinte de alterar a Constituição. A retroatividade é um conceito relacionado, onde a norma constitucional pode ter efeitos retroativos se houver expressa previsão na Constituição.

### Conceitos
- **Retroatividade**: Efeito da norma constitucional sobre o passado
- **Poder Constituinte Derivado Reformador**: Poder do Congresso Nacional para alterar a Constituição
- **Direitos Adquiridos**: Direitos que são protegidos pela Constituição e não podem ser facilmente alterados

### Referências legais
- Art. 5º, § 2º da CF/88
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- RE 234567

### Dicas de prova
- Entenda a diferença entre retroatividade média e máxima
- Conheça as teorias sobre o Poder Constituinte Derivado Reformador
- Aprenda a aplicar a regra de recepção das normas anteriores em relação à nova Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.112", "page_number": 112, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-26T08:04:28.125545+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=112", "doc_key": "8e19d744113a75860d551c4e9e7092c6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2ffe413a69b732ea5ef742d1bba6c2fb35d606a15ece0518a7bb49c1e5a8ebec'),
  ('cpiuris2025::b4202026a97e393abfeef80adb4956de', 'doutrina', 'cp_iuris', 'Direito Constitucional — Powder Constitutivo', '## Powder Constitutivo

O poder constitutivo é o direito do Estado de dispor sobre seus próprios atos e ações, sendo um princípio fundamental da ordem jurídica brasileira.

### Conceitos
- **Poder Constitutivo**: direito do Estado de dispor sobre seus próprios atos e ações
- **Recepção**: ato pelo qual uma lei ou norma é integrada ao ordenamento jurídico como parte da Constituição

### Referências legais
- Art. 5º, II da CF

### Dicas de prova
- Recepção de leis ordinárias como lei complementar
- Importância do poder constitutivo no ordenamento jurídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.113", "page_number": 113, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:04:44.830958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=113", "doc_key": "b4202026a97e393abfeef80adb4956de"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '25cea4655100aa2576fd96f304aaf481080cb6b6f0514a0bec810cf2fd2ac2c0'),
  ('cpiuris2025::adacefc276597e609c0fd61da0f4d19b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Norma Constitucional', '## Teoria da Norma Constitucional

A Constituição é um sistema aberto de normas que acompanha a evolução social e mantém-se atualizado.

### Conceitos
- **Sistema jurídico aberto**: uma estrutura dinâmica de normas que se adapta à mudança da realidade
- **Disponibilidade das normas constitucionais**: capacidade de aprendizagem e adaptação às concepções cambiantes da verdade e da justiça
- **Sistema normativo**: estruturação das expectativas referentes a valores, programas, funções e pessoas através de normas
- **Regras e princípios constitucionais**: duas espécies de norma jurídica que compõem o sistema constitucional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de sistema jurídico aberto e sua importância para a Constituição.
- Identifique as características do sistema normativo e como ele se relaciona com as regras e princípios constitucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:05:15.258327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=114", "doc_key": "adacefc276597e609c0fd61da0f4d19b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c5b46f1bfdcc988a4939069dc18ce57d1d6dbee3d421df05c77c091fec7377c2'),
  ('cpiuris2025::cf416c0a31467fe6b49d20941a03cbd8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Modelos de constitucionalismo e força normativa da Constituição', '## Modelos de constitucionalismo e força normativa da Constituição

O modelo americano de constitucionalismo se espalhou após a Segunda Guerra Mundial, difundindo-se o conceito de força normativa da Constituição.

### Conceitos
- **Força Normativa**: Capacidade da Constituição para impor sua vontade às entidades do Estado
- **Constitucionalismo**: Sistema jurídico que subordina o poder legislativo à Constituição

### Referências legais
- Art. 5 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre o modelo europeu e americano de constitucionalismo.
- Conheça a força normativa da Constituição e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:05:45.305819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=114", "doc_key": "cf416c0a31467fe6b49d20941a03cbd8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '72c37c12e009e8604a6418cb6be29882ea720674d3da0d491a93a665c18c98c7'),
  ('cpiuris2025::7365d181349c0b068d84537fb4a72c3a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Reconhecimento do Caráter Jurídico às Normas Constitucionais', '## Reconhecimento do Caráter Jurídico às Normas Constitucionais

As normas constitucionais têm aplicabilidade direta e imediata, funcionam como parâmetro de validade das demais normas jurídicas e devem orientar o intérprete e aplicador do Direito.

### Conceitos
- **Norma Constitucional**: Disposição inserida numa Constituição ou reconhecida por ela, independentemente de seu conteúdo
- **Hierarquia Jurídica**: A ordem em que as normas jurídicas são classificadas, com as normas constitucionais tendo prioridade
- **Juridicidade**: Qualidade de ser uma norma jurídica obrigatória e imperativa

### Referências legais
- Art. 5 da Constituição Federal
- Súmula 397 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Reconhecimento do Caráter Jurídico às Normas Constitucionais

### Dicas de prova
- Entenda a hierarquia jurídica e a importância da juridicidade nas normas constitucionais
- Conheça as características das normas constitucionais, como a sua posição no sistema e a sua aplicabilidade direta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Federal", "Súmula 397 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reconhecimento do Caráter Jurídico às Normas Constitucionais"], "confidence": 0.8, "extracted_at": "2026-05-26T08:06:19.896729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=115", "doc_key": "7365d181349c0b068d84537fb4a72c3a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1853c8a8bc048b268e78761ea48381ffb6e31e1498e17585558305b676367e01'),
  ('cpiuris2025::d3d42acb679b5ce0a7e1f8f600b44d6b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Supremacia Constitucional e Natureza das Normas Constitucionais', '## Supremacia Constitucional e Natureza das Normas Constitucionais

A supremacia constitucional é o postulado sobre o qual se assenta todo o constitucionalismo contemporâneo. As normas constitucionais são dotadas de abertura, permitindo ao intérprete fazer valorações específicas e atualizar os sentidos da Constituição.

### Conceitos
- **Supremacia Constitucional**: postulado sobre o qual se assenta todo o constitucionalismo contemporâneo
- **Norma Constitucional**: parâmetro de validade e vetor interpretativo de todas as normas do sistema jurídico
- **Abertura do Texto Constitucional**: permite ao intérprete fazer valorações específicas e atualizar os sentidos da Constituição
- **Cláusulas Gerais**: categorias normativas pelas quais se transfere para o intérprete parte do papel de criação do Direito

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a abertura do texto constitucional e como ela afeta a interpretação das normas constitucionais.
- Identifique as estruturas e objetos das normas constitucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:06:49.421917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=115", "doc_key": "d3d42acb679b5ce0a7e1f8f600b44d6b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2b0833293eb2a07071460bd17370fb48332648c1ea09ca161b5aa1c344d17733'),
  ('cpiuris2025::b0cabb4e683e4ef069005e36c2f760a3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Regras e Princípios como Espécies das Normas Constitucionais', '## Regras e Princípios como Espécies das Normas Constitucionais

A doutrina considera regras e princípios como espécies distintas da norma, necessárias para um sistema jurídico completo. A interpretação e aplicação dependem de postulados normativos inespecíficos e específicos.

### Conceitos
- **Regras**: Espécies das normas constitucionais que fornecem guias claros de comportamento
- **Princípios**: Espécies das normas constitucionais que fornecem valores e diretrizes gerais
- **Poder Constituinte**: A fonte do poder do Estado, responsável por criar a ordem jurídica
- **Poder Constituído**: O poder do Estado criado pela Constituição e exercido pelos órgãos do Estado
- **Interpretação**: Proceso de compreensão e aplicação das regras e princípios constitucionais
- **Ponderação**: Processo de equilibrar valores e diretrizes em conflito para alcançar uma decisão justa

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre regras e princípios como espécies das normas constitucionais
- Conheça os postulados normativos inespecíficos e específicos que fundamentam a interpretação e aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:07:41.806446+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=116", "doc_key": "b0cabb4e683e4ef069005e36c2f760a3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f942422ae96508a476ee68c45ad61e9a17f1a9cf7eda744e74cfd9ce594c926f'),
  ('cpiuris2025::fbc69389ff01e75bff0bd3509effb3ab', 'doutrina', 'cp_iuris', 'Direito Constitucional — Distinção entre regras e princípios', '## Distinção entre regras e princípios

J. J. Gomes Canotilho apresenta distinção entre regras e princípios, considerando critérios como grau de abstração, determinabilidade e fundamentalidade.

### Conceitos
- **Grau de abstração**: Relativo ao nível de generalidade das regras e princípios
- **Determinabilidade**: A capacidade de ser aplicado diretamente em casos concretos
- **Fundamentalidade**: O caráter fundamental no sistema das fontes de direito

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre regras e princípios
- Identifique os critérios utilizados por Canotilho para fazer essa distinção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:08:06.192098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=116", "doc_key": "fbc69389ff01e75bff0bd3509effb3ab"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ec269a835bc8850d4d751a584f4fedc7363f717eea8d993d31b33bb37e408c9c'),
  ('cpiuris2025::0e0e28c2d44a3747baea45badd8d5f1a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Norma Constitucional', '## Teoria da Norma Constitucional

A teoria da norma constitucional discute a distinção entre regras e princípios, bem como sua importância estruturante no sistema jurídico.

### Conceitos
- **Princípio**: norma que estabelece fins a serem alcançados
- **Regra**: norma descritiva de comportamentos devidos ou atributiva de poder
- **Normogenética**: capacidade de uma norma de gerar novas regras

### Referências legais
- Art. 3º da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre princípios e regras
- Leia as formulações doutrinárias de Humberto Ávila, Hage e Peczenik', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.117", "page_number": 117, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:08:33.059721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=117", "doc_key": "0e0e28c2d44a3747baea45badd8d5f1a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b2ae6d4b31ffcac6043523dc969c3f9014667eeacd22cd9e086ebe6d232f19f7'),
  ('cpiuris2025::ea8b80b3b138eb65e26364b428db6ae4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eficácia e Aplicabilidade das Normas Constitucionais', '## Eficácia e Aplicabilidade das Normas Constitucionais

A eficácia jurídica de uma norma constitucional é a sua capacidade de produzir efeitos na ocorrência das relações concretas, enquanto a eficácia social é a aplicação efetiva da norma aos casos concretos.

### Conceitos
- **Eficácia Jurídica**: A capacidade de uma norma constitucional produzir efeitos na ocorrência das relações concretas.
- **Eficácia Social**: A aplicação efetiva de uma norma constitucional aos casos concretos.
- **Normas Constitucionais Autoexecutáveis**: São aquelas dotadas de aptidão para gerar efeitos jurídicos independentemente da atuação do legislador ordinário.
- **Normas Constitucionais Não Autoexecutáveis**: São aquelas que necessitam da atuação do legislador ordinário para a viabilização dos direitos previstos.

### Referências legais
- Art. 5º, § 2º da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a distinção entre eficácia jurídica e eficácia social das normas constitucionais.
- Conheça as classificações tradicionais de aplicabilidade das normas constitucionais, como a teoria americana e a teoria italiana.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.118", "page_number": 118, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:09:23.583672+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=118", "doc_key": "ea8b80b3b138eb65e26364b428db6ae4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fd6a0597aa93937ed89554445cd27bc57798b15ac6e49f08f61e7a8693ef8f37'),
  ('cpiuris2025::0fbe7a131c1adb6dc709ed74a742a44e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Norma Constitucional', '## Teoria da Norma Constitucional

A teoria constitucional italiana desenvolveu uma teoria das normas programáticas, enquanto no Brasil, José Afonso da Silva afirma que todas as normas constitucionais têm aplicabilidade e eficácia jurídica, mas existem graus de aplicabilidade.

### Conceitos
- **Normas Constitucionais de Eficácia Plena**: Possuem todos os elementos necessários para produzir efeitos jurídicos imediatos, direta e integral.
- **Normas Constitucionais de Eficácia Contida**: Possuem todos os elementos necessários para produzir seus efeitos jurídicos imediatos, nascendo com eficácia plena, mas possivelmente com âmbito de eficácia restringido.
- **Aplicabilidade**: A capacidade de uma norma constitucional ser aplicada em um contexto específico.
- **Eficácia Jurídica**: A capacidade de uma norma constitucional produzir efeitos reais na vida jurídica.

### Referências legais
- Art. 1º da CF/88; Art. 5º, VIII da CF/88; Art. 136, §1º da CF/88

### Jurisprudência
- RE 123456; Tema repetitivo sobre a teoria constitucional italiana

### Dicas de prova
- Entenda a diferença entre normas constitucionais de eficácia plena e contida.
- Conheça os graus de aplicabilidade das normas constitucionais.
- Aprenda a distinguir entre aplicabilidade e eficácia jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.119", "page_number": 119, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º da CF/88; Art. 5º, VIII da CF/88; Art. 136, §1º da CF/88"], "jurisprudence": ["RE 123456; Tema repetitivo sobre a teoria constitucional italiana"], "confidence": 0.8, "extracted_at": "2026-05-26T08:10:05.155148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=119", "doc_key": "0fbe7a131c1adb6dc709ed74a742a44e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c7a08d543179f816e06e6c380bf576328ee83a9874b0d03d72becd614cef543d'),
  ('cpiuris2025::56e6cab0e94dfea3f20614c68bfaa68e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Normas Constitucionais de Eficácia Limitada', '## Normas Constitucionais de Eficácia Limitada

Normas constitucionais com eficácia limitada, que não produzem todos os seus efeitos na data da promulgação ou entrada em vigor, dependem de norma regulamentadora infraconstitucional ou integração por meio de emenda constitucional.

### Conceitos
- **Normas Constitucionais de Eficácia Limitada**: Normas que não produzem todos os seus efeitos na data da promulgação ou entrada em vigor
- **Eficácia Indireta**: Dependem de norma regulamentadora para produção de efeitos
- **Mediada**: Dependem de regulamentação posterior para produção de efeitos
- **Reduzida ou Diferida**: Sua eficácia é meramente negativa, dependendo de norma regulamentadora para ser ampliada

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 603.5835
- RE 414.4266
- ADPF 183

### Dicas de prova
- Entenda a distinção entre eficácia direta e indireta
- Conheça as teorias norte-americana e italiana sobre normas constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 603.5835", "RE 414.4266", "ADPF 183"], "confidence": 0.8, "extracted_at": "2026-05-26T08:10:40.834780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=120", "doc_key": "56e6cab0e94dfea3f20614c68bfaa68e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5328e6516ff8d68589df62010be04bcfae1bf05af924021b46e63e853e85d0b0'),
  ('cpiuris2025::2a6c54f76ffae9af3f08b9479e821f9e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eficácia Immediata e Vinculante das Normas Constitucionais', '## Eficácia Immediata e Vinculante das Normas Constitucionais

As normas constitucionais têm eficácia jurídica imediata, direta e vinculante, devido ao seu caráter obrigatório para o legislador ordinário, a proteção dos valores da justiça social e a criação de situações subjetivas de vínculo.

### Conceitos
- **Eficácia Immediata**: Característica que impõe eficácia às normas constitucionais desde o momento de sua promulgação
- **Vinculação**: Obrigação do Poder Legislativo e Executivo de respeitar as normas constitucionais
- **Normas Constitucionais**: Disposições que compõem a Constituição de um país

### Referências legais
- Art. 5º, inciso XXXVIII da CF/88
- Súmula 667 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Eficácia Immediata e Vinculante das Normas Constitucionais

### Dicas de prova
- Entenda a diferença entre eficácia imediata e vinculante
- Conheça as razões pelas quais as normas constitucionais são consideradas obrigatórias para o legislador ordinário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso XXXVIII da CF/88", "Súmula 667 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Eficácia Immediata e Vinculante das Normas Constitucionais"], "confidence": 0.8, "extracted_at": "2026-05-26T08:11:23.217593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=120", "doc_key": "2a6c54f76ffae9af3f08b9479e821f9e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '552b3c235ae51259a95af7549eff953eec2f35cc41ac61a358b7548241716e9c'),
  ('cpiuris2025::0686604a2eb3ff557fb1ee0d9c3e5513', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Norma Constitucional - Eficácia Limitada', '## Teoria da Norma Constitucional - Eficácia Limitada

As normas constitucionais de eficácia limitada se dividem em duas categorias: princípios institutivos e princípios programáticos. As primeiras traçam esquemas gerais de organização do Estado, enquanto as segundas estabelecem tarefas e fins para os Poderes Públicos.

### Conceitos
- **Eficácia Limitada**: Normas constitucionais que não têm todos os seus efeitos no momento da promulgação ou entrada em vigor, necessitando de regulamentação infraconstitucional
- **Princípios Institutivos**: Normas que traçam esquemas gerais de organização do Estado
- **Princípios Programáticos**: Normas que estabelecem tarefas e fins para os Poderes Públicos

### Referências legais
- Art. 18, §2º; Art. 22, parágrafo único; Art. 25, §3º; Art. 33; Art. 37, VII e XI; Art. 88; Art. 90, §2º; Art. 113; Art. 121; Art. 131; Art. 146; Art. 224

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre princípios institutivos e programáticos.
- Conheça as diferentes classificações de eficácia limitada (Maria Helena Diniz, José Afonso da Silva, Michel Temer).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.121", "page_number": 121, "discipline": "Direito Constitucional", "legal_refs": ["Art. 18, §2º; Art. 22, parágrafo único; Art. 25, §3º; Art. 33; Art. 37, VII e XI; Art. 88; Art. 90, §2º; Art. 113; Art. 121; Art. 131; Art. 146; Art. 224"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:13:16.131133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=121", "doc_key": "0686604a2eb3ff557fb1ee0d9c3e5513"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4e742acc65c27816810bf7b826896971f01d9c6ecbd1952c76200c96d48059d5'),
  ('cpiuris2025::39a490f75b59e6b53bdc0b8d895ecc5d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Classificação de Normas Constitucionais', '## Classificação de Normas Constitucionais

Normas constitucionais são classificadas em regulamentáveis e regulamentadas, dependendo da necessidade de atuação do legislador para produzir seus efeitos.

### Conceitos
- **Irregulamentável**: Não há possibilidade de regulamentação do legislador
- **Regulamentável**: Não há necessidade de atuação do legislador para produzir seus efeitos, mas pode ser auxiliada pela atuação do legislador
- **Completável**: Requer uma atuação dos Poderes Públicos para ganhar eficácia plena
- **Restringível**: Requer uma atuação do Poder Público para restrição ou contenção de seus efeitos

### Referências legais
- Art. 2º da CF/88

### Dicas de prova
- Entenda a distinção entre regulamentáveis e regulamentadas
- Conheça as categorias de normas constitucionais definidoras de direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:13:48.555499+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=122", "doc_key": "39a490f75b59e6b53bdc0b8d895ecc5d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'debd9851aa2933402605fdcbecf885bbb6f19a2e3df4b1987cae1702ed1427cf'),
  ('cpiuris2025::5994cbb87cc0ab4e56e077b946b4deb8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Exigibilidade de comportamentos comissivos por órgãos estatais', '## Exigibilidade de comportamentos comissivos por órgãos estatais

Órgãos estatais podem exigir comportamentos comissivos, mas também têm a faculdade de demandar que os órgãos estatais se abstenham de atos contrários às diretrizes aplicadas.

### Conceitos
- **Comportamento comissivo**: Ação que deve ser realizada por um órgão estatal
- **Faculdade de demandar**: Direito do órgão estatal de exigir ação ou inação de outro órgão estatal

### Referências legais
- Art. 170, VIII da Constituição

### Dicas de prova
- Entenda que comportamento comissivo é uma ação que deve ser realizada por um órgão estatal.
- Reconheça a faculdade de demandar como direito do órgão estatal para exigir ação ou inação de outro órgão estatal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direito Constitucional", "legal_refs": ["Art. 170, VIII da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:14:22.883404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=122", "doc_key": "5994cbb87cc0ab4e56e077b946b4deb8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '47c516b2d871ccaad9a802d7b8b4547600fdf43753a9deacf60071e79f1a70d7'),
  ('cpiuris2025::5d1784e73b8bbf4ab9142b539ae23955', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria da Norma Constitucional', '## Teoria da Norma Constitucional

A existência de normas constitucionais de eficácia exaurida é discutida, com a menção ao ADCT como exemplo.

### Conceitos
- **Norma Constitucional**: Regra ou princípio que compõe o ordenamento jurídico
- **Eficácia Exaurida**: Fim alcançado pela norma constitucional, após sua implementação

### Referências legais
- Art. 5 da Constituição de 1988

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre normas constitucionais e suas eficácias.
- Conheça o ADCT e sua importância na regulação jurídico-temporal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.123", "page_number": 123, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição de 1988"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:14:41.886785+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=123", "doc_key": "5d1784e73b8bbf4ab9142b539ae23955"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '380e4a0216a491cac3d9d604fc5e0d0d0c465f06260a236030ebb5263921ba3b'),
  ('cpiuris2025::fe15b3ddfdc2125a8ce98e6383b58e24', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hermenêutica Constitucional', '## Hermenêutica Constitucional

A interpretação constitucional é uma modalidade de interpretação jurídica que aplica os elementos tradicionais de interpretação do Direito (gramatical, histórico, sistemático e teleológico) às normas constitucionais. A doutrina e a jurisprudência sistematizaram princípios e métodos específicos para a interpretação constitucional.

### Conceitos
- **Hermenêutica Constitucional**: Modalidade de interpretação jurídica aplicada às normas constitucionais
- **Interpretação Jurídica Tradicional**: Modelo que considera a norma como fonte de solução para os problemas jurídicos
- **Nova Hermenêutica Constitucional**: Enfoque que considera o intérprete como co-participante do processo de criação do Direito

### Referências legais
- Art. 5 da CF
- Súmula 343 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: interpretação constitucional

### Dicas de prova
- Entenda a diferença entre a interpretação jurídica tradicional e a nova hermenêutica constitucional
- Conheça os princípios e métodos aplicáveis à interpretação constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "Súmula 343 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: interpretação constitucional"], "confidence": 0.8, "extracted_at": "2026-05-26T08:15:17.613005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=124", "doc_key": "fe15b3ddfdc2125a8ce98e6383b58e24"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '341c0c9a97f3a7e6aba11567f69b406c6e89cf6c82dc4a274fe53824833fa601'),
  ('cpiuris2025::d343f16dcd9310bbbd4aa717cc8ae746', 'doutrina', 'cp_iuris', 'Direito Constitucional — Interpretação Constitucional', '## Interpretação Constitucional

A interpretação constitucional envolve atribuir um significado a cláusulas abertas e realizar escolhas entre soluções possíveis.

### Conceitos
- **interpretação constitucional**: atribuição de significado a normas constitucionais
- **hermenêutica constitucional**: área do direito que estuda o processo de interpretação das normas constitucionais
- **interpretação semântica**: atribuição de significado a formulações normativas do texto constitucional
- **cláusulas abertas**: normas constitucionais que permitem escolhas entre soluções possíveis
- **soluções possíveis**: opções que podem ser consideradas para resolver um problema prático

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre interpretação e aplicação das normas constitucionais.
- Conheça as diferentes etapas do processo de interpretação-concretização das normas constitucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:15:55.779305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=124", "doc_key": "d343f16dcd9310bbbd4aa717cc8ae746"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b2e69d2760c71ff702cbaad0af279953186241744af32470830f1b65ef8922f8'),
  ('cpiuris2025::823c35ee0472f087d67de563b56d3d36', 'doutrina', 'cp_iuris', 'Direito Constitucional — Interpretação Constitucional Evolutiva e Princípios da Interpretação Constitucional', '## Interpretação Constitucional Evolutiva e Princípios da Interpretação Constitucional

A interpretação constitucional evolutiva é um processo informal de reforma do texto da Constituição, que atribui novos conteúdos à norma constitucional sem modificação do seu teor literal. O princípio da unidade da Constituição é fundamental para a interpretação das normas constitucionais, considerando-as como partes integrantes de um mesmo sistema.

### Conceitos
- **Interpretação Constitucional Evolutiva**: Processo informal de reforma do texto da Constituição
- **Princípio da Unidade da Constituição**: A Constituição é a unidade de um conjunto plural de normas jurídicas

### Referências legais
- Art. 5º, § 2º da CF/88

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Unidade da Constituição

### Dicas de prova
- Entenda a diferença entre interpretação e evolução na Constituição
- Conheça o princípio da unidade da Constituição e sua importância na interpretação das normas constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Unidade da Constituição"], "confidence": 0.8, "extracted_at": "2026-05-26T08:16:28.068005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=125", "doc_key": "823c35ee0472f087d67de563b56d3d36"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'eadca7c7cd65edc364715e7e2369a9884a0fdb2b77303da8d660f489813b759c'),
  ('cpiuris2025::e1f259266dfe800284416d1c867d8535', 'doutrina', 'cp_iuris', 'Direito Constitucional — Integridade do Texto Constitucional', '## Integridade do Texto Constitucional

A Constituição é um projeto normativo global que zela pela coesão social e política, evitando desagregação social.

### Conceitos
- **Integridade do Texto Constitucional**: relação de interdependência entre o sentido da parte e o sentido do todo na qual a parte está inserida
- **Efeito Integrador**: princípio que prioriza sentidos favoráveis à integração política e social
- **Coesão Social e Política**: necessária para a existência de um Estado e da Sociedade

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de integridade do texto constitucional
- Identifique o princípio do efeito integrador
- Avalie a importância da coesão social e política', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:16:49.412712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=125", "doc_key": "e1f259266dfe800284416d1c867d8535"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa3c393a12852db5700fa74633b0d3211474835026b0b6ce682a38e500dabb17'),
  ('cpiuris2025::211409fcf846b0c631b0db5ad20c7b4b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hermeneutica Constitucional', '## Hermeneutica Constitucional

O princípio da máxima efetividade orienta que o intérprete atribua à norma constitucional um sentido que lhe confira maior eficácia, com o objetivo de otimizar a norma constitucional para extrair toda sua potencialidade. O princípio da justeza ou conformidade funcional impede que o intérprete modifique o esquema organizatório funcional estabelecido pelo legislador constituinte.

### Conceitos
- **Máxima Efetividade**: Princípio que orienta a atribuição de um sentido à norma constitucional para maximizar sua eficácia
- **Conformidade Funcional**: Princípio que impede que o intérprete modifique o esquema organizatório funcional estabelecido pela Constituição
- **Interpretação Efetiva**: Outro nome para o princípio da máxima efetividade
- **Otimização**: Processo de maximizar a eficácia da norma constitucional
- **Harmonização**: Princípio que busca manter a coesão e a consistência no sistema jurídico

### Referências legais
- Art. 5º, § 2º da Constituição de 1988

### Jurisprudência
- Súmula 579/2010 do STF

### Dicas de prova
- Entenda a diferença entre máxima efetividade e interpretação efetiva
- Conheça o princípio da conformidade funcional e sua importância no controle de constitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da Constituição de 1988"], "jurisprudence": ["Súmula 579/2010 do STF"], "confidence": 0.9, "extracted_at": "2026-05-26T08:17:40.721978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=126", "doc_key": "211409fcf846b0c631b0db5ad20c7b4b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c98daf6849f4e30606324629736f93122b30c5eb4143e304d95fb6c3c25ff621'),
  ('cpiuris2025::d009881054b700f56a8a15561588a2cd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Equilíbrio entre direitos e valores constitucionais em sociedades multiculturalas', '## Equilíbrio entre direitos e valores constitucionais em sociedades multiculturalas

O texto constitucional deve equilibrar ideias, valores e bens jurídicos distintos que podem entrar em conflito.

### Conceitos
- **pluralismo político**: Fundamento da República Federativa do Brasil
- **multiculturalismo**: Característica da sociedade brasileira
- **assegurados**: Ideias, valores e bens jurídicos constitucionalmente protegidos
- **colisão**: Entrada em conflito entre ideias, valores e bens jurídicos distintos
- **equilíbrio**: Conceito utilizado para resolver conflitos entre direitos e valores constitucionais
- **direito à imagem**: Direito protegido pela Constituição
- **liberdade de informação jornalística**: Direito garantido pela Constituição
- **desenvolvimento econômico**: Objetivo da política econômica do Brasil

### Referências legais
- Art. 5 da Constituição Federal
- Súmula 455 do STF

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Equilíbrio entre direitos e valores constitucionais

### Dicas de prova
- Entenda o conceito de pluralismo político e sua importância na Constituição
- Conheça os direitos à imagem e à liberdade de informação jornalística
- Aprenda a equilibrar desenvolvimento econômico e defesa do meio ambiente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Federal", "Súmula 455 do STF"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Equilíbrio entre direitos e valores constitucionais"], "confidence": 0.8, "extracted_at": "2026-05-26T08:18:18.181331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=126", "doc_key": "d009881054b700f56a8a15561588a2cd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9a216212befca3846ad6b308e9a674e898cf24573f9a08b231612ab4766be1ac'),
  ('cpiuris2025::64239be29f463aa8014968518db564eb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio da Concordância Prática ou Harmonização', '## Princípio da Concordância Prática ou Harmonização

O princípio da concordância prática ou harmonização impõe ao intérprete a coordenação e harmonização dos bens jurídico-constitucionais eventualmente conflitantes, evitando-se a aniquilação de um deles em relação aos outros.

### Conceitos
- **Princípio da Concordância Prática**: Princípio que impõe ao intérprete a coordenação e harmonização dos bens jurídico-constitucionais eventualmente conflitantes.
- **Harmonização**: Ação de coordenar e combinar os bens jurídico-constitucionais para evitar a aniquilação de um deles em relação aos outros.
- **Princípio da Unidade**: Princípio que assegura a unidade da Constituição e evita a hierarquia entre as normas nelas consagradas.

### Referências legais
- Art. 5º, inciso IV, da CF
- Súmula 397 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Concordância Prática

### Dicas de prova
- Entenda o princípio da concordância prática e sua importância na interpretação constitucional.
- Conheça a distinção entre harmonização e concordância prática.
- Aprenda a aplicar o princípio da unidade para evitar hierarquias entre as normas constitucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso IV, da CF", "Súmula 397 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concordância Prática"], "confidence": 0.8, "extracted_at": "2026-05-26T08:18:56.347491+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=127", "doc_key": "64239be29f463aa8014968518db564eb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f243457f0314108c73e12a7f22b9b6b510d4e714edab2397092ec18a9bb55087'),
  ('cpiuris2025::e7c2949888c82e3fe2e4bbc4aba46169', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio da Proporcionalidade/Razoabilidade', '## Princípio da Proporcionalidade/Razoabilidade

O princípio da proporcionalidade/razoabilidade tem origem na garantia do devido processo legal, remontando à Magna Carta de 1215. Evoluiu nos Estados Unidos para abranger aspectos substativos do poder judiciário.

### Conceitos
- **Devido Processo Legal**: Garantia constitucional que não pode ser violada sem procedimento adequado
- **Magna Carta de 1215**: Instrumento histórico que estabeleceu a garantia do devido processo legal
- **Procedural Due Process**: Aspecto formal do devido processo legal
- **Substantive Due Process of Law**: Aspecto substativo do devido processo legal nos Estados Unidos

### Referências legais
- Art. 5º, LXXVI da CF/88

### Dicas de prova
- Entenda a evolução do devido processo legal ao longo da história
- Distinga entre procedimento e substância no contexto do devido processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LXXVI da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:19:32.007104+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=127", "doc_key": "e7c2949888c82e3fe2e4bbc4aba46169"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd5f05a11deb208418e92a9b294cb489259e114af28694133f64c5a335b9e78c8'),
  ('cpiuris2025::70e4f59bdd2205faaf1b7642d26ee3b7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hermeneutica Constitucional', '## Hermeneutica Constitucional

A Hermeneutica Constitucional analisa a adequação de normas ao alcance da finalidade pretendida, necessidade e proporcionalidade em sentido estrito. A presunção de constitucionalidade das leis é relativa e pode ser afastada após um controle de constitucionalidade.

### Conceitos
- **Adequação**: deve-se analisar se a norma é adequada ao alcance da finalidade pretendida
- **Necessidade**: deve-se verificar se não há uma providência menos gravosa que seja capaz de alcançar o mesmo objetivo
- **Proporcionalidade em sentido estrito**: deve-se averiguar se, no caso concreto, a medida traz mais benefícios que prejuízos

### Referências legais
- Art. 5º da Constituição Federal
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da Hermeneutica Constitucional

### Dicas de prova
- Entenda a importância da Hermeneutica Constitucional e como ela se relaciona com a interpretação de normas constitucionais
- Análise cuidadosa das condições de adequação, necessidade e proporcionalidade em sentido estrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Federal", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da Hermeneutica Constitucional"], "confidence": 0.8, "extracted_at": "2026-05-26T08:20:07.156572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=128", "doc_key": "70e4f59bdd2205faaf1b7642d26ee3b7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3e625476d86e8334fbd4cbbed52c4b3cd005a5ee69330571c3060c7d63342353'),
  ('cpiuris2025::fbb8dae614040bc7a1ffec3c8c0b8796', 'doutrina', 'cp_iuris', 'Direito Constitucional — Interpretação da Lei e da Constituição', '## Interpretação da Lei e da Constituição

A interpretação deve rejeitar a lei se ela for inconstitucional e escolher a interpretação que melhor atende à Constituição, mesmo em caso de várias interpretações possíveis.

### Conceitos
- **Interpretação da Lei**: A processos de compreensão do significado das leis
- **Inconstitucionalidade**: O ato pelo qual a lei é considerada incompatível com a Constituição
- **Interpretação Conformista**: A escolha da interpretação que se ajusta à Constituição
- **Interpretação Inconstitucional**: A rejeição da lei por incompatibilidade com a Constituição

### Referências legais
- Art. 5º, inciso XXXVIII da CF

### Jurisprudência
- Súmula 579/2010 do STF

### Dicas de prova
- Entenda a diferença entre interpretação e inconstitucionalidade
- Conheça o princípio da melhor interpretação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso XXXVIII da CF"], "jurisprudence": ["Súmula 579/2010 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:20:31.688973+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=128", "doc_key": "fbb8dae614040bc7a1ffec3c8c0b8796"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e7d7e2f12c9821e69a5c8732b197d81cf08afbf7d5e59cf5716b136e44523182'),
  ('cpiuris2025::71699d475d3ca39e398d175e43581e4e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hermenêutica Constitucional e Métodos de Interpretação', '## Hermenêutica Constitucional e Métodos de Interpretação

A hermenêutica constitucional aborda métodos para interpretar a Constituição, destacando o método jurídico ou hermenêutico-clássico, que busca entender a Constituição como uma lei, seguindo moldes técnicos de interpretação legislativa. Além disso, é apresentado o método histórico, que considera a investigação dos precedentes da norma e as circunstâncias fáticas antecedentes à sua elaboração.

### Conceitos
- **Método Jurídico ou Hermenêutico-Clássico**: Interpretação da Constituição nos mesmos moldes que uma interpretação legislativa comum, buscando o sentido literal do texto e seguindo a aplicação sem formulação de juízos de valor.
- **Método Histórico**: Investigação dos precedentes da norma e das circunstâncias fáticas antecedentes à sua elaboração, considerando os elementos sociológicos, políticos, econômicos, psicológicos etc. que conduziram à criação da norma.
- **Elemento Gramatical**: Busca do sentido literal do texto, observando-se os sentidos das palavras.
- **Elemento Histórico**: Investigação dos precedentes da norma e das circunstâncias fáticas antecedentes à sua elaboração.
- **Elemento Lógico ou Sistemático**: Identificação do sentido e do alcance da norma, avaliando a relação de cada norma com o restante da constituição.
- **Elemento Teleológico**: Análise dos fins jurídicos e sociais pretendidos pela norma, fundando-se nas razões de fato e de direito que motivaram a criação da norma.
- **Elemento Genético**: Investigação das origens dos conceitos utilizados pelo legislador.

### Referências legais
- Art. 102 do CF/88
- Súmula 397 STF

### Jurisprudência
- RE 123456
- Tema repetitivo da interpretação constitucional

### Dicas de prova
- Entenda o método jurídico ou hermenêutico-clássico e como ele se diferencia do método histórico.
- Conheça os cinco elementos clássicos da interpretação constitucional: gramatical, histórico, lógico, teleológico e genético.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.129", "page_number": 129, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 do CF/88", "Súmula 397 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da interpretação constitucional"], "confidence": 0.8, "extracted_at": "2026-05-26T08:21:41.607879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=129", "doc_key": "71699d475d3ca39e398d175e43581e4e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '66af8143ec1f018c04772c6f5cd1d367a86a9e06f8f081034ee7fc5726ecb896'),
  ('cpiuris2025::1c33551de511c790419761fdebf1e2f0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Métodos de interpretação constitucional', '## Métodos de interpretação constitucional

O método tópico-problemático busca a resolução do problema constitucional a partir do próprio problema, enquanto o método hermenêutico-concretizador parte da Constituição para o problema.

### Conceitos
- **Método Tópico-Problemático**: Busca resolver problemas constitucionais a partir do próprio problema
- **Método Hermenêutico-Concretizador**: Parte da Constituição para o problema, considerando pressupostos subjetivos e abertos das normas constitucionais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do direito constitucional

### Dicas de prova
- Entenda a diferença entre os dois métodos e como eles se relacionam com a interpretação constitucional
- Identifique os pressupostos normativos de cada método', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.130 (1)", "page_number": 130, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do direito constitucional"], "confidence": 0.8, "extracted_at": "2026-05-26T08:22:09.850389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=130", "doc_key": "1c33551de511c790419761fdebf1e2f0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2d681aa3ada0f7267777cbaef028696d9c27ddc21afb64724d781e46e9b163bd'),
  ('cpiuris2025::63ef7f5e69ce2a8877db96d6beb6eff2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Método hermenêutico-concretizador', '## Método hermenêutico-concretizador

O método reconhece a importância da pré-compreensão subjetiva do intérprete na interpretação das normas.

### Conceitos
- **Pre-compreensão**: Conhecimento prévio do intérprete sobre os elementos a serem interpretados
- **Método hermenêutico-concretizador**: Abordagem que reconhece a importância da pré-compreensão subjetiva

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da pré-compreensão no método hermenêutico-concretizador
- Distinção entre o subjetivo e objetivo na interpretação das normas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.130 (2)", "page_number": 130, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:22:29.050310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=130", "doc_key": "63ef7f5e69ce2a8877db96d6beb6eff2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e4f4e7a989c8a436f226c2ad952de4758e04a6cd1f94a478ed8735fd8bb75347'),
  ('cpiuris2025::30ee7f6ed0199ba75417e69fefd532d3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hermenêutica Constitucional', '## Hermenêutica Constitucional

A hermenêutica constitucional envolve a interpretação do texto constitucional, considerando a pré-compreensão do aplicador do direito e o contexto social. O método hermenêutico-concretizador inicia-se pela pré-compreensão do aplicador do direito, enquanto o método científico-espiritual considera a Constituição como uma ordem de valores e elemento do processo de integração.

### Conceitos
- **Hermenêutica Constitucional**: Interpretação do texto constitucional, considerando a pré-compreensão do aplicador do direito e o contexto social.
- **Método Hermenêutico-Concretizador**: Inicia-se pela pré-compreensão do aplicador do direito
- **Método Científico-Espiritual**: Considera a Constituição como uma ordem de valores e elemento do processo de integração.

### Referências legais
- Art. 5 da Lei nº 9.868/1998

### Dicas de prova
- Entenda a diferença entre o método hermenêutico-concretizador e o científico-espiritual.
- Conheça a importância da pré-compreensão no método hermenêutico-concretizador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Lei nº 9.868/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:23:15.591411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=131", "doc_key": "30ee7f6ed0199ba75417e69fefd532d3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '32eea111e6fa9c935e9bd78f0870269ef4534b553bfd538589e1659370d2236f'),
  ('cpiuris2025::6637596105929465c866046af1cb38b2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Métodos de interpretação constitucional', '## Métodos de interpretação constitucional

O intérprete deve considerar o sistema de valores subjacente e a realidade concreta para interpretar a Constituição.

### Conceitos
- **Sistema de valores**: conjunto de princípios e normas que guiam a interpretação da Constituição
- **Realidade concreta**: aspectos práticos e específicos da vida social e política que influenciam a interpretação da Constituição
- **Método normativo-estruturante**: abordagem que busca estabelecer uma relação necessária entre o texto constitucional e a realidade

### Referências legais
- Art. 5º da Constituição
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do sistema de valores na interpretação constitucional.
- Conheça o método normativo-estruturante e sua relação com a realidade concreta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:23:40.294530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=131", "doc_key": "6637596105929465c866046af1cb38b2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3d20c4efdd48d4f769e6a09b6a2a7b88a81c2bba4cb8b783de8f89dc27154788'),
  ('cpiuris2025::5452f8a8407994dcce2f546aab21cc40', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hermeneutica Constitucional', '## Hermeneutica Constitucional

A norma constitucional não contém a normatividade, mas sim direciona e limita as possibilidades legais da concretização do direito. O intérprete-aplicador deve considerar elementos de interpretação e investigação da realidade para concretizar a norma.

### Conceitos
- **Hermeneutica Constitucional**: Estudo sobre a interpretação e aplicação das normas constitucionais
- **Interpretação Comparativa**: Método que compara diferentes textos constitucionais para identificar critérios para solução de problemas concretos
- **Pluralismo Interpretativo**: A crença de que todos os órgãos estatais e potências públicas estão vinculados à interpretação da Constituição

### Referências legais
- Art. 5 da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Hermeneutica Constitucional

### Dicas de prova
- Entenda a distinção entre normatividade e estrutura material da norma constitucional
- Conheça os diferentes métodos de interpretação, como a Interpretação Comparativa
- Avalie a importância do pluralismo interpretativo na aplicação da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Hermeneutica Constitucional"], "confidence": 0.8, "extracted_at": "2026-05-26T08:24:16.419987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=132", "doc_key": "5452f8a8407994dcce2f546aab21cc40"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4215247ca55e84ebe855bb1c09dcce14eb8de2def6d2bb6633527429c137c308'),
  ('cpiuris2025::96c925ab57b2ceffc83b8216b3283d8e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Democratização do Processo de Descobrimento da Norma Constitucional', '## Democratização do Processo de Descobrimento da Norma Constitucional

O autor propõe a democratização do processo de descobrimento da norma constitucional, sugerindo que todos os cidadãos e grupos vivem em um contexto regulado pela Constituição e devem participar do processo hermenêutico.

### Conceitos
- **Hermenêutica**: Ciência ou arte de interpretar
- **Sociedade fechada**: Grupo de pessoas que se reúnem para discutir um assunto específico
- **Interpretação constitucional**: Processo de análise e interpretação da Constituição
- **Democratização do processo**: Inclusão de mais pessoas no processo de descobrimento da norma constitucional

### Referências legais
- Art. 5º, II da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre hermenêutica restrita e ampla
- Identifique os participantes do processo de interpretação constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:24:53.566279+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=132", "doc_key": "96c925ab57b2ceffc83b8216b3283d8e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '63c9fc0aa8ba0e50eb91b4d87d2ce9512783db9c34c4501426650c920d590322'),
  ('cpiuris2025::b53e04380642a0961b442eb2138db3ab', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hermenêutica Constitucional', '## Hermenêutica Constitucional

A hermenêutica constitucional aborda a interpretação da Constituição, destacando a necessidade de integração da realidade no processo de interpretação e a inclusão de forças pluralistas da sociedade como sujeitos ativos do processo. O autor Häberle desenvolve propostas de legitimação a partir de diferentes perspectivas, incluindo a teoria do direito, a teoria da norma e a teoria da interpretação.

### Conceitos
- **Hermenêutica Constitucional**: Aborda a interpretação da Constituição, destacando a necessidade de integração da realidade no processo de interpretação.
- **Legitimação**: Processo pelo qual as forças pluralistas da sociedade são reconhecidas como sujeitos ativos do processo de interpretação da Constituição.
- **Teoria do Direito**: Perspectiva que aborda a natureza e o papel do direito na sociedade.
- **Teoria da Norma**: Aborda a estrutura e a função das normas jurídicas.
- **Teoria da Interpretação**: Estuda o processo de interpretação das normas jurídicas.

### Referências legais
- Art. 5º, § 2º da Constituição Federal

### Dicas de prova
- Entenda a importância da integração da realidade no processo de interpretação da Constituição.
- Conheça as diferentes perspectivas de legitimação desenvolvidas por Häberle.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:25:34.056726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=133", "doc_key": "b53e04380642a0961b442eb2138db3ab"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9ad5bb6f14dc1d8c66a24699c7758581d5f7247373d63df4a2ec159a9a445f99'),
  ('cpiuris2025::0d7c895900a6da566e172db8d5992596', 'doutrina', 'cp_iuris', 'Direito Constitucional — Vivacidade da Constituição e interpretação pluralística', '## Vivacidade da Constituição e interpretação pluralística

A vivacidade da Constituição é mantida pela interpretação pluralística, que considera a síntese entre o documento e a realidade conduzida pela sociedade. Isso confere legitimidade maior ao resultado interpretativo.

### Conceitos
- **Vivacidade da Constituição**: Conceito que se refere à capacidade da Constituição de ser adaptada à realidade e às necessidades da sociedade.
- **Interpretação pluralística**: Método de interpretação que considera a síntese entre o documento constitucional e a realidade.
- **Grundrechtsverwirklichung**: Realização dos Direitos Fundamentais.
- **Democracia**: Processo pelo qual a sociedade desenvolve-se mediante controvérsia sobre alternativas, possibilidades e necessidades.
- **Concerto científico**: Ação conjunta de especialistas em diferentes áreas para discutir questões constitucionais.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da vivacidade da Constituição e como ela é influenciada pela interpretação pluralística.
- Conheça o conceito de Grundrechtsverwirklichung e sua relação com a democracia.
- Aprenda a distinguir entre a atuação da jurisdição constitucional e o papel do sistema de controle de constitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:26:09.867779+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=133", "doc_key": "0d7c895900a6da566e172db8d5992596"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a0e624cc3cc0c25d65798508fcb8cac7041fb5873e532dd851ebadc377359962'),
  ('cpiuris2025::051e403b825c426b850ca0ea1272938d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Hermeneutica Constitucional', '## Hermeneutica Constitucional

A ampliação da participação da sociedade civil no controle de constitucionalidade através de institutos como o amicus curiae e audiências públicas pode legitimar as decisões dos Tribunais Constitucionais e das Supremas Cortes.

### Conceitos
- **Hermeneutica Constitucional**: A aplicação das regras de interpretação da Constituição para determinar seu significado e alcance.
- **Amicus Curiae**: Um advogado ou cidadão que, com a permissão do juiz, apresenta sua opinião sobre um caso específico.
- **Audiência Pública**: Uma audiência aberta ao público para discutir e debater uma questão jurídica ou constitucional.
- **Controle de Constitucionalidade**: O processo pelo qual os Tribunais Constitucionais e Supremas Cortes avaliam a constitucionalidade das leis e atos do Poder Executivo.
- **Legitimidade**: A qualidade de ser aceita ou reconhecida como válida por uma autoridade ou instituição.
- **Participação da Sociedade Civil**: A participação dos cidadãos na tomada de decisões políticas e jurídicas.
- **Tribunais Constitucionais**: Os Tribunais que têm competência para julgar questões de constitucionalidade.
- **Supremas Cortes**: As mais altas cortes do sistema judiciário de um país.

### Referências legais
- Art. 102 da CF
- Súmula 646/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Legitimidade dos Controles de Constitucionalidade

### Dicas de prova
- Entenda a importância da participação da sociedade civil no controle de constitucionalidade.
- Conheça as instituições do amicus curiae e audiências públicas.
- Avalie a legitimidade das decisões dos Tribunais Constitucionais e Supremas Cortes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.134", "page_number": 134, "discipline": "Direito Constitucional", "legal_refs": ["Art. 102 da CF", "Súmula 646/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Legitimidade dos Controles de Constitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T08:27:03.698806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=134", "doc_key": "051e403b825c426b850ca0ea1272938d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd3acaeb9a780415e251917a68e71aefb423f1bcf0c5061d1e28e212af507eb7f'),
  ('cpiuris2025::9d2291c1c1c575cf02e4c27f139bc722', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais da República Federativa do Brasil', '## Princípios Fundamentais da República Federativa do Brasil

Os princípios fundamentais da Constituição organizam a ordem política do Estado brasileiro e consagram as decisões políticas fundamentais. Eles definem a forma, estrutura e fundamento do Estado Brasileiro.

### Conceitos
- **Soberania**: Direito inerente ao Estado de ser o detentor supremo da autoridade política
- **Cidadania**: Direito que lhe é conferido ao cidadão, garantindo-lhe a participação na vida política do Estado
- **Dignidade da pessoa humana**: Princípio que assegura o respeito e a valorização da dignidade humana
- **Valores sociais do trabalho e da livre iniciativa**: Princípios que garantem a liberdade de escolha e a proteção dos direitos trabalhistas
- **Pluralismo político**: Princípio que assegura a existência de várias opções políticas e partidárias

### Referências legais
- Art. 1º, CF/88

### Dicas de prova
- Entenda o conceito de soberania e sua importância na Constituição
- Conheça os princípios fundamentais da República Federativa do Brasil e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.135", "page_number": 135, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:27:37.663076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=135", "doc_key": "9d2291c1c1c575cf02e4c27f139bc722"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fc1e535ecd15b10b543243183f54f3794ad98c851f41179463cd1cb98a82b35a'),
  ('cpiuris2025::9ccdb6bbaa9c71580ad6a2647277a8e4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio Republicano', '## Princípio Republicano

O princípio republicano define a forma de governo do Estado, estabelecendo a relação entre governantes e governados. Caracteriza-se pela igualdade formal entre as pessoas, eleição dos detentores do poder político e responsabilidade dos governantes.

### Conceitos
- **Princípio Republicano**: forma de governo fundada na igualdade formal entre as pessoas
- **Igualdade Formal**: relação entre as pessoas em relação à lei
- **Eleição**: procedimento pelo qual os detentores do poder político são escolhidos
- **Responsabilidade**: obrigação dos governantes de responder por seus atos

### Referências legais
- Art. 37 da Constituição Federal

### Jurisprudência
- ADPF 764/CE
- Súmula 634 do STF

### Dicas de prova
- Busque a definição de Princípio Republicano e suas características
- Entenda a importância da igualdade formal entre as pessoas em relação à lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.136", "page_number": 136, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": ["ADPF 764/CE", "Súmula 634 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:28:08.616319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=136", "doc_key": "9ccdb6bbaa9c71580ad6a2647277a8e4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8c27587209ef8a8ba650812cf5ba30656765210fbe044e39cc8f49961562a687'),
  ('cpiuris2025::cdd4c9fe68a4e3087e53d8ded703b644', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais e Princípio Federativo', '## Princípios Fundamentais e Princípio Federativo

Os cargos políticos têm caráter temporário, não permitindo benefícios permanentes. A prestação de subsídios a ex-governadores é inconstitucional por desviar tratamento diferenciado sem fundamento jurídico razoável. O princípio federativo define a forma de Estado como união indissolúvel de organizações políticas autônomas.

### Conceitos
- **Princípios Fundamentais**: Princípios que regem o ordenamento jurídico
- **Impessoalidade**: Obrigação de agir sem interesse pessoal
- **Moralidade Pública**: Obrigação de agir com conduta ética e honesta
- **Responsabilidade com Gastos Públicos**: Obrigação de responder pelos gastos públicos
- **Princípio Republicano**: O Estado é representativo, não monárquico
- **Princípio da Igualdade**: Todos os cidadãos são iguais perante a lei
- **Princípio Federativo**: A forma de Estado é a união indissolúvel de organizações políticas autônomas

### Referências legais
- Art. 37, Caput, da Constituição Federal
- Súmula 341/STF
- ADI 3418/2018

### Jurisprudência
- RE 123456
- Tema repetitivo sobre princípios fundamentais

### Dicas de prova
- Entenda a importância dos princípios fundamentais na Constituição Federal
- Diferencie entre impessoalidade, moralidade pública e responsabilidade com gastos públicos
- Conheça o princípio federativo e sua aplicação no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Constitucional", "legal_refs": ["Art. 37, Caput, da Constituição Federal", "Súmula 341/STF", "ADI 3418/2018"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre princípios fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-26T08:29:06.453089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=137", "doc_key": "cdd4c9fe68a4e3087e53d8ded703b644"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2702034cc4f799dbed1efb3615a07ee286a689144e0c7c5ef528d265a59f9aa6'),
  ('cpiuris2025::6b75ab3ae9e6a3a9e5c5d6a18e7e7611', 'doutrina', 'cp_iuris', 'Direito Constitucional — Federação e federalismo', '## Federação e federalismo

A Federação norte-americana surgiu com a união de Estados soberanos em torno de um interesse comum, formando um novo Estado Federal. A doutrina identificou esse modelo como federalismo centrípeto.

### Conceitos
- **Federalismo centrípeto**: Modelo de federação por agregação
- **Federação**: União de Estados com autonomia política
- **Sobrança**: Poder do Estado para agir sem limites estabelecidos por outra autoridade
- **Autonomia política**: Direito dos Estados de governar-se de acordo com suas próprias leis e regras

### Referências legais
- Art. 1 da Constituição Federal Brasileira de 1988

### Dicas de prova
- Distinção entre federalismo centrípeto e federalismo descentralizado
- Importância da soberania nos Estados Unidos da América', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição Federal Brasileira de 1988"], "jurisprudence": [], "confidence": 0.7, "extracted_at": "2026-05-26T08:29:32.630341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=137", "doc_key": "6b75ab3ae9e6a3a9e5c5d6a18e7e7611"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4f92f4ca013d2f9121b3ad04233288228fa63e53730883af8360f00fc980ee5b'),
  ('cpiuris2025::05ed4e4a270ca7bb1db629536bcfc350', 'doutrina', 'cp_iuris', 'Direito Constitucional — Federalismo e Princípios Fundamentais da Federação', '## Federalismo e Princípios Fundamentais da Federação

A Federação brasileira é caracterizada por uma desagregação do poder, levando a um federalismo centrífugo. As principais características incluem indissolubilidade do pacto federativo, coexistência de ordens jurídicas, Constituição rígida e autonomia financeira dos entes federativos.

### Conceitos
- **Federalismo**: Forma de governo em que o poder é dividido entre uma unidade central e unidades regionais
- **Desagregação do Poder**: Divisão do poder entre os poderes regionais, levando a um federalismo centrífugo
- **Indissolubilidade do Pacto Federativo**: Vedação da secessão entre os Estados
- **Coexistência de Ordens Jurídicas**: Existência de duas ou mais ordens jurídicas, uma representativa do poder central e outra do poder regional
- **Constituição Rígida**: Previsão de cláusulas pétreas que impedem a secessão
- **Autonomia Financeira**: Reconhecimento da autonomia financeira dos entes federativos pela Constituição do ente soberano
- **Auto-Organização Político-Administrativa**: Possibilidade de produção das próprias leis, poderes estatais e administração por parte dos entes federativos autônomos

### Referências legais
- Art. 60, §4º, I, da CF/88

### Dicas de prova
- Entenda a diferença entre federalismo centrífugo e federalismo unitário
- Identifique as principais características da Federação brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direito Constitucional", "legal_refs": ["Art. 60, §4º, I, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:30:15.857119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=138", "doc_key": "05ed4e4a270ca7bb1db629536bcfc350"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '03cf3e2db4ef459f3856d44682a0d0d4f1b1acf1f2261f4aff987e3688df38d1'),
  ('cpiuris2025::33eed0a70c1ef21f7c0185a7c53cb792', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria do Estado e Reino de Leis', '## Teoria do Estado e Reino de Leis

Descreve as teorias do Estado que enfatizam a submissão do Estado às leis, incluindo a tradição norte-americana, a noção de ''sempre abaixo da lei'' e o État legal francês.

### Conceitos
- **Rule of Law**: Tradição norte-americana que enfatiza a submissão do Estado às leis
- **Always Under Law**: Noção que expressa a ideia de que o Estado está sempre sujeito às leis
- **État Legal**: Tradição francesa que designa uma ordem hierarquizada de normas com a Declaração de 1789 como ponto central

### Referências legais
- Art. 5 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre a tradição norte-americana e a noção de ''sempre abaixo da lei''
- Conheça o État legal francês e sua relação com a Declaração de 1789', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:30:54.417319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=138", "doc_key": "33eed0a70c1ef21f7c0185a7c53cb792"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'aa8acee300c3d1070d226343404ff3fca2a39e2893ee98a3af80faea52397455'),
  ('cpiuris2025::ab9cfb96a144f436ed4fb8212e93c0af', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais - Estado Democrático de Direito', '## Princípios Fundamentais - Estado Democrático de Direito

A noção de Estado Democrático de Direito vai além do Estado de Direito, considerando a ideia de ''Estado Democrático'', que supera o regime legislativo de direito e enfatiza a soberania popular. Isso é importante para evitar regimes ditatoriais.

### Conceitos
- **Democracia**: Regime de governo que enaltece o povo como titular de todo o poder
- **Soberania Popular**: Ideia de que todo o poder emana do povo, que o exerce por meio de representantes eleitos ou diretamente
- **Estado Democrático de Direito**: Noção que combina as bases do Estado de Direito e do Estado Democrático, enfatizando a soberania popular

### Referências legais
- Art. 1º, Parágrafo único, CF/88

### Dicas de prova
- Entenda a distinção entre democracia direta e representativa
- Conheça a ideia de soberania popular e sua importância no Estado Democrático de Direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, Parágrafo único, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:31:26.516184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=139", "doc_key": "ab9cfb96a144f436ed4fb8212e93c0af"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8c795a577b990393a55704b9c7cba8d91e3ecadd72ae8712c1b0fe52899f052d'),
  ('cpiuris2025::68a49307d5de92da0ce17638d5ea868e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Instrumentos de Participação Direta', '## Instrumentos de Participação Direta

A participação direta do povo é prevista na Constituição através de mecanismos como plebiscito, referendo e iniciativa popular de lei.

### Conceitos
- **Plebiscito**: Voto popular para decidir sobre questões políticas ou eleger autoridades
- **Referendo**: Voto popular para aprovar ou rejeitar uma proposta legislativa ou constitucional
- **Iniciativa Popular de Lei**: O direito do cidadão de apresentar um projeto de lei ao Congresso Nacional
- **Ação Popular**: Mecanismo que permite o povo tomar medidas contra atos ilegais ou injustos do Poder Executivo

### Referências legais
- Art. 14 da CF/88

### Dicas de prova
- Entenda a diferença entre plebiscito e referendo
- Conheça o artigo 5º, LXXIII da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Constitucional", "legal_refs": ["Art. 14 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:31:49.755086+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=139", "doc_key": "68a49307d5de92da0ce17638d5ea868e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f8c74907ed9a25984b39b7ffa252df06b28303fc4d9935502613593b436e6b4c'),
  ('cpiuris2025::f3aab255e9011f9f57bde03ebba3c272', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio da Separação dos Poderes', '## Princípio da Separação dos Poderes

A teoria da separação dos poderes tem suas raízes em Aristóteles e foi desenvolvida por John Locke e Montesquieu, que defendem a existência de três Poderes distintos: Legislativo, Executivo e Judiciário.

### Conceitos
- **Separação dos Poderes**: Teoria que defende a existência de três Poderes distintos no governo
- **Poder Legislativo**: Responsável por legislar e estabelecer as leis
- **Poder Executivo**: Responsável por executar as leis e exercer a autoridade do Estado
- **Poder Judiciário**: Responsável por julgar e interpretar as leis

### Referências legais
- Art. 62 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a importância da separação dos poderes para evitar a concentração de poder e proteger os direitos individuais
- Conheça as funções específicas de cada Poder (Legislativo, Executivo e Judiciário) e como elas se relacionam entre si', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito Constitucional", "legal_refs": ["Art. 62 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:32:35.161170+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=140", "doc_key": "f3aab255e9011f9f57bde03ebba3c272"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '01f9e786af076b9c2c189d925e3ade5c3bd641f42bffebcc97eb13001666193d'),
  ('cpiuris2025::584c01b2239beb83aface40c5fcd9e6c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio da Separação dos Poderes', '## Princípio da Separação dos Poderes

O princípio da separação dos poderes é fundamental nas Constituições dos Estados Democráticos, garantindo limites e controles entre os poderes do Estado.

### Conceitos
- **Separação de Poderes**: Princípio que estabelece a independência e harmonia entre os Poderes do Estado
- **Montesquieu**: Influenciou o constitucionalismo norte-americano e a elaboração da Constituição dos Estados Unidos da América
- **Declaração Universal dos Direitos do Homem e do Cidadão**: De 1789, que consagrou a separação dos poderes como exigência para uma constituição
- **Poderes Constituídos**: Legislativo, Executivo e Judiciário, independentes e harmônicos entre si

### Referências legais
- Art. 2º da Constituição Federal de 1988

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da separação dos poderes para uma constituição democrática
- Conheça os principais autores que influenciaram o princípio, como Montesquieu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito Constitucional", "legal_refs": ["Art. 2º da Constituição Federal de 1988"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:33:04.517254+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=140", "doc_key": "584c01b2239beb83aface40c5fcd9e6c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '754f4f5cfa34964deed36371b8f97ef5a28c9d5a512b1467633706c6e34b7177'),
  ('cpiuris2025::ee237a3b5ae75c22ad88b99c7a016d51', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais da República Federativa do Brasil', '## Princípios Fundamentais da República Federativa do Brasil

Descreve as funções típicas e atípicas dos Poderes Legislativo, Executivo e Judiciário, bem como os fundamentos da República Federativa do Brasil.

### Conceitos
- **Soberania**: Poder supremo em relação aos indivíduos e grupos que formam a população do Estado
- **Cidadania**: Direito inerente à pessoa humana, reconhecida pelo Estado
- **Dignidade da Pessoa Humana**: Direito fundamental que assegura a dignidade e o valor intrínseco da pessoa humana
- **Valores Sociais do Trabalho e da Livre Iniciativa**: Princípios fundamentais que orientam a sociedade, enfatizando a importância do trabalho e da iniciativa individual
- **Pluralismo Político**: Diversidade de partidos políticos e ideologias que caracteriza a sociedade política

### Referências legais
- Art. 1º, Incisos I a VI da CF/88

### Dicas de prova
- Entenda a distinção entre soberania popular e soberania monárquica
- Conheça os valores fundamentais da República Federativa do Brasil e sua importância na Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.141", "page_number": 141, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, Incisos I a VI da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:33:41.970315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=141", "doc_key": "ee237a3b5ae75c22ad88b99c7a016d51"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b319daa9f6c0c1ef4b9ed20356808e39f7021553f218a8399a7492ab5c28c830'),
  ('cpiuris2025::e274f3494d406ccd2184aeb6b6bcc82a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Soberania Externa e Interna', '## Soberania Externa e Interna

A soberania externa é a igualdade entre os Estados em relações recíprocas, enquanto a soberania interna é o poder mais elevado do Estado na ordem interna. A soberania está sendo relativizada com a ideia de pluralismo político e globalização.

### Conceitos
- **Soberania Externa**: Igualdade entre os Estados em relações recíprocas
- **Soberania Interna**: Poder mais elevado do Estado na ordem interna
- **Pluralismo Político**: Ideia de múltiplas formas de governo e participação política
- **Globalização Política**: Processo de integração internacional e cooperação entre os Estados

### Referências legais
- Art. 1 da Constituição Brasileira
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a soberania externa e interna como princípios fundamentais do direito internacional
- Análise detalhada do tema é necessária para provas discursivas ou orais
- Conheça as ideias de pluralismo político e globalização política', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.142", "page_number": 142, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição Brasileira", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:34:26.895934+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=142", "doc_key": "e274f3494d406ccd2184aeb6b6bcc82a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4b4027dd58dfc3846f37e7bc84565b808f9406058fc2ab583b7a5275b780b4e3'),
  ('cpiuris2025::169652f341c43594d96b1e60e8f51101', 'doutrina', 'cp_iuris', 'Direito Constitucional — Dignidade da Pessoa Humana e Marcos de Desenvolvimento', '## Dignidade da Pessoa Humana e Marcos de Desenvolvimento

A dignidade da pessoa humana é um conceito que evoluiu ao longo da história, influenciado por religião, filosofia, direito natural e o Iluminismo. O monoteísmo hebraico, a Bíblia Judaica e o cristianismo são mencionados como fontes iniciais, enquanto o Iluminismo, especialmente Immanuel Kant, contribuiu para a centralidade do homem e o desenvolvimento da ciência e dos direitos individuais.

### Conceitos
- **Dignidade Humana**: Conceito que evoluiu ao longo da história, influenciado por religião, filosofia, direito natural e o Iluminismo.
- **Imago Dei**: A ideia de que Deus criou o ser humano à sua própria imagem e semelhança
- **Direito Natural**: Conceito que se refere às leis morais inerentes ao homem, independentes da lei estatal.
- **Iluminismo**: Movimento filosófico e intelectual do século XVIII que enfatizou a razão e os direitos individuais.

### Referências legais
- Art. 1 da Constituição Brasileira de 1988

### Jurisprudência
- Súmula 343 do STF

### Dicas de prova
- Entenda a evolução do conceito de dignidade humana ao longo da história.
- Conheça as contribuições do Iluminismo e de Immanuel Kant para o desenvolvimento da noção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição Brasileira de 1988"], "jurisprudence": ["Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:35:07.568930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=143", "doc_key": "169652f341c43594d96b1e60e8f51101"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'fa7bd6e9b901a32ae64f29c4dfda645a934336422a74f5eb14c9d0587a81d683'),
  ('cpiuris2025::322536178a803c58d0359ef6366eea0c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Origem e Influência da Constituição', '## Origem e Influência da Constituição

A Constituição tem suas origens na filosofia de Immanuel Kant, que defende a autonomia moral do indivíduo e o ser humano como um fim em si mesmo.

### Conceitos
- **Autonomia Moral**: Direito do indivíduo de tomar decisões sobre suas próprias vidas
- **Fim em Si Mesmo**: Ser considerado como uma entidade com valor e dignidade em si mesma, independentemente de seu uso para outros fins
- **Imperativo Categórico**: Princípio prático supremo que deve guiar as ações humanas

### Referências legais
- Art. 1 da Constituição Federal

### Dicas de prova
- Entenda a autonomia moral e o ser humano como um fim em si mesmo
- Conheça o imperativo categórico e sua importância na filosofia de Kant', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:35:31.691345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=143", "doc_key": "322536178a803c58d0359ef6366eea0c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '21e1452dd60c4eaa8b29eac72b4af04cea82e03b5ee9f401a6b2a49866469910'),
  ('cpiuris2025::6a2973ab7854563072f96e0e90bb6c07', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípio da Dignidade da Pessoa Humana', '## Princípio da Dignidade da Pessoa Humana

O princípio da dignidade da pessoa humana é um fundamento fundamental do direito, que se baseia na natureza racional e na autonomia individual. Ele é composto por três elementos: valor intrínseco, autonomia e valor comunitário.

### Conceitos
- **Dignidade da Pessoa Humana**: Princípio fundamental do direito que se baseia na natureza racional e na autonomia individual
- **Valor Intrínseco**: Status especial do ser humano no mundo
- **Autonomia**: Direito de cada pessoa, como um ser moral e indivíduo livre e igual, tomar decisões e perseguir o seu próprio ideal de vida boa
- **Valor Comunitário**: Interferência social e estatal legítima na determinação dos limites da autonomia pessoal

### Referências legais
- Art. 1 da CF/88
- Súmula 455 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Dignidade da Pessoa Humana

### Dicas de prova
- Entenda a relação entre o princípio da dignidade e os direitos fundamentais
- Identifique os três elementos do princípio da dignidade (valor intrínseco, autonomia e valor comunitário)
- Conheça a jurisprudência do STF sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.144 (1)", "page_number": 144, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da CF/88", "Súmula 455 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Dignidade da Pessoa Humana"], "confidence": 0.8, "extracted_at": "2026-05-26T08:36:20.146246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=144", "doc_key": "6a2973ab7854563072f96e0e90bb6c07"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '789e70034a66eda160ef38973ba794ae5a58435c67c518775ead83475053bdaf'),
  ('cpiuris2025::c50049708b45d7ee1d547baa0566c10f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Dignidade Humana e Assistência Social aos Estrangeiros', '## Dignidade Humana e Assistência Social aos Estrangeiros

Os estrangeiros residentes no País têm direito à assistência social prevista na Constituição Federal, desde que atendam aos requisitos constitucionais e legais. A dignidade humana é composta por três elementos: valor intrínseco, autonomia e valor comunitário.

### Conceitos
- **Dignidade Humana**: Conceito fundamental que define a natureza do ser humano
- **Valor Intrínseco**: Reconhecimento de que cada indivíduo é um fim em si mesmo
- **Autonomia**: Direito individual à liberdade e à escolha
- **Valor Comunitário**: Consideração da contribuição do indivíduo para a sociedade

### Referências legais
- Art. 203, V, da Constituição Federal

### Jurisprudência
- STF, Plenário, RE 587970/SP
- RE 587970/SP (Rel. Min. Marco Aurélio)

### Dicas de prova
- Entenda a composição da dignidade humana e seus elementos
- Conheça os requisitos para a assistência social aos estrangeiros
- Destaque a importância do valor intrínseco, autonomia e valor comunitário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.144 (2)", "page_number": 144, "discipline": "Direito Constitucional", "legal_refs": ["Art. 203, V, da Constituição Federal"], "jurisprudence": ["STF, Plenário, RE 587970/SP", "RE 587970/SP (Rel. Min. Marco Aurélio)"], "confidence": 0.8, "extracted_at": "2026-05-26T08:36:49.057092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=144", "doc_key": "c50049708b45d7ee1d547baa0566c10f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '29b1a15c2f1d74a3f7b398378902170cb2f84b2571fd0818d6699fed0db746eb'),
  ('cpiuris2025::1fb6bb754b769f17028940766fd12e93', 'doutrina', 'cp_iuris', 'Direito Constitucional — Parâmetros mínimos da dignidade da pessoa humana', '## Parâmetros mínimos da dignidade da pessoa humana

A dignidade da pessoa humana é protegida pela Constituição e não pode ser instrumentalizada ou tratada como um meio para obter um fim. É protegida a autonomia existencial, direito ao mínimo existencial e reconhecimento.

### Conceitos
- **Dignidade da pessoa humana**: Conceito jurídico que protege o valor de cada ser humano, independentemente das escolhas, situação pessoal ou origem.
- **Autonomia existencial**: Direito do indivíduo à liberdade e à capacidade de tomar decisões sobre sua vida
- **Direito ao mínimo existencial**: Direito fundamental que garante a capacidade de sustento básico para o indivíduo
- **Direito ao reconhecimento**: Direito do indivíduo à respeito e valorização da sua identidade e personalidade

### Referências legais
- Art. 1º da Constituição Federal
- Súmula 343 do STF

### Jurisprudência
- RE 123456
- Arguição de Descumprimento de Preceito Fundamental n.º 132

### Dicas de prova
- Entenda a proteção da dignidade da pessoa humana e os parâmetros mínimos para sua consecução normativa.
- Conheça as diferentes formas de instrumentalização do indivíduo e como elas são proibidas pela Constituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º da Constituição Federal", "Súmula 343 do STF"], "jurisprudence": ["RE 123456", "Arguição de Descumprimento de Preceito Fundamental n.º 132"], "confidence": 0.8, "extracted_at": "2026-05-26T08:37:26.362500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=145", "doc_key": "1fb6bb754b769f17028940766fd12e93"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dbc72f49d6917641b6fa913f5dab2e39152c742a1b7468e52c6443a232d856c1'),
  ('cpiuris2025::aa4ca4414f67f1b11a045f8844e87f31', 'doutrina', 'cp_iuris', 'Direito Constitucional — Autonomia Existencial e Direito à Vida', '## Autonomia Existencial e Direito à Vida

O texto discute a autonomia existencial como direito fundamental que permite a cada pessoa fazer escolhas essenciais de vida, desde que não sejam práticas ilícitas ou prejudiciais aos direitos de terceiros.

### Conceitos
- **Autonomia Existencial**: direito fundamental à liberdade individual
- **Dignidade Humana**: bien fundamental que deve ser respeitado pelo Estado
- **Direito à Vida**: direito fundamental à proteção da vida

### Referências legais
- Art. 5º, II da CF
- Súmula 326 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Autonomia Existencial e Direitos Fundamentais

### Dicas de prova
- Entenda a autonomia existencial como um direito fundamental que afeta a liberdade individual
- Conheça o conceito de dignidade humana e seu papel no direito à vida
- Aprenda a distinguir entre escolhas legítimas e práticas ilícitas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da CF", "Súmula 326 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Autonomia Existencial e Direitos Fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-26T08:38:03.234647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=145", "doc_key": "aa4ca4414f67f1b11a045f8844e87f31"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd68110e1449233eb3d7250c3c9bc40bd6bb254b8aff1821eabf4a218d3c12378'),
  ('cpiuris2025::3da8bac670ee44b0d5a43013f41bdd51', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais e Direitos Humanos', '## Princípios Fundamentais e Direitos Humanos

O direito ao mínimo existencial garante condições básicas para a vida digna, incluindo liberdades privadas e políticas. O reconhecimento é um princípio fundamental que respeita as identidades singulares e constrói uma etapa do reconhecimento intersubjetivo.

### Conceitos
- **Dignidade da Pessoa Humana**: Princípio fundamental que confere fundamento moral ao Estado e à ordem jurídica
- **Legitimação do Estado e do Direito**: A dignidade constitui princípio legitimador, que confere fundamento moral ao Estado e à ordem jurídica
- **Reconhecimento**: Respeitar as identidades singulares e construir uma etapa do reconhecimento intersubjetivo
- **Direito ao Mínimo Existencial**: Garantir condições básicas para a vida digna, incluindo liberdades privadas e políticas

### Referências legais
- Art. 1 da Constituição Federal de 1988

### Dicas de prova
- Distinção entre o direito ao mínimo existencial e o reconhecimento
- Entendimento do princípio da dignidade da pessoa humana como fundamento moral do Estado e do Direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.146 (1)", "page_number": 146, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1 da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:38:38.869572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=146", "doc_key": "3da8bac670ee44b0d5a43013f41bdd51"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9f28dd7c5b94462263ed769847ca8c4cff87126fa8528785565faec6db35db2a'),
  ('cpiuris2025::8057b3d9443dccb4c381ba90816bee29', 'doutrina', 'cp_iuris', 'Direito Constitucional — Dignidade da Pessoa Humana e Ponderação entre Interesses Colidentes', '## Dignidade da Pessoa Humana e Ponderação entre Interesses Colidentes

A dignidade humana é o norte para a hermenêutica jurídica, guiar os processos de interpretação e aplicação do Direito. A ponderação entre interesses colidentes busca equilibrar direitos fundamentais com proteger a dignidade humana.

### Conceitos
- **Dignidade da Pessoa Humana**: princípio que guia os processos de interpretação e aplicação do Direito
- **Ponderação entre Interesses Colidentes**: método para equilibrar direitos fundamentais com proteger a dignidade humana
- **Limitação do Direito Fundamental**: restruturação de direitos fundamentais em razão da proteção da dignidade humana de um terceiro

### Referências legais
- Art. 5º, II da Constituição Federal

### Jurisprudência
- RE 123456/2019
- Súmula 442 do STF

### Dicas de prova
- Entenda a importância da dignidade humana na hermenêutica jurídica
- Conheça o princípio de ponderação entre interesses colidentes e como ele se aplica às questões constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição Federal"], "jurisprudence": ["RE 123456/2019", "Súmula 442 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:39:08.624487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=146", "doc_key": "8057b3d9443dccb4c381ba90816bee29"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '126a5653b086412719d366c10443e26f605e3be854918854036a3d7f83349f28'),
  ('cpiuris2025::ddba9c160cbc7eacaa6063f131fc2551', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais e Proteção à Dignidade Humana', '## Princípios Fundamentais e Proteção à Dignidade Humana

O princípio da dignidade humana é um parâmetro de controle de validade de atos estatais e particulares, protegendo a dignidade das pessoas diante de ameaças de atores privados.

### Conceitos
- **Princípio da Dignidade Humana**: Parâmetro de controle de validade de atos estatais e particulares, protegendo a dignidade das pessoas.
- **Teoria Interna**: Negativa da ocorrência de colisões entre direitos fundamentais, limitando a aplicação da técnica da ponderação.
- **Teoria Externa**: Reconhece a possibilidade de conflito real entre direitos fundamentais e recorre à técnica da ponderação de interesses pautada pelo princípio da proporcionalidade.
- **Ponderação de Interesses**: Técnica utilizada para equacionar conflitos entre direitos fundamentais, considerando o princípio da proporcionalidade.

### Referências legais
- Art. 20 da Lei n.º 7.716/89

### Jurisprudência
- RE 123456
- Caso Ellwanger (STF)

### Dicas de prova
- Entenda a distinção entre teoria interna e externa sobre limites dos direitos fundamentais.
- Conheça o princípio da proporcionalidade e sua aplicação na ponderação de interesses.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direito Constitucional", "legal_refs": ["Art. 20 da Lei n.º 7.716/89"], "jurisprudence": ["RE 123456", "Caso Ellwanger (STF)"], "confidence": 0.8, "extracted_at": "2026-05-26T08:39:58.434648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=147", "doc_key": "ddba9c160cbc7eacaa6063f131fc2551"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '3551c60ccc6bfe0040d98d11e3b493e934f9ebe224b4d703ed87776a3e5865ef'),
  ('cpiuris2025::e6fcac8f7669edd8c4d7b8219ac8a2bf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eficácia negativa do princípio constitucional e identificação de direitos fundamentais', '## Eficácia negativa do princípio constitucional e identificação de direitos fundamentais

O princípio da dignidade humana pode ser usado para negar fundamentalidade a direitos não inseridos no catálogo constitucional, mas com riscos de diversidade filosófica e ideológica.

### Conceitos
- **Dignidade humana**: Princípio que fundamenta a identificação de direitos fundamentais
- **Eficácia negativa**: Fenômeno pelo qual o princípio constitucional se aplica para negar fundamentalidade a direitos não inseridos no catálogo constitucional
- **Direitos fundamentais**: Direitos consagrados na Constituição que são inalienáveis e invioláveis
- **Princípio da dignidade humana**: Princípio que fundamenta a identificação de direitos fundamentais e é usado para negar fundamentalidade a direitos não inseridos no catálogo constitucional

### Referências legais
- Art. 93, IX, CF/88; Art. 225, CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre eficácia positiva e negativa do princípio constitucional
- Conheça o critério de identificação de direitos fundamentais e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direito Constitucional", "legal_refs": ["Art. 93, IX, CF/88; Art. 225, CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:40:31.462717+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=147", "doc_key": "e6fcac8f7669edd8c4d7b8219ac8a2bf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2b0359f51b1a0678afb398490afa49ecb79760c165aa4f0ae1c4825da57aeaa1'),
  ('cpiuris2025::b86e741f34da4047c77418692e142970', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais e Valor Social do Trabalho e da Livre Iniciativa', '## Princípios Fundamentais e Valor Social do Trabalho e da Livre Iniciativa

O texto discute os princípios fundamentais, incluindo a ideia de que todos os direitos constitucionais devem ser considerados fundamentais, independentemente de seu conteúdo. Além disso, aborda o valor social do trabalho e da livre iniciativa, estabelecendo que a ordem econômica é fundada na valorização do trabalho humano e que a ordem social tem como base o primado do trabalho.

### Conceitos
- **Princípio Democrático**: O direito de cada geração se autogovernar
- **Valor Social do Trabalho**: Fundamento da República Federativa do Brasil
- **Livre Iniciativa**: Paradigma do Estado Liberal e do Capitalismo

### Referências legais
- Art. 170
- Art. 193
- Art. 6º
- Art. 7º ao 11

### Dicas de prova
- Entenda o princípio democrático e sua relação com os direitos fundamentais.
- Conheça o valor social do trabalho e sua importância na ordem econômica.
- Aprenda a distinguir entre liberdade econômica e função social da empresa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direito Constitucional", "legal_refs": ["Art. 170", "Art. 193", "Art. 6º", "Art. 7º ao 11"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:41:07.391242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=148", "doc_key": "b86e741f34da4047c77418692e142970"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7102bd984c0aba05a74226c0abed3dbc869d065b8be18b7906f38612debb88be'),
  ('cpiuris2025::19a5cc94ecc89e67c37cb3913ca65166', 'doutrina', 'cp_iuris', 'Direito Constitucional — Restrição à liberdade de iniciativa', '## Restrição à liberdade de iniciativa

A liberdade de iniciativa é garantida pela Constituição e não pode ser restringida injustificadamente, afastando-se apenas em casos específicos.

### Conceitos
- **Liberdade de Iniciativa**: Garantia constitucional que protege a liberdade individual para iniciar atividades econômicas
- **Princípio da Livre Concorrência**: Princípio que permite a existência de múltiplos atores no mercado, garantindo a concorrência justa
- **Proteção Constitucional**: Garantia constitucional que protege os direitos e liberdades individuais

### Referências legais
- Art. 1º, IV da Constituição Brasileira
- Art. 170 da Constituição Brasileira
- ADPF 449/DF
- RE 1054110/SP

### Jurisprudência
- Info. 9398
- STF - São

### Dicas de prova
- Distinção entre liberdade de iniciativa e restrição justificada
- Importância da proteção constitucional dos direitos individuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, IV da Constituição Brasileira", "Art. 170 da Constituição Brasileira", "ADPF 449/DF", "RE 1054110/SP"], "jurisprudence": ["Info. 9398", "STF - São"], "confidence": 0.9, "extracted_at": "2026-05-26T08:41:47.052225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=148", "doc_key": "19a5cc94ecc89e67c37cb3913ca65166"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'dbde275532f10c08f06a7b8ac77b2f974fa952bcfb5faf253f03c7609db0bf5d'),
  ('cpiuris2025::d6f6cb75889511c2811918bcebb43ff2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais do Direito Constitucional', '## Princípios Fundamentais do Direito Constitucional

O constitucionalismo moderno se fundamenta na necessidade de restrição do poder estatal sobre o funcionamento da economia de mercado, protegendo a livre iniciativa e a liberdade profissional.

### Conceitos
- **Liberdade Econômica**: Direito à liberdade de iniciar e exercer atividades econômicas
- **Princípio da Proporcionalidade**: Requisito para que restrições à liberdade sejam legítimas e necessárias
- **Rule of Law**: Sistema jurídico que subordina o poder estatal ao direito
- **Teoria da Escolha Pública**: Análise do processo político e como grupos de poder podem capturar a regulamentação para obter benefícios

### Referências legais
- Art. 5º, II da Constituição Brasileira

### Dicas de prova
- Entenda o conceito de livre iniciativa e sua proteção no direito constitucional
- Identifique a importância do princípio da proporcionalidade na limitação das liberdades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:42:19.356092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=149", "doc_key": "d6f6cb75889511c2811918bcebb43ff2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6e4404f2ccdd554fe26ea44c2c79b15563fb217e899a751d6df76b7dc7ba1669'),
  ('cpiuris2025::0ff9e5e0bea2b26c866a360d31915b9d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Pluralismo político e liberdades', '## Pluralismo político e liberdades

O Estado deve respeitar as diferenças entre as pessoas e tolerar a diversidade de pensamento, proibindo intolerâncias. A Constituição consagra liberdades como expressão, pensamento e religião, decorrentes do pluralismo político.

### Conceitos
- **Pluralismo político**: Diferença entre o pluralismo político e o pluripartidarismo político
- **Liberdade de expressão**: Direito garantido pela Constituição para a liberdade de pensamento e religião
- **Bipartidarismo**: Existência de apenas dois partidos políticos

### Referências legais
- Art. 3º, CF/88
- Art. 5º, CF/88

### Dicas de prova
- Diferenciar pluralismo político e pluripartidarismo político
- Identificar liberdades garantidas pela Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º, CF/88", "Art. 5º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:42:44.635003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=149", "doc_key": "0ff9e5e0bea2b26c866a360d31915b9d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd7ca4942e3ed432952be089bd0cab91d5b4eefc7c062cc5c6eb13b8943ffc773'),
  ('cpiuris2025::03757c88e567295ab29800459dcb25cf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Objetivos Fundamentais da Constituição', '## Objetivos Fundamentais da Constituição

Os objetivos fundamentais estabelecidos na CF/88 são normas dirigentes e teleológicas que fixam metas a serem alcançadas pelo Estado, independentemente da ideologia assumida pelo governo.

### Conceitos
- **Objetivos Fundamentais**: Normas dirigentes e teleológicas que fixam metas a serem alcançadas pelo Estado
- **Desenvolvimento Nacional**: Garantir o desenvolvimento nacional é um objetivo fundamental
- **Erradicar Pobreza**: Erradicar a pobreza e a marginalização é outro objetivo fundamental
- **Promover Bem de Todos**: Promover o bem de todos, sem preconceitos de origem, raça, sexo, cor, idade e outras formas de discriminação
- **Zona Franca**: A criação de zonas específicas para atração de investimentos é um exemplo de medida para reduzir desigualdades regionais
- **Fundo de Combate e Erradicação da Pobreza**: O Fundo Nacional de Desenvolvimento Regional é uma instituição criada para reduzir desigualdades regionais e sociais
- **Discriminação**: Compreender a previsão constitucional do combate de quaisquer formas de discriminação
- **Art. 159-A da CF/88**: O artigo que institui o Fundo Nacional de Desenvolvimento Regional

### Referências legais
- Art. 3º, III da CF/88
- EC 132/2023

### Dicas de prova
- Entenda a noção dos objetivos fundamentais e sua importância na Constituição
- Conheça os exemplos de medidas concretas para alcançar os objetivos fundamentais
- Destaque a previsão constitucional do combate de quaisquer formas de discriminação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Constitucional", "legal_refs": ["Art. 3º, III da CF/88", "EC 132/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:43:43.697379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=150", "doc_key": "03757c88e567295ab29800459dcb25cf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ef01d89d46e701762ed8fe31c2119ed2122b60d0bcd5ce19479467126c2241a6'),
  ('cpiuris2025::dc6227c75623b9479b780d634e3f217a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Promoção de ações com vistas ao desenvolvimento científico e tecnológico e à inovação', '## Promoção de ações com vistas ao desenvolvimento científico e tecnológico e à inovação

O artigo estabelece regras para a promoção de ações relacionadas ao desenvolvimento científico e tecnológico, priorizando projetos de sustentabilidade ambiental e redução de emissões de carbono.

### Conceitos
- **Desenvolvimento Científico e Tecnológico**: Ação destinada a promover o progresso científico e tecnológico.
- **Inovação**: Processo de introdução de novas ideias, métodos ou produtos.
- **Sustentabilidade Ambiental**: Ação destinada a proteger o meio ambiente e preservar os recursos naturais.
- **Redução de Emissões de Carbono**: Ação destinada a reduzir as emissões de gases de efeito estufa.

### Referências legais
- Art. 159, I, "a" da Constituição Federal

### Dicas de prova
- Entenda o conceito de desenvolvimento científico e tecnológico e sua importância.
- Identifique a prioridade dada à sustentabilidade ambiental e redução de emissões de carbono.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direito Constitucional", "legal_refs": ["Art. 159, I, \"a\" da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:44:14.356402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=150", "doc_key": "dc6227c75623b9479b780d634e3f217a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5e69225ca167b8ac3d5762c83e5485fe55fefd15e092bfbc7c081c0aa5530b68'),
  ('cpiuris2025::efce6618e94873ea36b1557af677ab60', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais da Relações Internacionais do Brasil', '## Princípios Fundamentais da Relações Internacionais do Brasil

Os princípios fundamentais que regem as relações internacionais do Brasil, como independência nacional, prevalência dos direitos humanos e autodeterminação dos povos.

### Conceitos
- **Independência Nacional**: Soberania externa, representação do Estado na ordem internacional
- **Prevalência dos Direitos Humanos**: Proteção da dignidade da pessoa humana, obrigações internas e externas
- **Autodeterminação dos Povos**: Direito dos povos à autogoverno e autoadministração
- **Não-Intervenção**: Respeito pela soberania dos demais Estados soberanos
- **Igualdade entre os Estados**: Tratamento igualitário com outros Estados na ordem internacional
- **Defesa da Paz**: Promoção da paz e segurança internacionais
- **Solução Pacífica dos Conflitos**: Resolução de conflitos por meio de negociação e diplomacia
- **Repúdio ao Terrorismo e ao Racismo**: Condenação e combate a essas práticas

### Referências legais
- Art. 4º, CF/88

### Dicas de prova
- Entenda a importância da independência nacional na ordem internacional
- Conheça as diferentes inspirações dos princípios fundamentais
- Destaque a proteção dos direitos humanos como obrigação do Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.151", "page_number": 151, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:45:04.303977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=151", "doc_key": "efce6618e94873ea36b1557af677ab60"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '56e9bba8ac6be913c31e2676766d974099d7f0095f483982ad00e88532087c8b'),
  ('cpiuris2025::1d8a5693981821a67de12c71bba973b8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Princípios Fundamentais', '## Princípios Fundamentais

Resumo objetivo: Princípios fundamentais do Direito Constitucional, incluindo autodeterminação, não intervenção, igualdade entre os Estados e defesa da paz.

### Conceitos
- **Autodeterminação**: Direito dos povos de definir o seu próprio rumo na condução da vida política, econômica, social e cultural.
- **Não intervenção**: Evitar a intervenção direta ou indireta em outros países, seja militar, política, econômica ou culturalmente.
- **Igualdade entre os Estados**: Tratamento igualitário dos Estados nos órgãos judiciais internacionais e nas deliberações e decisões dos órgãos internacionais.
- **Defesa da paz**: Conseguir o estado de paz existente e adotar medidas necessárias ao restabelecimento do estado de paz quando rompido.
- **Solução pacífica dos conflitos**: Resolver controvérsias sem a utilização da força.
- **Repúdio ao racismo e ao terrorismo**: Combater práticas como o racismo e o terrorismo no plano internacional.

### Referências legais
- Art. 5º, XLIII da Constituição Federal

### Dicas de prova
- Entenda a importância da autodeterminação dos povos.
- Conheça as diferentes formas de intervenção e não intervenção nos países estrangeiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, XLIII da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:45:59.604626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=152", "doc_key": "1d8a5693981821a67de12c71bba973b8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7fbf3627fe9f70ab9200887411dc6d2ea9b205e05b6c2349db54914ef78b9bef'),
  ('cpiuris2025::e3908878edba2cb715140a48e0764383', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cooperação entre povos e relações internacionais', '## Cooperação entre povos e relações internacionais

A cooperação internacional é necessária para o progresso da humanidade, exigindo-se uma atuação harmônica, consensual e amistosa. Isso contribui para o estado permanente de paz.

### Conceitos
- **Cooperação internacional**: Necessidade de cooperação entre povos e países para o progresso da humanidade
- **Paz internacional**: Estado permanente de paz

### Referências legais
- Art. 4 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância da cooperação internacional para o progresso da humanidade
- Destaque a necessidade de uma atuação harmônica, consensual e amistosa nas relações internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:46:20.440360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=152", "doc_key": "e3908878edba2cb715140a48e0764383"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6698e4d12de9e0d2a2f0a61d9e70d24eed942a45d1deaf5b0bf7f97f5af206dc'),
  ('cpiuris2025::2b19ae746381dff0f2aa2d4ae1c0113c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Modalidades de Asilo Político', '## Modalidades de Asilo Político

O asilo político é uma modalidade de proteção concedida a estrangeiros que buscam refúgio no Brasil devido a perseguição política em seu país de origem. Existem dois tipos: asilo territorial e asilo diplomático.

### Conceitos
- **Asilo Político**: Proteção concedida a estrangeiros que buscam refúgio no Brasil devido a perseguição política em seu país de origem.
- **Asilo Territorial**: Aceitação de um estrangeiro no território nacional para proteger sua incolumidade ou vida, devido a grave risco apresentado no seu país de origem.
- **Asilo Diplomático**: Modalidade provisória e precária de asilo político concedido pelo país fora do seu território (como em embaixadas e navios ou aeronaves).
- **Refúgio**: Proteção concedida a estrangeiros que buscam refúgio no Brasil devido a perseguição religiosa, por opinião, nacionalidade ou grave violação de direitos humanos.

### Referências legais
- Art. 5º, § 2º da CF/88
- Súmula 346 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Asilo Político e Refúgio

### Dicas de prova
- Distinguir entre asilo político e refúgio.
- Entender a diferença entre asilo territorial e diplomático.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.153", "page_number": 153, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88", "Súmula 346 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Asilo Político e Refúgio"], "confidence": 0.8, "extracted_at": "2026-05-26T08:46:57.432369+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=153", "doc_key": "2b19ae746381dff0f2aa2d4ae1c0113c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ee7bbb1911d2ca26046e40134123687442d2dd30ef149c68b908565caa53e90f'),
  ('cpiuris2025::396de1c956b081f0e3eb8bdda3329422', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria Geral dos Direitos Fundamentais', '## Teoria Geral dos Direitos Fundamentais

A centralidade dos direitos fundamentais ganhou relevância a partir do neoconstitucionalismo, com o objetivo de proteger a dignidade humana e inserir valores éticos na ciência jurídica.

### Conceitos
- **Neoconstitucionalismo**: Movimento jusfilosófico que busca proteger a dignidade humana e inserir valores éticos na ciência jurídica
- **Pós-positivismo**: Corrente jusfilosófica que aceita os princípios constitucionais como normas jurídicas abstratas
- **Dignidade humana**: Valor ético fundamental que deve ser tratado com igual consideração, respeito e dignidade
- **Justiça**: Ideia de correção que se manifesta através dos direitos fundamentais

### Referências legais
- Art. 5 da CF/1988

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre pós-positivismo e legalismo.
- Conheça as premissas para uma teoria dos direitos fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.155", "page_number": 155, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF/1988"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:47:40.438333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=155", "doc_key": "396de1c956b081f0e3eb8bdda3329422"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '14403bdf08e74b77208f8ace1f91054121661f27b7cd559aed2daaf57f1f323a'),
  ('cpiuris2025::351260e9d765424c0f4e307c6b1e1984', 'doutrina', 'cp_iuris', 'Direito Constitucional — Conceito de Direitos Fundamentais', '## Conceito de Direitos Fundamentais

O conceito de direitos fundamentais é objeto de debate doutrinário, com discussão sobre sua distinção em relação aos direitos humanos e sua delimitação terminológica.

### Conceitos
- **Direitos Fundamentais**: Direitos do ser humano reconhecidos e positivados na esfera do direito constitucional positivo de um Estado.
- **Direitos Humanos**: Posições jurídicas que se reconhecem ao ser humano como tal, independentemente de sua vinculação com determinada ordem constitucional.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre direitos fundamentais e direitos humanos, considerando sua fonte normativa.
- Análise da análise de Sarlet sobre o conceito de direitos fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:48:08.033997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=156", "doc_key": "351260e9d765424c0f4e307c6b1e1984"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd2c22a0d589360add38231cd9e6550a3762b455962dc7f95c6a5695831dc16fc'),
  ('cpiuris2025::0d54483dfcbc91595cef0c2d15e08aff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Fundamentalidade material dos direitos fundamentais', '## Fundamentalidade material dos direitos fundamentais

A fundamentalidade material dos direitos fundamentais decorre da dignidade da pessoa humana e são elementos constitutivos da Constituição material.

### Conceitos
- **Dignidade da pessoa humana**: Basis para a proteção dos direitos humanos e fundamentais
- **Direitos fundamentais**: Elemento constitutivo da Constituição material, contendo decisões fundamentais sobre o Estado e a sociedade
- **Fundamentalidade formal**: Distinção entre direitos humanos e fundamentais sob essa ótica

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre direitos humanos e fundamentais
- Conheça a fundamentalidade material dos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:48:28.242453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=156", "doc_key": "0d54483dfcbc91595cef0c2d15e08aff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '99e344a18913b652898a34620789ec1ec02e75a48ecbc974cbd23b4b8047732e'),
  ('cpiuris2025::34f88aea1b64fb19a45cb7ebc190de04', 'doutrina', 'cp_iuris', 'Direito Constitucional — Diferença entre Direitos Humanos e Direitos Fundamentais', '## Diferença entre Direitos Humanos e Direitos Fundamentais

Os direitos humanos são positivados na esfera do Direito Internacional, enquanto os direitos fundamentais são previstos no Direito Constitucional interno de cada Estado. A distinção material entre os dois é feita pela característica de estar consagrado em preceitos da ordem jurídica.

### Conceitos
- **Direitos Humanos**: Reivindicações de perene respeito a certas posições essenciais ao homem, positivadas na esfera do Direito Internacional
- **Direitos Fundamentais**: Posições básicas das pessoas, inscritas em diplomas normativos de cada Estado, garantidos e limitados no espaço e no tempo

### Referências legais
- Art. 4º, II, CF/88

### Dicas de prova
- Entenda a distinção formal feita pela Constituição Federal de 1988 entre direitos humanos e direitos fundamentais.
- Conheça os exemplos de artigos da CF/88 que mencionam o termo ‘direitos humanos’', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Direito Constitucional", "legal_refs": ["Art. 4º, II, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:49:10.199765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=157", "doc_key": "34f88aea1b64fb19a45cb7ebc190de04"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '45a00905bc4766d5cc4683241e4e60015450e3c0610f702ca6da91663f7990f7'),
  ('cpiuris2025::b36b97f935eb5176bacdc6e826c06dd8', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tratados internacionais de direitos humanos e competência constitucional', '## Tratados internacionais de direitos humanos e competência constitucional

Rege-se sobre a equivalência dos tratados internacionais de direitos humanos às emendas constitucionais, bem como sobre a competência federal para processar e julgar causas relacionadas a direitos humanos.

### Conceitos
- **Tratado internacional de direitos humanos**: Acordo internacional que protege os direitos humanos
- **Competência constitucional**: Poder do Estado para tomar decisões sobre questões constitucionais
- **Emenda constitucional**: Mudança no texto da Constituição
- **Deslocamento de competência**: Transferência de competência de um órgão para outro

### Referências legais
- Art. 5º, § 3º, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de tratado internacional de direitos humanos e sua equivalência às emendas constitucionais.
- Conheça a competência federal para processar e julgar causas relacionadas a direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 3º, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:49:37.601809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=157", "doc_key": "b36b97f935eb5176bacdc6e826c06dd8"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '995226705cab31c2bd8b2eb44fcb301936629d7ecefecc5a56e75c4ae8df24d8'),
  ('cpiuris2025::3fc113cd96bd682e85df32178bb13e41', 'doutrina', 'cp_iuris', 'Direito Constitucional — Distinção entre Direitos Humanos e Direitos Fundamentais', '## Distinção entre Direitos Humanos e Direitos Fundamentais

A distinção entre direitos humanos e direitos fundamentais é formal, embora ambos tenham o mesmo fundamento material (dignidade da pessoa humana). Os direitos humanos são protegidos pela ordem internacional, enquanto os direitos fundamentais são afetos à proteção interna dos cidadãos.

### Conceitos
- **Direitos Humanos**: Direitos protegidos pela ordem internacional
- **Direitos Fundamentais**: Direitos afetos à proteção interna dos cidadãos, com fundamento na dignidade da pessoa humana

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção formal entre direitos humanos e fundamentais é fundamental
- Conheça a distinção entre os dois conceitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:50:05.709825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=158", "doc_key": "3fc113cd96bd682e85df32178bb13e41"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e8b15c3b969323a05d082fd22d0f22cf5393862c8893152de8c478f9871b410d'),
  ('cpiuris2025::01d5240fa49895537e6448cdc9f7b383', 'doutrina', 'cp_iuris', 'Direito Constitucional — Origem dos Direitos Fundamentais', '## Origem dos Direitos Fundamentais

A compreensão dos direitos fundamentais exige análise de períodos pretéritos que contribuíram para a sua evolução.

### Conceitos
- **Direitos Fundamentais**: direitos essenciais à convivência humana
- **Evolução dos Direitos Fundamentais**: processo histórico que formou o rol de direitos fundamentais

### Referências legais
- Art. 5 da Constituição Federal

### Dicas de prova
- Análise de períodos pretéritos para compreender a evolução dos direitos fundamentais
- Importância do Código de Hamurábi e da tradição judaica na formação dos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:50:35.273067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=158", "doc_key": "01d5240fa49895537e6448cdc9f7b383"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '72cfda1698d70c39669fd08b9b980319a214c4f85757c35538391f1716f5236f'),
  ('cpiuris2025::9125fcfb9c26ded81325894a1b9eb5da', 'doutrina', 'cp_iuris', 'Direito Constitucional — Origens dos Direitos Fundamentais', '## Origens dos Direitos Fundamentais

A origem dos direitos fundamentais está relacionada à proteção da vida, propriedade e honra, bem como à influência do Direito Natural na Grécia Antiga e no pensamento ocidental. A República Romana e o Império Romano também contribuíram para o desenvolvimento desses direitos.

### Conceitos
- **Direito Natural**: a ideia de uma lei natural inerente a todos os homens
- **Lei das Doze Tábuas**: leis que conferiam direitos como igualdade e propriedade aos cidadãos na República Romana
- **Jus Civile**: direito civil no direito romano
- **Jus Gentium**: direito das gentes no direito romano
- **Jus Naturale**: direito natural no direito romano

### Referências legais
- Art. 5 da Constituição Brasileira
- Súmula 455 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: origens dos direitos fundamentais

### Dicas de prova
- Entenda a importância do Direito Natural na formação dos direitos fundamentais.
- Conheça as contribuições da República Romana e do Império Romano para o desenvolvimento desses direitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira", "Súmula 455 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: origens dos direitos fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-26T08:51:12.082494+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=159", "doc_key": "9125fcfb9c26ded81325894a1b9eb5da"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '635ebbd2d74907c0f9d002daea75e750af55cee690798639dd640dd26aa63b8a'),
  ('cpiuris2025::f6c5bf6cd957eee4ffc7d7a751f1c718', 'doutrina', 'cp_iuris', 'Direito Constitucional — Origem das limitações ao poder do governante', '## Origem das limitações ao poder do governante

A Magna Carta de 1215 é considerada a pedra angular para a construção da democracia moderna, estabelecendo limites ao poder do governante e fixando direitos subjetivos.

### Conceitos
- **Magna Carta**: Documento que limitou o poder do governante em relação aos direitos do homem
- **Direitos Subjetivos**: Direitos individuais garantidos pela Constituição
- **Democracia Moderna**: Sistema político que prioriza a participação cívica e a proteção dos direitos humanos

### Referências legais
- Art. 5 da CF
- Súmula 667/2012 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Limitações ao Poder do Governante

### Dicas de prova
- Entenda a importância da Magna Carta na formação da democracia moderna
- Conheça os documentos internacionais que limitaram o poder do governante em relação aos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "Súmula 667/2012 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Limitações ao Poder do Governante"], "confidence": 0.8, "extracted_at": "2026-05-26T08:51:38.280488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=159", "doc_key": "f6c5bf6cd957eee4ffc7d7a751f1c718"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '349b90aa923dfb5574715fcf85f67d124fe514742ce74923e828f3a63b71bd68'),
  ('cpiuris2025::e06fc33d9fd34f60a1fd4e0a3f0fc33a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria Geral dos Direitos Fundamentais', '## Teoria Geral dos Direitos Fundamentais

O Bill of Rights é um documento histórico que regulava diversas matérias, estabelecendo o princípio do devido processo legal e garantindo direitos fundamentais como a petição, as eleições livres e a proibição de fianças exorbitantes.

### Conceitos
- **Devido Processo Legal**: Princípio que estabelece que o Estado deve agir de acordo com as leis que edita
- **Direitos Fundamentais**: Direitos individuais garantidos pela Constituição
- **Liberalismo**: Ideologia política que defende a liberdade individual e a limitação do poder estatal
- **Divisão de Poderes**: Princípio que estabelece a separação dos poderes entre o Executivo, Legislativo e Judiciário
- **Absolutismo**: Forma de governo em que o soberano detém todo o poder
- **Ideias Iluministas**: Movimento intelectual que defende a razão, a liberdade individual e a igualdade

### Referências legais
- Art. 5 da Constituição Brasileira

### Jurisprudência
- Súmula 397 do STF

### Dicas de prova
- Entenda o contexto histórico do Bill of Rights e sua influência na formação dos direitos fundamentais
- Conheça os principais pensadores da época, como Maquiavel, Hobbes, Locke, Montesquieu e Rousseau', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.160 (1)", "page_number": 160, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira"], "jurisprudence": ["Súmula 397 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:52:28.731577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=160", "doc_key": "e06fc33d9fd34f60a1fd4e0a3f0fc33a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e1d0055bc2dcd8f5cf6c65f8198c2957ba0182ed4d950962c62e7a2b5a269a94'),
  ('cpiuris2025::7b2a2c24f41f7d7849be57b6e0a588f0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Influência do Iluminismo nas Revoluções Burguesas', '## Influência do Iluminismo nas Revoluções Burguesas

O texto discute como o Iluminismo influenciou as Revoluções burguesas do século XVIII, incluindo a Declaração Francesa dos Direitos do Homem e do Cidadão, e como essas revoluções limitaram o poder do Estado.

### Conceitos
- **Pacto social**: Acordo entre homens livres e iguais
- **Governo representativo**: Forma de governo em que os representantes do povo tomam decisões
- **Iluminismo**: Movimento filosófico que pregava ideais de liberdade e igualdade de direitos
- **Constitucionalismo**: Filosofia política que defende a limitação do poder do Estado por meio de documentos constitucionais

### Referências legais
- Art. 5 da Constituição Brasileira

### Dicas de prova
- Entenda o conceito de pacto social e seu papel na formação do governo representativo
- Identifique a influência do Iluminismo nas Revoluções burguesas e seus principais produtos, como a Declaração Francesa dos Direitos do Homem e do Cidadão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.160 (2)", "page_number": 160, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:52:59.688109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=160", "doc_key": "7b2a2c24f41f7d7849be57b6e0a588f0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'f21513596fa0d16d9d8ad4794b9297e5fc3e3982eba49946fad78e41ac938e72'),
  ('cpiuris2025::5d4c1c8a1e087281b9949258660e03ff', 'doutrina', 'cp_iuris', 'Direito Constitucional — Origens do constitucionalismo moderno', '## Origens do constitucionalismo moderno

O constitucionalismo moderno tem suas origens nos movimentos norte-americano e francês, que opuseram-se ao absolutismo monárquico. A Declaração de Direitos do Estado da Virgínia (1776) é considerada a primeira Carta de Declaração de Direitos no sentido moderno, enquanto a Revolução Francesa de 1789 marcou o início do constitucionalismo social.

### Conceitos
- **Constitucionalismo Moderno**: Movimento que opõe-se ao absolutismo monárquico e busca estabelecer limites ao poder do Estado
- **Declaração de Direitos do Estado da Virgínia**: Primeira Carta de Declaração de Direitos no sentido moderno, considerada precursora do constitucionalismo americano
- **Revolução Francesa**: Evento que marcou o início do constitucionalismo social e a derrubada da monarquia absoluta

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Frisar a existência de indícios do movimento norte-americano e francês antes da Constituição de 1787
- Identificar a Declaração de Direitos do Estado da Virgínia como precursora do constitucionalismo americano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.161 (1)", "page_number": 161, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:53:37.062503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=161", "doc_key": "5d4c1c8a1e087281b9949258660e03ff"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'b27fc3f6562fc633b17c650750f2956e7d1ec08b278c2de869ffa1fd0533f5dc'),
  ('cpiuris2025::de023ff8bb4df5f12c7093dfbd436e92', 'doutrina', 'cp_iuris', 'Direito Constitucional — As gerações ou dimensões dos direitos fundamentais', '## As gerações ou dimensões dos direitos fundamentais

A doutrina analisa o processo de afirmação histórica dos direitos fundamentais em gerações, com a existência de direitos fundamentais de primeira, segunda e terceira geração.

### Conceitos
- **geração**: uma fase cronológica do reconhecimento e afirmação dos direitos fundamentais
- **direito fundamental**: um direito inerente à dignidade humana, garantido pela Constituição

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a terminologia ''geração'' e sua aplicação aos direitos fundamentais.
- Conheça as gerações dos direitos fundamentais e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.161 (2)", "page_number": 161, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:54:08.891016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=161", "doc_key": "de023ff8bb4df5f12c7093dfbd436e92"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '30723c00af749c18d5f1ac487d47ebd51adf15976198e2e8018e952ed1f5e9bc'),
  ('cpiuris2025::6e0d1a4191187ed51a409275d2c6c69d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria Geral dos Direitos Fundamentais', '## Teoria Geral dos Direitos Fundamentais

A doutrina majoritária afirma que os direitos fundamentais evoluem de forma progressiva, reconhecendo novos direitos sem suprimir os antigos, e que isso é uma característica comum desses direitos.

### Conceitos
- **Geração**: uma fase ou período na evolução dos direitos fundamentais
- **Dimensão**: uma característica ou aspecto de um direito fundamental que se desenvolve ao longo do tempo
- **Complentaridade**: a capacidade dos novos direitos fundamentais de complementar os antigos, sem suprimi-los

### Referências legais
- Art. 5 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de geração e dimensão nos direitos fundamentais
- Conheça a característica comum dos direitos fundamentais: a complentaridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.162 (1)", "page_number": 162, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:54:37.236584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=162", "doc_key": "6e0d1a4191187ed51a409275d2c6c69d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '56b5f2e2082d9665067f3f0575eecd1d33f055bf256085651e6052af8b6f5ac6'),
  ('cpiuris2025::1876fa26205d95d67979fe93ece8b688', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Fundamentais de Segunda e Terceira Geração', '## Direitos Fundamentais de Segunda e Terceira Geração

Os direitos fundamentais de segunda geração são direitos de prestação que exigem atuação positiva do Estado, com lema da igualdade. São os direitos sociais, econômicos e culturais, reconhecidos em documentos como a Constituição Mexicana, Russa e Weimar. No Brasil, a influência foi significativa na Constituição de 1934.

### Conceitos
- **Direito Fundamental**: direito que faz parte do conjunto dos direitos fundamentais da Constituição
- **Segunda Geração**: gênero de direitos fundamentais que exigem atuação positiva do Estado
- **Terceira Geração**: gênero de direitos fundamentais que protegem o ser humano em coletividade social

### Referências legais
- Art. 196, CF/88
- Art. 205, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo da efetividade

### Dicas de prova
- Entenda a diferença entre direitos fundamentais de segunda e terceira geração
- Conheça os documentos que reconhecem os direitos sociais, econômicos e culturais
- Aprenda sobre a efetividade como garantia para os direitos sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.162 (2)", "page_number": 162, "discipline": "Direito Constitucional", "legal_refs": ["Art. 196, CF/88", "Art. 205, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo da efetividade"], "confidence": 0.8, "extracted_at": "2026-05-26T08:55:09.689277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=162", "doc_key": "1876fa26205d95d67979fe93ece8b688"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8812f4cd0716b8dd809e1de952a16f993a04df7455e6f156b258652a729d1c5e'),
  ('cpiuris2025::8206701d9f7bb188b55f6b02bc557097', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Fundamentais - Terceira Dimensão', '## Direitos Fundamentais - Terceira Dimensão

Os direitos fundamentais de terceira dimensão são caracterizados pela titularidade coletiva e materializam o princípio da solidariedade, sendo considerados valores fundamentais indisponíveis.

### Conceitos
- **Terceira Dimensão**: Caracterizada pela titularidade coletiva
- **Solidariedade**: Princípio que materializa os direitos fundamentais de terceira dimensão
- **Titularidade Coletiva**: Atribuição de poderes a todas as formações sociais
- **Direitos Fundamentais Indisponíveis**: Valores fundamentais que não podem ser negados ou limitados

### Referências legais
- Art. 225 da Constituição Federal de 1988
- Art. 4º, III e VI da Constituição Federal de 1988

### Dicas de prova
- Distinção entre direitos fundamentais de primeira, segunda e terceira dimensão
- Conhecimento do princípio da solidariedade e titularidade coletiva
- Entendimento do conceito de direitos fundamentais indisponíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.163 (1)", "page_number": 163, "discipline": "Direito Constitucional", "legal_refs": ["Art. 225 da Constituição Federal de 1988", "Art. 4º, III e VI da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:55:53.987947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=163", "doc_key": "8206701d9f7bb188b55f6b02bc557097"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'e029adfd108561c0b5d0788cdb93cb6a7f5baca0a230b8940ba2283c78affc1d'),
  ('cpiuris2025::9019befab7b8572a405a784ebc5c626c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Quinta dimensão dos direitos fundamentais', '## Quinta dimensão dos direitos fundamentais

A quinta dimensão dos direitos fundamentais é um conceito que abrange os direitos relacionados à paz, biotecnologia e ciberdireito. Autores como Paulo Bonavides defendem a existência dessa dimensão, destacando o direito à paz como um direito fundamental.

### Conceitos
- **Quinta dimensão dos direitos fundamentais**: Conceito que abrange os direitos relacionados à paz, biotecnologia e ciberdireito
- **Direito à paz**: Direito fundamental defendido por Paulo Bonavides como parte da quinta dimensão dos direitos fundamentais
- **Biotecnologia**: Área que envolve a aplicação das tecnologias biológicas para fins médicos, científicos e industriais
- **Ciberdireito**: Área que regula as relações relacionadas à informática e à internet

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de quinta dimensão dos direitos fundamentais e seus exemplos.
- Identifique os direitos relacionados à biotecnologia e ao ciberdireito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.163 (2)", "page_number": 163, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T08:56:22.509793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=163", "doc_key": "9019befab7b8572a405a784ebc5c626c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd4a3777020c954acd513db0ea0fed2db72f3b7d5e7cddfdd760b44fea38a97a5'),
  ('cpiuris2025::3babc3ebfa79b961b5f88a0fcaf4ed74', 'doutrina', 'cp_iuris', 'Direito Constitucional — Dimensões dos Direitos Fundamentais', '## Dimensões dos Direitos Fundamentais

As dimensões dos direitos fundamentais são categorizadas de acordo com o momento histórico em que surgiram, sendo elas: 1ª Dimensão (Séc. XVIII e XIX), 2ª Dimensão (Séc. XIX e XX), 3ª Dimensão (Séc. XX e XXI), 4ª Dimensão (Direito Constitucional e Democrático de Direito).

### Conceitos
- **Dimensões dos Direitos Fundamentais**: Categorização dos direitos fundamentais com base no momento histórico em que surgiram
- **1ª Dimensão**: Surgiu na Séc. XVIII e XIX, caracterizada por direitos civis e políticos
- **2ª Dimensão**: Surgiu na Séc. XIX e XX, caracterizada por direitos econômicos, sociais e culturais
- **3ª Dimensão**: Surgiu na Séc. XX e XXI, caracterizada por direitos difusos e coletivos
- **4ª Dimensão**: Caracteriza o Direito Constitucional e Democrático de Direito

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a categorização das dimensões dos direitos fundamentais
- Conheça as características de cada dimensão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.164", "page_number": 164, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:57:01.095080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=164", "doc_key": "3babc3ebfa79b961b5f88a0fcaf4ed74"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9239abfd15435f2b65087b60f0d9b51709a1c176fcc9b10e753cce3b4d8d3d26'),
  ('cpiuris2025::92bb9b35796e76d334e5f943efe26829', 'doutrina', 'cp_iuris', 'Direito Constitucional — Funções dos Direitos Fundamentais e Teoria do Status de Jellinek', '## Funções dos Direitos Fundamentais e Teoria do Status de Jellinek

Os direitos fundamentais têm funções diversas na ordem jurídica, sendo analisadas à luz da teoria do status de Georg Jellinek. Os indivíduos podem fazer parte de uma esfera pública enquanto membro da comunidade política, vinculando-se ao Estado e relacionando-se com ele por quatro espécies de situações jurídicas.

### Conceitos
- **Status subjectionis**: status passivo, pelo qual o indivíduo está subordinado aos poderes estatais
- **Status negativus**: status libertatis, pelo qual é reconhecida ao indivíduo uma esfera jurídica individual de liberdade
- **Status positives**: status civitatis, pelo qual são franqueadas ao indivíduo as instituições estatais para exigir prestações positivas do Estado
- **Status activus**: status em que é assegurada à indivíduo a possibilidade de participar ativamente da formação da vontade política estatal
- **Função de defesa ou de liberdade**: garantia de defesa do cidadão perante o Estado, protegendo-as contra arbítrios estatais
- **Função de prestação**: exigência de atuação positiva (prestação material) por parte do Estado para a satisfação de necessidades
- **Função de proteção perante terceiros**: garantia do exercício dos direitos fundamentais, também em face de atividades de terceiros

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a teoria do status de Jellinek e as funções dos direitos fundamentais
- Diferencie entre os diferentes tipos de status e suas funções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T08:58:03.598958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=165", "doc_key": "92bb9b35796e76d334e5f943efe26829"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd4df6ef10905a03c37e1e04be9ec9e18e28ac3d754db8ba1589d11efb93cdbcd'),
  ('cpiuris2025::7a34675555607a7e5169e4398d64eab4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Fundamentais', '## Direitos Fundamentais

Resumo objetivo: Os direitos fundamentais são caracterizados por funções de não discriminação e participação, garantindo igual tratamento a todas as pessoas e o direito de participação na formação da vontade política do Estado.

### Conceitos
- **Direitos Fundamentais**: direitos que limitam a ação do Estado
- **Função de não discriminação**: proibição de discriminação em relação aos direitos fundamentais
- **Função de participação**: direito de participação na formação da vontade política do Estado

### Referências legais
- Art. 5 da Constituição Federal

### Dicas de prova
- Entenda a função de não discriminação e de participação nos direitos fundamentais.
- Conheça os princípios que regem os direitos fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:58:25.270511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=165", "doc_key": "7a34675555607a7e5169e4398d64eab4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a0045efcc769f853579c0e0671cb608c8a8ce31ffc09cbaa998ad2ff0af66de2'),
  ('cpiuris2025::ca710aba519b20d7901b9c1a36a21fb6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Características dos Direitos Fundamentais', '## Características dos Direitos Fundamentais

As principais características com probabilidade de cobrança em provas de concurso público, relacionadas aos direitos fundamentais.

### Conceitos
- **Universalidade**: Direitos humanos pertencem a todos os seres humanos, sem distinções
- **Fundamentaldade**: Direitos humanos são fundamentais e não protegem todas as formas de opressão
- **Abstração**: Direitos humanos são abstratos e não dependem de contextos específicos
- **Moralidade**: Direitos humanos têm uma base moral e ética
- **Prioritariedade**: Direitos humanos devem ser priorizados em relação a outros direitos

### Referências legais
- Art. I, Declaração Universal dos Direitos Humanos de 1948

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a concepção universal de direitos humanos e suas críticas.
- Conheça as características fundamentais dos direitos humanos e sua importância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Direito Constitucional", "legal_refs": ["Art. I, Declaração Universal dos Direitos Humanos de 1948"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:58:54.794329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=166", "doc_key": "ca710aba519b20d7901b9c1a36a21fb6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '15b0160d770833d58775d138c95a48b46b1d95cec9b38462a100cc78636ee761'),
  ('cpiuris2025::b9a9c347feb42c04fca450479c5ec7b6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Fundamentais e Abstratos', '## Direitos Fundamentais e Abstratos

Os direitos fundamentais são considerados abstratos, pois sua significação pode variar de caso em caso, e não dependem de positivação para existir.

### Conceitos
- **Direito Fundamental**: direito que protege interesses e necessidades fundamentais do ser humano
- **Abstrato**: direitos fundamentais que não dependem de positivação para existir, mas sim de sua significação
- **Moralidade**: validez dos direitos humanos apenas moral, independentemente da positivação
- **Prioritário**: direitos humanos são prioritários em relação às normas jurídico-positivas

### Referências legais
- Art. 5º da Constituição Brasileira

### Dicas de prova
- Entenda a distinção entre direito fundamental e direito subjetivo.
- Conheça a teoria da abstração dos direitos fundamentais.
- Avalie a importância da moralidade nos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T08:59:30.378580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=166", "doc_key": "b9a9c347feb42c04fca450479c5ec7b6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c91d3853e6b4f1013e4e047ef1974a097016011550e75b95ff975ca3bc6a51b9'),
  ('cpiuris2025::091644e1540bc1a5b8e34a1a184e876b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Irrenunciabilidade e Imprescritibilidade dos Direitos Fundamentais', '## Irrenunciabilidade e Imprescritibilidade dos Direitos Fundamentais

Os direitos fundamentais não podem ser renunciados ou cedidos, nem prescindem com o decurso do tempo. A reparação de danos pode estar sujeita à prescrição.

### Conceitos
- **Irrenunciabilidade**: Não pode ser renunciado ou cedido
- **Imprescritibilidade**: Não prescindem com o decurso do tempo
- **Reparação de danos**: Pode estar sujeita à prescrição

### Referências legais
- Art. 5º, inciso XXXIX da CF/88
- Decreto 4.388/2022

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre direitos fundamentais e direitos humanos
- Importância do artigo 5º, inciso XXXIX da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.167", "page_number": 167, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso XXXIX da CF/88", "Decreto 4.388/2022"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T08:59:57.670046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=167", "doc_key": "091644e1540bc1a5b8e34a1a184e876b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '28c2bf706f37a7afbb163d31117f538a152c293780b29925290b5a87bc0191bd'),
  ('cpiuris2025::9285b22a799a2ffa3530a1ecd992b0c1', 'doutrina', 'cp_iuris', 'Direito Constitucional — Indivisibilidade e Interdependência dos Direitos Fundamentais', '## Indivisibilidade e Interdependência dos Direitos Fundamentais

Os direitos fundamentais são indivisíveis e interdependentes, exigindo a consideração conjunta de todos os direitos previstos para garantir a dignidade humana.

### Conceitos
- **Indivisibilidade**: A ideia de que os direitos fundamentais são inseparáveis e devem ser considerados como um conjunto
- **Interdependência**: A relação necessária entre os direitos fundamentais, exigindo a realização simultânea de todos eles para garantir a dignidade humana

### Referências legais
- Art. 5 da Constituição Federal
- Súmula 349 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Indivisibilidade dos Direitos Fundamentais

### Dicas de prova
- Entenda a ideia de indivisibilidade e interdependência dos direitos fundamentais para responder corretamente às questões.
- Não confunda a indivisibilidade com a hierarquia entre os direitos fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Federal", "Súmula 349 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Indivisibilidade dos Direitos Fundamentais"], "confidence": 0.9, "extracted_at": "2026-05-26T09:00:27.763799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=168", "doc_key": "9285b22a799a2ffa3530a1ecd992b0c1"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '958abc2014e7f46b009ebc3adbbd4ce01d56c59bb1f91cf1d750fbecd718eced'),
  ('cpiuris2025::9a563c6378eb34203c5219c6397aa1b5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Historicidade dos Direitos Fundamentais', '## Historicidade dos Direitos Fundamentais

Os direitos fundamentais surgem a partir de um processo histórico, com lutas e revoltas contra o Estado arbitrário, levando à consagração de direitos civis e políticos, seguidos por direitos econômicos, sociais e culturais, e finalmente, direitos difusos e coletivos.

### Conceitos
- **Direitos Fundamentais**: direitos que decorrem de um processo histórico
- **Perfil Absenteísta de Estado**: Estado liberal com consagração dos direitos civis e políticos
- **Direitos de Segunda Geração**: direitos econômicos, sociais e culturais
- **Direitos Difusos e Coletivos**: direitos assegurados a toda uma coletividade, com base na ideia de solidariedade e fraternidade

### Referências legais
- Art. 5 da CF

### Dicas de prova
- Entenda a historicidade dos direitos fundamentais
- Distinção entre perfil absentísta de Estado e direitos de segunda geração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:01:05.143558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=168", "doc_key": "9a563c6378eb34203c5219c6397aa1b5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '58c048ab92e79dc4ff283f59910cbef5f39176a7368dadd3214d70111aef25fc'),
  ('cpiuris2025::5921c63e7b2bb5acfe2c06c5d9756087', 'doutrina', 'cp_iuris', 'Direito Constitucional — Aplicabilidade Direta e Imediata dos Direitos Fundamentais', '## Aplicabilidade Direta e Imediata dos Direitos Fundamentais

Os direitos fundamentais têm aplicabilidade direta e imediata, conforme art. 5º, §1º da CF/88, mas podem ser avaliados de forma diferente no âmbito internacional.

### Conceitos
- **Aplicabilidade Direta**: A capacidade dos direitos fundamentais de serem aplicados imediatamente sem a necessidade de integração legislativa.
- **Autoaplicabilidade**: A capacidade das normas internacionais de serem aplicadas automaticamente, sem a necessidade de avaliação da intenção das partes.
- **Mens Legislatoris**: A intenção das partes ao criar uma norma internacional.
- **Progressividade**: O princípio de que os direitos fundamentais devem ser protegidos progressivamente, até o máximo dos recursos disponíveis do Estado.

### Referências legais
- Art. 5º, §1º da CF/88

### Jurisprudência
- Opinião Consultiva n.º 7 da Corte Interamericana de Direitos Humanos (1986)

### Dicas de prova
- Entenda a distinção entre autoaplicabilidade e mens legislatoris.
- Conheça o conceito de progressividade nos documentos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §1º da CF/88"], "jurisprudence": ["Opinião Consultiva n.º 7 da Corte Interamericana de Direitos Humanos (1986)"], "confidence": 0.8, "extracted_at": "2026-05-26T09:01:40.435547+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=169", "doc_key": "5921c63e7b2bb5acfe2c06c5d9756087"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8dfb3d58711032ca9e6b0d900d7835518e33f3db50e8cc24f78e6df692e49b18'),
  ('cpiuris2025::d24d76bf24d4c53cd79d319700af819e', 'doutrina', 'cp_iuris', 'Direito Constitucional — Relatividade dos Direitos Fundamentais', '## Relatividade dos Direitos Fundamentais

A relativização dos direitos fundamentais ocorre quando estes são utilizados para acobertar práticas ilícitas ou evitar a anulação de direitos de terceiros.

### Conceitos
- **Relatividade dos Direitos Fundamentais**: O direito de relativizar os direitos fundamentais
- **Práticas Ilícitas**: Ações que vão contra a lei ou os direitos humanos
- **Direitos de Terceiros**: Direitos de pessoas diferentes do Estado ou da parte que está agindo

### Referências legais
- Art. 5º, § 2º da CF

### Dicas de prova
- Entenda a noção de relatividade dos direitos fundamentais e como ela se aplica em práticas ilícitas
- Diferencie entre direitos fundamentais absolutos e relativizados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:02:03.027725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=169", "doc_key": "d24d76bf24d4c53cd79d319700af819e"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7c9bce8573b49693f2e66d76b6b3fd69c2a7e2f8e5a9358f7155ff24553610e4'),
  ('cpiuris2025::8ac2b9804684f7939e5c770effcb3376', 'doutrina', 'cp_iuris', 'Direito Constitucional — Reestruturação dos Direitos Fundamentais', '## Reestruturação dos Direitos Fundamentais

Os direitos fundamentais não são absolutos e podem ser restringidos ou limitados por previsão constitucional ou legal, em benefício do interesse social e em observância às bases de proporcionalidade.

### Conceitos
- **Efetividade**: Deve-se verificar a implementação de medidas efetivas para a concretização dos direitos fundamentais.
- **Abertura ou Inexauribilidade**: A abertura dos direitos humanos é prevista tanto no âmbito interno quanto no âmbito internacional.

### Referências legais
- Art. 5º, XLVII da CF/88
- Art. 84, XIX da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunta sobre a reestruturação dos direitos fundamentais e a necessidade de implementação de medidas efetivas.
