Os direitos fundamentais são essenciais por natureza, tendo conteúdo material na dignidade humana e formal na prevalência de valores supremos. A dimensão subjetiva relaciona-se à atuação positiva ou negativa do Estado em relação aos indivíduos, enquanto a dimensão objetiva se refere à eficácia irradiante dos direitos fundamentais como parâmetros da ordem jurídica.

### Conceitos
- **Dimensão Subjetiva**: Relaciona-se à atuação positiva ou negativa do Estado em relação aos indivíduos
- **Dimensão Objetiva**: Se refere à eficácia irradiante dos direitos fundamentais como parâmetros da ordem jurídica
- **Ação Positiva**: Exigência de atuação positiva do Estado em relação aos indivíduos
- **Ação Negativa**: Exigência de atuação negativa do Estado em relação aos indivíduos

### Referências legais
- Art. 5 da CF
- Súmula 455 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Dimensão Subjetiva e Objetiva dos Direitos Fundamentais

### Dicas de prova
- Entenda a distinção entre dimensão subjetiva e objetiva dos direitos fundamentais
- Conheça as exigências de atuação positiva e negativa do Estado em relação aos indivíduos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "Súmula 455 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Dimensão Subjetiva e Objetiva dos Direitos Fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-26T09:03:24.510401+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=171", "doc_key": "772102ccbd3ba39041482f54a1b0c1d0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '110a87dea811ca1b97d2da7384ec0f61590f628e13042c1d556b4e2dc8566ed2'),
