Os direitos fundamentais foram concebidos como limites ao exercício do poder estatal, protegendo a esfera jurídica individual. A eficácia vertical se refere à relação entre Estado e particular, enquanto a eficácia horizontal se refere às relações privadas entre indivíduos em igualdade.

### Conceitos
- **Eficácia Vertical**: Relação entre o Estado e o particular
- **Eficácia Horizontal**: Relações privadas entre indivíduos em igualdade
- **Teorias sobre aplicabilidade de direitos fundamentais nas relações privadas**: Três teorias surgiram para abordar a questão

### Referências legais
- Art. 5 da Constituição Federal

### Dicas de prova
- Entenda a diferença entre eficácia vertical e horizontal
