  ('cpiuris2025::cfd9bd05fed48a2776771891f4b98de2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teorias sobre aplicabilidade dos direitos fundamentais nas relações privadas', '## Teorias sobre aplicabilidade dos direitos fundamentais nas relações privadas

Discute-se as teorias negativas, da eficácia direta e imediata, e da eficácia indireta e mediata sobre a aplicabilidade dos direitos fundamentais nas relações privadas.

### Conceitos
- **Teoria Negativa**: Rejeita a aplicação dos direitos fundamentais às relações privadas
- **Eficácia Direta e Imediata**: Os direitos fundamentais têm aplicabilidade direta e imediata nas relações entre particulares, independentemente de prévia atividade legislativa
- **Eficácia Indireta e Mediata**: A aplicação dos direitos fundamentais nas relações privadas requer atuação do legislador infraconstitucional para conformar as relações à luz de normas constitucionais definidoras de direitos

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 158.215/RS

### Dicas de prova
- Diferenciar entre as teorias e entender a aplicabilidade dos direitos fundamentais nas relações privadas
