  ('cpiuris2025::254be2a2d046f49c2275800d8d8c2d90', 'doutrina', 'cp_iuris', 'Direito Constitucional — Eficácia dos direitos fundamentais', '## Eficácia dos direitos fundamentais

A eficácia dos direitos fundamentais é um tema importante na teoria jurídica, abordando a sua aplicação em relações privadas e públicas. Robert Alexy defende um modelo de complementaridade entre as eficácias indireta e direta, acrescentando a ''teoria dos deveres de proteção'' para explicar a incidência desses direitos.

### Conceitos
- **Eficácia direta**: aplicação imediata do direito fundamental
- **Eficácia indireta**: aplicação secundária do direito fundamental
- **Teoria dos deveres de proteção**: dever de proteção do Estado na relação entre particulares
- **Modelo de complementaridade**: combinando eficácias direta e indireta

### Referências legais
- Art. 5 da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre eficácia direta e indireta
- Conheça a teoria dos deveres de proteção e o modelo de complementaridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T09:05:02.188219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=172", "doc_key": "254be2a2d046f49c2275800d8d8c2d90"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'faece9c27695008c1c6d4b52c6af91bb1b42af350335810c4526c4c59f0a723c'),
