A eficácia horizontal direta dos direitos fundamentais é uma teoria que busca superar a teoria clássica e demonstrar novas modalidades de violações de direitos fundamentais.

### Conceitos
- **Eficácia Horizontal Direta**: Teoria que busca superar a teoria clássica e demonstrar novas modalidades de violações de direitos fundamentais.
- **Eficácia Vertical**: Teoria tradicional que limita a aplicação dos direitos fundamentais apenas às relações entre o Estado e os cidadãos
- **Contraditório**: O direito de ser ouvido antes da decisão que afeta os seus interesses
- **Ampla Defesa**: O direito de ter assistência jurídica para defender os próprios interesses

### Referências legais
- Art. 5º, LXXII da CF
- Súmula 295/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Eficácia Horizontal Direta

