A teoria interna considera que os limites de um direito fundamental são encontrados no próprio direito, sem restrições externas.

### Conceitos
- **Teoria Interna**: considera que os limites de um direito fundamental são encontrados no próprio direito
- **Limites Imanentes**: não admite restrições externas a um direito fundamental
- **Direitos Fundamentais**: direitos protegidos pela Constituição

### Referências legais
- Art. 5 da CF

### Dicas de prova
- Entenda que a teoria interna não admite conflitos entre direitos fundamentais
