  ('cpiuris2025::70f34d61c1062e1bd308935e01563026', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria Geral dos Direitos Fundamentais', '## Teoria Geral dos Direitos Fundamentais

A teoria geral dos direitos fundamentais afirma que os limites desses direitos estão contidos no próprio direito e não são impostos a partir do exterior. A teoria externa, por outro lado, considera que existem restrições aos direitos fundamentais, mas estabelece requisitos para que essas restrições sejam válidas.

### Conceitos
- **Teoria Geral dos Direitos Fundamentais**: afirma que os limites dos direitos fundamentais estão contidos no próprio direito
- **Teoria Externa**: considera que existem restrições aos direitos fundamentais, mas estabelece requisitos para que essas restrições sejam válidas
- **Limites dos Limites**: mecanismo de defesa dos direitos fundamentais contra atos abusivos
- **Núcleo Essencial**: parte fundamental do direito restringido que deve ser preservada
- **Dignidade da Pessoa Humana**: aspecto material dos direitos fundamentais que deve ser protegido
- **Segurança Jurídica**: privilégio dado à clareza e precisão nas limitações de direitos fundamentais
- **Isonomia**: necessidade de restrições gerais e abstratas para evitar discriminações absurdas
- **Proporcionalidade**: regra que deve ser seguida nas limitações de direitos fundamentais

### Referências legais
- Art. 5 da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre Teoria Geral e Teoria Externa dos direitos fundamentais
- Conheça os requisitos para que as restrições de direitos fundamentais sejam válidas (núcleo essencial, dignidade da pessoa humana, segurança jurídica, isonomia e proporcionalidade)
- Aprenda a aplicar a teoria dos limites dos limites em casos concretos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T09:06:57.267897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=174", "doc_key": "70f34d61c1062e1bd308935e01563026"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '60d0ce369125e9ff06e0022c9172768dc65a8d7d48cb2d431422d3092c2b7cd2'),
  ('cpiuris2025::cf9d4acff8e71ce78938e9ae948db462', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria Interna e Externa de Direitos Fundamentais', '## Teoria Interna e Externa de Direitos Fundamentais

A teoria interna e externa de direitos fundamentais são abordadas, com a discussão sobre a dicotomia entre direito e restrição. A teoria externa é caracterizada pela ponderação de interesses, enquanto a teoria interna não se baseia na concepção de limite imanente.

### Conceitos
- **Teoria Interna**: Abordagem que busca superar os pontos de tensão entre direitos no processo de interpretação
- **Teoria Externa**: Abordagem que se baseia na concepção de limite imanente para resolver conflitos entre direitos fundamentais
- **Dicotomia Direito-Restrição**: Conceito que direciona a atuação do intérprete em relação aos direitos e restrições
- **Ponderação de Interesses**: Técnica utilizada pela teoria externa para resolver conflitos entre direitos fundamentais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre teoria interna e externa de direitos fundamentais
- Conheça a concepção de dicotomia direito-restrição e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:07:28.815417+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=174", "doc_key": "cf9d4acff8e71ce78938e9ae948db462"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'a3e3546af53de8455bf96af0a3d4aee5c0c46cd6e3694f61332b460fc553eae1'),
  ('cpiuris2025::63d2ff788e66283a48b69ecdc2618a75', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria Geral dos Direitos Fundamentais e Deveres Fundamentais', '## Teoria Geral dos Direitos Fundamentais e Deveres Fundamentais

A regra da proporcionalidade é composta por três sub-regras: adequação, necessidade e proporcionalidade em sentido estrito. Os deveres fundamentais decorrem da observância dos direitos fundamentais e são uma contrapartida lógica à atribuição de direitos.

### Conceitos
- **Proporcionalidade**: Regra que busca equilibrar os benefícios e malefícios de dois princípios
- **Adequação**: Investigar a maneira mais adequada para realizar o princípio cujo peso deve prevalecer
- **Necessidade**: Buscar o meio menos gravoso para solução do caso concreto
- **Proporcionalidade em sentido estrito**: Sopesamento de benefícios e malefícios
- **Deveres Fundamentais**: Contrapartida lógica à atribuição de direitos
- **Eficácia Irradiante**: Aptidão para produzir efeitos em todo o sistema jurídico
- **Tipologias dos Deveres Fundamentais**: Classificações como Conexos ou Correlatos, Autônomos

### Referências legais
- Art. 5 da CF/88

### Dicas de prova
- Entenda a regra da proporcionalidade e suas sub-regras
- Conheça as tipologias dos Deveres Fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.175 (1)", "page_number": 175, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:08:19.085924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=175", "doc_key": "63d2ff788e66283a48b69ecdc2618a75"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '443bb50769aef67ffd4b9daf9a1b4538916e1775690ddca0a049a33ecc5f1573'),
  ('cpiuris2025::bcdb4bf6dcd24333f61071749289e9b6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Deveres fundamentais e expressos vs implícitos', '## Deveres fundamentais e expressos vs implícitos

Resumo objetivo: São os deveres que decorrem diretamente de um direito fundamental, como o art. 225 da CF/88, que estabelece deveres para proteger o meio ambiente. Já os deveres implícitos são aqueles não relacionados à conformação de um direito fundamental e estabelecidos na Constituição autônoma.

### Conceitos
- **Deveres fundamentais**: decorrem diretamente de um direito fundamental
- **Deveres implícitos**: não relacionados à conformação de um direito fundamental e estabelecidos na Constituição autônoma

### Referências legais
- Art. 143 da CF/88
- Art. 225 da CF/88

### Dicas de prova
- Diferenciar entre deveres fundamentais e implícitos
