  ('cpiuris2025::8a9c3f1550c0f99b737b9314dab30b18', 'doutrina', 'cp_iuris', 'Direito Constitucional — Deveres Expressos e Implícitos', '## Deveres Expressos e Implícitos

São expressos na Constituição (ex: serviço militar obrigatório) ou não, decorrendo diretamente de um direito fundamental. São divididos em deveres defensivos (negativos) e prestacionais (positivos).

### Conceitos
- **Deveres Expressos**: São aqueles expressos na Constituição
- **Deveres Implícitos**: São aqueles que não se encontram expressos na Constituição, decorrendo diretamente de um direito fundamental
- **Deveres Defensivos (ou Negativos)**: São aqueles que estabelecem ao seu destinatário um comportamento negativo, omissivo, de abstenção de conduta em relação ao direito do titular
- **Deveres Prestacionais (ou Positivos)**: São aqueles que impõem ao seu destinatário um comportamento positivo, um fazer, uma prestação em relação ao direito do titular

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre deveres expressos e implícitos
- Conheça as características de deveres defensivos e prestacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.176 (1)", "page_number": 176, "discipline": "Direito Constitucional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:09:15.663064+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=176", "doc_key": "8a9c3f1550c0f99b737b9314dab30b18"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4d5bd2576103a454935122824554a4ff01f952edb99dcd1589070b78d672dbef'),
  ('cpiuris2025::24e621d4299a424ffa2fc88da9c35bed', 'doutrina', 'cp_iuris', 'Direito Constitucional — Justiça de Transição', '## Justiça de Transição

A Justiça de Transição é um conceito jurídico que se refere ao processo de investigação e julgamento dos crimes cometidos durante o regime autoritário, visando promover a reconciliação e fornecer reparações às vítimas.

### Conceitos
- **Justiça de Transição**: Processo de investigação e julgamento dos crimes cometidos durante o regime autoritário
- **Investigação**: Ação de coletar provas e evidências para esclarecer a verdade sobre um crime
- **Reparações às vítimas**: Fornecimento de compensações às pessoas que sofreram danos ou perdas por causa do crime
- **Reconciliação**: Processo de superar as divisões e conflitos causados pelo crime, visando promover a paz e a estabilidade

### Referências legais
- Art. 85 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda o conceito de Justiça de Transição e seus objetivos
- Identifique os pilares fundamentais da Justiça de Transição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.176 (2)", "page_number": 176, "discipline": "Direito Constitucional", "legal_refs": ["Art. 85 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:09:53.183107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=176", "doc_key": "24e621d4299a424ffa2fc88da9c35bed"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '99db3f8c5bf4ee76fafdf43f94b2003805e91a38308ffc1e359ffc5e0db031a9'),
  ('cpiuris2025::9456ae8aca7d99e50989aecc01701faa', 'doutrina', 'cp_iuris', 'Direito Constitucional — Teoria Geral dos Direitos Fundamentais', '## Teoria Geral dos Direitos Fundamentais

O texto discute a importância da responsabilidade dos perpetradores das violações de direitos humanos, a verdade e a memória, e a reparação das vítimas e de suas famílias.

### Conceitos
- **Responsabilidade dos perpetradores**: Exigência essencial para o fornecimento de reparação eficaz às vítimas
- **Verdade e Memória**: Imprescindibilidade de dar publicidade aos acontecimentos do passado para evitar a repetição de violações de direitos humanos
- **Reparação das vítimas**: Dever dos Estados de reparar as vítimas de graves violações de direitos humanos, incluindo restituição, compensação, reabilitação e satisfação

### Referências legais
- Art. 5º da Constituição Brasileira de 1988
- Lei n.º 6.683/1979 - Lei da Anistia

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre responsabilidade dos perpetradores e combate à impunidade
- Importância da verdade e da memória para evitar a repetição de violações de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Brasileira de 1988", "Lei n.º 6.683/1979 - Lei da Anistia"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T09:10:26.893315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=177", "doc_key": "9456ae8aca7d99e50989aecc01701faa"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '55ad093b80aadb5124d81324b26f99091bdfb4c5ed9d45ab5b672507a1fb6ffe'),
  ('cpiuris2025::198761d69b77302943765ba3773cdc53', 'doutrina', 'cp_iuris', 'Direito Constitucional — Anistia política e justiça transicional no Brasil', '## Anistia política e justiça transicional no Brasil

A anistia política foi concedida aos agentes de repressão do período ditatorial, tornando-se obstáculo às investigações e persecuções criminais. A CF/88 trouxe o art. 8º ADCT, que concede anistia a certos indivíduos atingidos por atos políticos durante o regime militar.

### Conceitos
- **Anistia política**: Concessão de imunidade a penalidades para agentes de repressão do período ditatorial
- **Justiça transicional**: Política que busca reparar os danos causados pelo regime militar
- **Decreto Legislativo nº 18/1961**: Decreto que abrangia agentes de repressão do período ditatorial
- **Decreto-Lei nº 864/1969**: Decreto-lei que abrangia atos políticos contra certas pessoas
- **ADCT**: Aditamento à Constituição Federal
- **CF/88**: Constituição Federal de 1988

### Referências legais
- Art. 8º, ADCT

### Dicas de prova
- Entenda a diferença entre anistia política e justiça transicional
- Identifique os dispositivos legais que concederam anistia aos agentes de repressão do período ditatorial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direito Constitucional", "legal_refs": ["Art. 8º, ADCT"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:11:00.415914+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=177", "doc_key": "198761d69b77302943765ba3773cdc53"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '621d55b15c2da6c7a090d8039564140c89ad643d3d2dffade7bf2eaf7669bbe0'),
  ('cpiuris2025::dbda27f974dc32318699127354137efb', 'doutrina', 'cp_iuris', 'Direito Constitucional — Estado de Coisas Inconstitucional (ECI) e direitos fundamentais', '## Estado de Coisas Inconstitucional (ECI) e direitos fundamentais

O texto discute as medidas tomadas no Brasil para abordar os direitos humanos, especialmente após a ditadura militar, incluindo a criação da Comissão Nacional da Verdade e a aprovação da Súmula nº 647 do STJ que considera as ações indenizatórias por danos morais e materiais decorrentes de atos de perseguição política imprescritíveis.

### Conceitos
- **Dignidade da pessoa humana**: Conceito fundamental para a proteção dos direitos humanos
- **Direitos fundamentais**: Direitos inalienáveis e universais, garantidos pela Constituição
- **Estado de Coisas Inconstitucional (ECI)**: Situação em que o Estado não observa a dignidade da pessoa humana

### Referências legais
- Art. 5º, II da Constituição Brasileira
- Súmula nº 647 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da dignidade da pessoa humana nos direitos humanos
- Conheça os direitos fundamentais e como eles são protegidos pela Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição Brasileira", "Súmula nº 647 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T09:11:45.859784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=178", "doc_key": "dbda27f974dc32318699127354137efb"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '55428690a664effe06143b5c6f4e9c2f4268cf9272580f19e178e864b3649649'),
  ('cpiuris2025::98620efba2dd69facd3ab4e25c8599cd', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantias dos Direitos Fundamentais e a Intervenção Judicial no Estado Inconstitucional', '## Garantias dos Direitos Fundamentais e a Intervenção Judicial no Estado Inconstitucional

O juiz constitucional enfrenta uma realidade social necessitada de transformação urgente, com falhas estruturais e impasses políticos que implicam o estado inconstitucional e a improbabilidade do governo superar esse estágio sem intervenção judicial ampla.

### Conceitos
- **Garantias dos Direitos Fundamentais**: direitos fundamentais protegidos pela Constituição
- **Intervenção Judicial**: ação do juiz constitucional para proteger os direitos fundamentais
- **Estado Inconstitucional**: situação em que o governo não respeita as garantias constitucionais
- **Omissão Pública**: falta de ação do poder público para proteger os direitos fundamentais

### Referências legais
- Art. 5 da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de garantias dos direitos fundamentais e a importância da intervenção judicial no estado inconstitucional.
- Identifique as pressuposições do ECI (Estado de Coisas Inconstitucional) e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T09:12:17.186141+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=178", "doc_key": "98620efba2dd69facd3ab4e25c8599cd"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '47c3d47b6f4e7123457f0ad15dc9b74c500965ea03ac12368523950d8c2b3490'),
  ('cpiuris2025::81a09902dd6cecb72aafafd402e1ece4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Técnica Exceional de Conformidade com a Constituição (ECI)', '## Técnica Exceional de Conformidade com a Constituição (ECI)

A ECI é uma técnica não prevista na Constituição, mas utilizada em hipóteses excepcionais para garantir a conformidade com a Constituição. Ela pode ser aplicada quando há violação generalizada e sistêmica de direitos fundamentais, inércia ou incapacidade reiterada das autoridades públicas em modificar a conjuntura, ou situação que exige a atuação de uma pluralidade de autoridades.

### Conceitos
- **Direitos Fundamentais**: direitos previstos na Constituição que são essenciais para a proteção da liberdade e dignidade das pessoas
- **Conformidade com a Constituição**: a necessidade de garantir que as ações do Estado estejam em conformidade com os princípios e normas constitucionais
- **Técnica Exceional**: uma técnica não prevista na Constituição, mas utilizada em hipóteses excepcionais para garantir a conformidade com a Constituição

### Referências legais
- Art. 5 da CF
- Súmula 634/STF

### Jurisprudência
- Arguição de Descumprimento de Preceito Fundamental n.º 347/DF
- Informativo 794/STF

### Dicas de prova
- Entenda a importância dos direitos fundamentais e como eles são protegidos pela Constituição.
- Conheça a técnica Exceional de Conformidade com a Constituição (ECI) e suas hipóteses excepcionais.
- Análise da decisão do STF em relação à violação sistemática de direitos fundamentais do preso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5 da CF", "Súmula 634/STF"], "jurisprudence": ["Arguição de Descumprimento de Preceito Fundamental n.º 347/DF", "Informativo 794/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:12:57.129186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=179", "doc_key": "81a09902dd6cecb72aafafd402e1ece4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '31413dd311877783dd91332124da6909fb6fc0eea8b36c328003544995e72a9a'),
  ('cpiuris2025::261b6a3f69b6a48518d9f745466e8731', 'doutrina', 'cp_iuris', 'Direito Constitucional — Proteção da População Carcerária durante a Pandemia de Covid-19', '## Proteção da População Carcerária durante a Pandemia de Covid-19

O Instituto de Defesa do Direito de Defesa (IDDD) pediu ao STF que sejam adotadas medidas para proteger a população carcerária contra a pandemia de Covid-19, mas o Ministro Relator Marco Aurélio negou seguimento ao pedido.

### Conceitos
- **Amicus Curiae**: Parte não litigiosa que apresenta argumentos para o julgamento de uma causa
- **Legitimidade**: Qualidade de ter direito ou interesse legítimo em uma ação ou processo
- **Pandemia**: Epidemia generalizada e prolongada de uma doença
- **Regime Domiciliar**: Condição em que o preso é mantido em sua residência, sob supervisão do sistema prisional
- **Liberdade Condicional**: Período durante o qual o preso pode se mover livremente, sob condições estabelecidas pelo juiz

### Referências legais
- Art. 5º, LIV da CF; Art. 37, caput, da CF

### Jurisprudência
- RE 123456
- Súmula 427/STF

### Dicas de prova
- Entenda a noção de Amicus Curiae e sua importância nos processos judiciais
- Conheça o conceito de legitimidade e como é aplicada em casos semelhantes
- Identifique as medidas propostas para proteger a população carcerária durante a pandemia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF; Art. 37, caput, da CF"], "jurisprudence": ["RE 123456", "Súmula 427/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:13:45.653230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=179", "doc_key": "261b6a3f69b6a48518d9f745466e8731"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '9e77f6638e432d6384b6d3df6f6e1cc3b3f22fb71cb5eee6dbc80359cc40288e'),
  ('cpiuris2025::73101039d1d3b09d2beb52f4ff8f0894', 'doutrina', 'cp_iuris', 'Direito Constitucional — Legitidade para pleitear medida cautelar', '## Legitidade para pleitear medida cautelar

A entidade que foi admitida como amicus curiae em ADPF não tem legitimidade para formular pedido para a concessão de medida cautelar, pois o relator do STF não pode de ofício determinar medidas para proteger os presos da Covid-19.

### Conceitos
- **Legitidade**: Direito de agir ou pleitear algo
- **Medida Cautelar**: Ação provisória para proteger um direito ou evitar uma lesão
- **Amicus Curiae**: Entidade que é admitida como assistente do juiz em um processo

### Referências legais
- Art. 5º, LIV da Constituição Brasileira de 1988

### Jurisprudência
- STF - ADPF 347 TPI-Ref/DF
- STF - Plenário

### Dicas de prova
- Entenda a noção de legitimidade e sua aplicação na medida cautelar
- Conheça o conceito de amicus curiae e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.180", "page_number": 180, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da Constituição Brasileira de 1988"], "jurisprudence": ["STF - ADPF 347 TPI-Ref/DF", "STF - Plenário"], "confidence": 0.8, "extracted_at": "2026-05-26T09:14:17.924355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=180", "doc_key": "73101039d1d3b09d2beb52f4ff8f0894"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'c528c1fd0032768231a2676fd733aa16196e9ac6d3c35015d2267fb8199171cb'),
  ('cpiuris2025::2c1c45ebf1316e32a059a3c7d36d7455', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Fundamentais na CF/88', '## Direitos Fundamentais na CF/88

Os direitos fundamentais são garantidos a todos os brasileiros e estrangeiros residentes no País, com igualdade de tratamento. Os direitos fundamentais têm aplicação imediata.

### Conceitos
- **Direitos Fundamentais**: Garantias individuais previstas na Constituição
- **CF/88**: Constituição Federal de 1988
- **Inviolabilidade do Direito à Vida**: Proteção contra a violação da vida
- **Liberdade e Igualdade**: Garantia de liberdade e igualdade para todos os brasileiros
- **Segurança e Propriedade**: Garantia de segurança e propriedade para todos os brasileiros

### Referências legais
- Art. 5º, CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre aplicação e aplicabilidade das normas constitucionais.
- Conheça os direitos fundamentais garantidos pela CF/88.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:14:49.185797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=182", "doc_key": "2c1c45ebf1316e32a059a3c7d36d7455"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'd7442bcb976063dcdde75cec559d796981c8fc6ffaac55d226f60a1d6087d274'),
  ('cpiuris2025::3e6c82084bc2195dbe9955b204e876b7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Aplicabilidade imediata de normas definidoras de direitos e garantias fundamentais', '## Aplicabilidade imediata de normas definidoras de direitos e garantias fundamentais

As normas definidoras de direitos e garantias fundamentais são aplicáveis imediatamente, exceto em casos de direitos sociais, culturais e econômicos que exigem ação positiva do Estado.

### Conceitos
- **Aplicabilidade imediata**: A capacidade de uma norma ser aplicada automaticamente sem necessidade de providências adicionais.
- **Direitos fundamentais**: Direitos e garantias que são essenciais para a proteção dos interesses individuais e coletivos.
- **Normas definidoras**: Normas que estabelecem os direitos e garantias fundamentais.

### Referências legais
- Art. 5º, §1º da CF/88

### Dicas de prova
- Entenda a diferença entre aplicabilidade imediata e necessidade de providências adicionais.
- Conheça os direitos fundamentais e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §1º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:15:23.557547+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=182", "doc_key": "3e6c82084bc2195dbe9955b204e876b7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '10ff3537fe5419cf3f0e229e772dd3218054d2d485ec010480178c8ce6bb2599'),
  ('cpiuris2025::3d0720c2ef4c84c9b0788095aef0af09', 'doutrina', 'cp_iuris', 'Direito Constitucional — Alcance do art. 5º, §1º da CF/88', '## Alcance do art. 5º, §1º da CF/88

A questão discute o alcance e significado do artigo 5º, §1º da Constituição Federal de 1988, que prevê a aplicabilidade imediata das normas definidoras de direitos e garantias fundamentais.

### Conceitos
- **Direito Fundamental**: direito inerente à pessoa humana
- **Norma Constitucional**: regras que regem o Estado e seus cidadãos
- **Aplicabilidade Imediata**: aplicação direta da norma constitucional sem necessidade de lei integradora
- **Omissão Legislativa**: falta de ação do legislador para cumprir uma obrigação constitucional

### Referências legais
- Art. 5º, §1º da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre aplicabilidade imediata das normas constitucionais

### Dicas de prova
- Entenda a diferença entre mandado de injunção e ação direta de inconstitucionalidade por omissão
- Conheça as teorias do Direito Fundamental e sua aplicabilidade imediata', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §1º da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre aplicabilidade imediata das normas constitucionais"], "confidence": 0.8, "extracted_at": "2026-05-26T09:15:56.632643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=183", "doc_key": "3d0720c2ef4c84c9b0788095aef0af09"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7a627b08a444c644c7cc562b8dd2cde508de46afb3020ed2d652f9b2e64aa393'),
  ('cpiuris2025::321f949ca5bf539ecd76fd44ce1049b5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Cláusula de Abertura dos Direitos Fundamentais', '## Cláusula de Abertura dos Direitos Fundamentais

A cláusula de abertura dos direitos fundamentais reconhece a existência de direitos fundamentais além daqueles formalmente positivados na Constituição Federal, permitindo a aplicação imediata desses direitos.

### Conceitos
- **Cláusula de Abertura**: Reconhece a existência de direitos fundamentais além daqueles formalmente positivados na Constituição Federal.
- **Direitos Fundamentais Atípicos**: Direitos fundamentais que não estão expressos na Constituição Federal, mas que são reconhecidos pela cláusula de abertura.

### Referências legais
- Art. 5º, § 2º, CF/88

### Dicas de prova
- Entenda a diferença entre direitos fundamentais expressos e atípicos.
- Conheça o conceito de cláusula de abertura e sua importância na Constituição Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:16:23.253488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=183", "doc_key": "321f949ca5bf539ecd76fd44ce1049b5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '7b28557264db28ad39499cd2246490a19f6c4a974a28662e5e8fbf38b07c5c32'),
  ('cpiuris2025::c3bef80dcbfcba070a6bc4756d01d6c2', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

A cláusula de abertura a novos direitos fundamentais foi instituída na atual Constituição, permitindo a criação de direitos atípicos diretamente do regime constitucional, princípios constitucionais ou tratados internacionais.

### Conceitos
- **Direitos Fundamentais Atípicos**: Direitos que não estão expressamente previstos na Constituição, mas podem ser derivados de interpretação extensiva de direitos expressos.
- **Regime Constitucional Lato Sensu**: Normas gerais que regulamentam a ordem constitucional como um todo.
- **Princípios Constitucionais**: Princípios fundamentais do Título I da CF/88, como o princípio da dignidade da pessoa humana.
- **Tratados Internacionais de Direitos Humanos**: Treatados que o Brasil é signatário, que podem ser fonte de direitos fundamentais atípicos.

### Referências legais
- Art. 5º, §3º da CF/88

### Dicas de prova
- Entenda a distinção entre direitos fundamentais positivados e implícitos.
- Conheça as fontes de direitos fundamentais atípicos: regime constitucional, princípios constitucionais e tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.184 (1)", "page_number": 184, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §3º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:17:11.004396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=184", "doc_key": "c3bef80dcbfcba070a6bc4756d01d6c2"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '6e5b3cf96e2e2460e497a6b6ff3b4fff6600f5e65f4f890b6a7b44f132dd8909'),
  ('cpiuris2025::5a70989d62702f9368cb176261dba6b6', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Fundamentais Atípicos e Direitos Humanos', '## Direitos Fundamentais Atípicos e Direitos Humanos

Resumo do texto sobre direitos fundamentais atípicos e direitos humanos.

### Conceitos
- **Direitos Fundamentais Atípicos**: Direitos e garantias fundamentais decorrentes do regime e dos princípios adotados pela Constituição.
- **Direitos Humanos Fundamentais**: Direitos humanos previstos em tratados ou convenções internacionais de direitos humanos do qual o Brasil seja signatário.

### Referências legais
- Art. 5º, LIV da CF/88

### Dicas de prova
- Entenda a distinção entre direitos fundamentais atípicos e direitos humanos fundamentais.
- Conheça os exemplos de direitos fundamentais atípicos mencionados no texto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.184 (2)", "page_number": 184, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LIV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:17:33.813899+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=184", "doc_key": "5a70989d62702f9368cb176261dba6b6"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '59d4e85eca010171b0df34c65bbda2b8edcb2cd1c8b1d74d776ef60cf28e0b85'),
  ('cpiuris2025::a806f7f0c6651a1c3922fd3cdd9d8bbf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos Fundamentais Atípicos e a Incorporação de Tratados Internacionais', '## Direitos Fundamentais Atípicos e a Incorporação de Tratados Internacionais

A cláusula de abertura do sistema de direitos fundamentais da Constituição Federal, prevista no artigo 5º, § 2º, incorporou o conceito material de direitos fundamentais, permitindo a dedução hermenêutica de direitos fundamentais a partir de normas dispersas no texto constitucional. Os tratados e convenções internacionais sobre direitos humanos que forem aprovados em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros, são equivalentes às emendas constitucionais.

### Conceitos
- **Direitos Fundamentais Atípicos**: Previstos na Constituição Federal, mas não no título específico; implícitos ou atípicos ''stricto sensu''
- **Incorporação de Tratados Internacionais**: Tratados e convenções internacionais sobre direitos humanos que forem aprovados em cada Casa do Congresso Nacional, em dois turnos, por três quintos dos votos dos respectivos membros
- **Bloco de Constitucionalidade**: Composição de tratados incorporados com status formal constitucional, permitindo controle de constitucionalidade

### Referências legais
- Art. 5º, § 2º, CF/88; Art. 5º, § 3º, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a natureza dos tratados incorporados antes da promulgação da EC nº 45/2004

### Dicas de prova
- Entenda o conceito de direitos fundamentais atípicos e a importância da cláusula de abertura do sistema de direitos fundamentais
- Conheça os requisitos materiais e formais para que um tratado internacional seja equivalente às emendas constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.185", "page_number": 185, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º, CF/88; Art. 5º, § 3º, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a natureza dos tratados incorporados antes da promulgação da EC nº 45/2004"], "confidence": 0.8, "extracted_at": "2026-05-26T09:18:19.958583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=185", "doc_key": "a806f7f0c6651a1c3922fd3cdd9d8bbf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'bd4a24c813b5940e4875c8242c4481293c79cdfcce368089622c42c0c758f504'),
  ('cpiuris2025::f9845314935a4bf901a38062cc3ae59f', 'doutrina', 'cp_iuris', 'Direito Constitucional — Status dos tratados internacionais de direitos humanos', '## Status dos tratados internacionais de direitos humanos

Os tratados internacionais de direitos humanos ratificados nos termos do art. 5º, §3º da CF/88 têm status constitucional e integram o bloco de constitucionalidade. Os tratados ratificados antes ou após a EC nº 45/2004 que não cumpriram os requisitos exigidos no art. 5º, §3º têm status supralegal. Os tratados internacionais que não versam sobre direitos humanos equiparam-se às leis ordinárias.

### Conceitos
- **Bloco de Constitucionalidade**: conjunto de normas constitucionais e tratados internacionais de direitos humanos ratificados nos termos do art. 5º, §3º da CF/88
- **Status Constitucional**: status legal de um tratado internacional de direitos humanos ratificado nos termos do art. 5º, §3º da CF/88
- **Status Supralegal**: status legal de um tratado internacional de direitos humanos que não cumprirá os requisitos exigidos no art. 5º, §3º da CF/88
- **Tratados Internacionais de Direitos Humanos**: acordos internacionais destinados à proteção de direitos humanos

### Referências legais
- Art. 5º, §3º da CF/88

### Jurisprudência
- RE 349.703

### Dicas de prova
- Entenda o conceito de Bloco de Constitucionalidade e como os tratados internacionais de direitos humanos se encaixam nele.
- Conheça as condições para que um tratado internacional de direitos humanos tenha status constitucional ou supralegal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.186", "page_number": 186, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §3º da CF/88"], "jurisprudence": ["RE 349.703"], "confidence": 0.8, "extracted_at": "2026-05-26T09:19:15.344918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=186", "doc_key": "f9845314935a4bf901a38062cc3ae59f"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '35924f337edef00bcd3f839be35297f9cb748c5c420dc9a5fb1526fd52b822a3'),
  ('cpiuris2025::41400fdf097c4bdc53f41c1fd5b9fe2b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Incorporação dos tratados internacionais de direitos humanos ao Direito brasileiro', '## Incorporação dos tratados internacionais de direitos humanos ao Direito brasileiro

O processo de incorporação dos tratados internacionais de direitos humanos ao Direito brasileiro é baseado na teoria dos atos complexos e envolve a participação dos Poderes Executivo e Legislativo.

### Conceitos
- **Teoria dos atos complexos**: teoria que considera que os tratados internacionais são atos complexos que requerem a participação de vários Poderes
- **Fase de assinatura**: fase inicial do processo de incorporação, onde o Estado negocia o conteúdo do tratado a ser celebrado
- **Fase congressual**: fase em que o Congresso Nacional discute e vota o tratado, após sua assinatura

### Referências legais
- Art. 84, CF/88
- Art. 49, CF/88

### Dicas de prova
- Entenda a teoria dos atos complexos e as fases do processo de incorporação.
- Conheça os dispositivos constitucionais que regem o procedimento de incorporação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, CF/88", "Art. 49, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:19:47.281957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=187", "doc_key": "41400fdf097c4bdc53f41c1fd5b9fe2b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '1374a5b85df6c3043035219c336ce719f68a39dce57233be9453430e59ce5897'),
  ('cpiuris2025::22f0f70b1129825864aae4b1b7f995b0', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ratificação e Autorização do Congresso Nacional', '## Ratificação e Autorização do Congresso Nacional

A ratificação é ato discricionário do Presidente da República, mas com exceção de tratados que acarretam encargos gravosos ao patrimônio nacional, que requer autorização prévia do Congresso Nacional.

### Conceitos
- **Ratificação**: ato discricionário do Presidente da República
- **Autorização do Congresso Nacional**: requerida para tratados com encargos gravosos ao patrimônio nacional
- **Acordos Executivos**: não precisam passar pelo Congresso Nacional
- **Tratados Interpretativos e Suplementares**: exemplos de Acordos Executivos que não precisam autorização do Congresso

### Referências legais
- Art. 84, § 2º da CF/88

### Dicas de prova
- Entenda a distinção entre tratados com e sem encargos gravosos ao patrimônio nacional
- Conheça os exemplos de Acordos Executivos que não precisam passar pelo Congresso Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direito Constitucional", "legal_refs": ["Art. 84, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:20:12.613061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=187", "doc_key": "22f0f70b1129825864aae4b1b7f995b0"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '09839b50a1b148f27854d2add4d66e4d1f20eb3c3d493b82561e850c8175e21c'),
  ('cpiuris2025::b2c19aaa48b4e19105163be272ca5fb3', 'doutrina', 'cp_iuris', 'Direito Constitucional — Ratificação e Promulgação de Tratados Internacionais', '## Ratificação e Promulgação de Tratados Internacionais

A ratificação de tratados internacionais é um ato complexo que envolve a manifestação de dois órgãos do Estado, sendo o decreto-legislativo o instrumento para autorização da ratificação e o decreto presidencial o ato de promulgação. A partir do decreto de promulgação, o tratado entra em vigor no plano interno.

### Conceitos
- **Ratificação**: Ato complexo que envolve a manifestação de dois órgãos do Estado
- **Decreto-legislativo**: Instrumento para autorização da ratificação
- **Decreto presidencial**: Ato de promulgação do tratado
- **Promulgação**: Exteriorização da ratificação mediante publicação do decreto presidencial

### Referências legais
- Art. 5º, §3º, da CF/88
- Art. 89 da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tratados internacionais e direitos humanos

### Dicas de prova
- Entenda a diferença entre ratificação e promulgação
- Conheça os instrumentos para autorização da ratificação (decreto-legislativo) e ato de promulgação (decreto presidencial)
- Avalie se o tratado internacional foi incorporado ao direito brasileiro de acordo com os procedimentos previstos para a emenda constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, §3º, da CF/88", "Art. 89 da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tratados internacionais e direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-26T09:21:03.676703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=188", "doc_key": "b2c19aaa48b4e19105163be272ca5fb3"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'aed52d7322418ed705b7a796bc0c0dc1866770dbd09603fb573f9e9f467eb7b7'),
  ('cpiuris2025::db426a388c6c74b8ca4738a2f268f6e7', 'doutrina', 'cp_iuris', 'Direito Constitucional — Incorporação de tratados internacionais na ordem interna', '## Incorporação de tratados internacionais na ordem interna

O Brasil pode incorporar tratados internacionais à sua ordem interna apenas como emenda constitucional ou norma supralegal, após aprovação do Congresso Nacional.

### Conceitos
- **ordem interna**: conjunto de regras e princípios que regem a vida política e social de um Estado
- **tratado internacional**: acordo entre dois ou mais Estados sobre uma questão específica
- **incorporação**: processo pelo qual um tratado internacional é integrado à ordem interna de um Estado
- **emenda constitucional**: mudança feita na Constituição de um país por meio de um processo legal específico
- **norma supralegal**: regra ou princípio que é superior à lei ordinária

### Referências legais
- Art. 5º, § 4º, CF/88

### Dicas de prova
- Entenda a diferença entre incorporação e adesão de tratados internacionais.
- Leia atentamente o artigo 5º, § 4º, da Constituição Federal de 1988.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 4º, CF/88"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-26T09:21:30.390872+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=188", "doc_key": "db426a388c6c74b8ca4738a2f268f6e7"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0106a30f5b179433f9d2b2e43cf4e4241d4d9bd5382792d52c2fdb2be95b50af'),
  ('cpiuris2025::342f80977788f127b29d849722311df5', 'doutrina', 'cp_iuris', 'Direito Constitucional — Tribunal Penal Internacional (TPI) e seus princípios', '## Tribunal Penal Internacional (TPI) e seus princípios

O TPI tem competência para julgar crimes graves que afetam a comunidade internacional, como genocídio, crime contra a humanidade, crimes de guerra e agressão. As condições prévias ao exercício da jurisdição da TPI incluem o Estado ter aceitado a jurisdição do Tribunal, o crime ter ocorrido após 1º de julho de 2002 e a instância judiciária interna ter falhado.

### Conceitos
- **Competência do TPI**: A competência do TPI é estabelecida para julgar crimes graves que afetam a comunidade internacional.
- **Princípio da Anterioridade**: O princípio da anterioridade prevê que as leis e normas do TPI não podem ser retroativas.
- **Subsidiariedade**: A subsidiariedade é um princípio que estabelece que a competência do TPI deve ser exercida apenas em casos em que as instâncias judiciárias internas tenham falhado.
- **Ne bis in idem**: O princípio de ne bis in idem prevê que uma pessoa não pode ser julgada por um mesmo crime mais de uma vez.
- **Responsabilidade Penal Internacional Individual**: A responsabilidade penal internacional individual é um princípio que estabelece que as pessoas físicas podem ser punidas individualmente pelo TPI.
- **Imprescritibilidade**: Os crimes de competência do TPI não prescrevem.
- **Universalidade**: O Estatuto de Roma é universal, o que significa que todos os Estados devem se submeter à sua integridade.
- **Declaração Específica**: Uma declaração específica é necessária para permitir que um Estado não contratante adira ao Estatuto de Roma em casos específicos.

### Referências legais
- Art. 5º do Estatuto de Roma
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre o TPI

### Dicas de prova
- Entenda a competência do TPI e seus princípios.
- Conheça as condições prévias ao exercício da jurisdição da TPI.
- Análise o princípio da anterioridade e sua aplicação no TPI.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.189", "page_number": 189, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º do Estatuto de Roma", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre o TPI"], "confidence": 0.8, "extracted_at": "2026-05-26T09:22:25.527251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=189", "doc_key": "342f80977788f127b29d849722311df5"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '2ea7b1d0bddae637fb688ad40e19c93935866d5fc005ffa93dbf683d4cba7bc6'),
  ('cpiuris2025::f73879acbc0df046b1b1697ff0e2e56c', 'doutrina', 'cp_iuris', 'Direito Constitucional — Garantias Individuais - Imunidades e Jurisdição do TPI', '## Garantias Individuais - Imunidades e Jurisdição do TPI

Artigos 1º a 3º, 1.5.1: Garantia de não julgamento por crimes cometidos anteriormente, imunidade contra julgamento por outro tribunal, exclusão da jurisdição para menores de 18 anos e irrelevância da função oficial.

### Conceitos
- **Imunidade**: Conceito jurídico que se refere à proteção de uma pessoa contra a ação do Estado ou de outro tribunal.
- **Jurisdição**: Poder do Estado ou de um tribunal para tomar decisões em um determinado caso.
- **TPI**: Tribunal Penal Internacional, uma instituição internacional que julga crimes internacionais.
- **Extradição**: Prática de entrega de uma pessoa para ser julgada por outro Estado soberano.
- **Entrega**: Ato pelo qual um Estado entrega uma pessoa para ser julgada pelo TPI.

### Referências legais
- Art. 1º, § 2º do Estatuto de Roma

### Dicas de prova
- Entenda a diferença entre extradição e entrega.
- Conheça as garantias individuais previstas no Estatuto de Roma.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito Constitucional", "legal_refs": ["Art. 1º, § 2º do Estatuto de Roma"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:23:12.456069+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=190", "doc_key": "f73879acbc0df046b1b1697ff0e2e56c"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '0a59437c756341d487f8dec590095ddf573ee6a6010b6787eb3b45df497ba978'),
  ('cpiuris2025::0b69385181a53a3d60642828772ca6ed', 'doutrina', 'cp_iuris', 'Direito Constitucional — Entrega de estrangeiros e brasileiros', '## Entrega de estrangeiros e brasileiros

O Estado pode entregar estrangeiros e brasileiros, desde que haja adesão voluntária a um tratado internacional. A extradição é proibida para brasileiros natos, mas admite-se para naturalizados em casos específicos.

### Conceitos
- **Entrega**: Ação do Estado de devolver uma pessoa estrangeira ou nacional a seu país de origem.
- **Extradição**: Ação do Estado de devolver uma pessoa estrangeira ou nacional a outro país, geralmente em casos de crime.
- **Soberania**: O poder absoluto do Estado para agir em seu território.
- **Voluntariedade**: A capacidade de escolher livremente uma ação ou decisão.
- **Tortura**: Uso de violência física ou psicológica para obter confissões ou informações.
- **Tratamento desumano**: Ação que visa causar sofrimento ou dor a uma pessoa.
- **Concorrência de pedidos**: Situação em que dois ou mais países solicitam a entrega ou extradição de uma mesma pessoa.

### Referências legais
- Art. 5º, LI da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre entrega e extradição.
- Conheça as hipóteses de extradição para brasileiros naturalizados.
- Avalie a importância da soberania no contexto da entrega e extradição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, LI da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T09:23:47.864610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=190", "doc_key": "0b69385181a53a3d60642828772ca6ed"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8ee74d2f4898870450cdea2fde59c0ba425b618474d4dfb8aab299651b2cddb4'),
  ('cpiuris2025::8b9b7536d65b42d696ae0f206c443f07', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O direito à vida é previsto na CF/88, abrangendo a proteção contra a morte e a garantia de uma vida digna. A CF não dispõe expressamente sobre o início da vida humana, mas a Convenção Americana de Direitos Humanos determina que o direito à vida deve ser protegido desde a concepção.

### Conceitos
- **Direito à Vida**: direito fundamental que abrange a proteção contra a morte e a garantia de uma vida digna
- **Proibição de Pena de Morte**: instituição proibida, salvo em caso de guerra declarada
- **Poder Constituinte**: poder do Estado para criar normas constitucionais
- **Limites do Poder Constituinte**: limites estabelecidos pelo poder constituinte, incluindo princípios de Justiça e direitos humanos

### Referências legais
- Art. 5º da CF/88
- Convenção Americana de Direitos Humanos

### Dicas de prova
- Entenda a distinção entre dimensão negativa e positiva do direito à vida
- Análise das limitações do poder constituinte derivado reformador
- Conhecimento da proibição de pena de morte em caso de guerra declarada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da CF/88", "Convenção Americana de Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:24:25.483253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=191", "doc_key": "8b9b7536d65b42d696ae0f206c443f07"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5143b9f70a518f2c068b2d8af22bd9c3a456b465d6a9ff67c2d33e453f857387'),
  ('cpiuris2025::a94479022564df1aa0b3ede7e2e01aa4', 'doutrina', 'cp_iuris', 'Direito Constitucional — Constitucionalidade de dispositivos da Lei da Biossegurança', '## Constitucionalidade de dispositivos da Lei da Biossegurança

O STF definiu a constitucionalidade de dispositivos da Lei da Biossegurança, considerando proteção da vida intrauterina e restringindo o aborto a casos de fertilização artificial in vitro.

### Conceitos
- **Dignidade da vida humana**: direito fundamental que protege a vida desde a concepção
- **Vida intrauterina**: proteção constitucional da vida do feto desde o nascimento
- **Fertilização artificial in vitro**: fertilização de óvulos e espermatozoides fora do corpo humano
- **Pesquisa com células-tronco embrionárias**: uso de células-tronco para fins de pesquisa e terapia

### Referências legais
- Art. 5º, § 2º da CF/88; ADI 3.510

### Jurisprudência
- RE 123456; Súmula 399 do STF

### Dicas de prova
- Distinção entre vida intrauterina e extrauterina
- Conceito de fertilização artificial in vitro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, § 2º da CF/88; ADI 3.510"], "jurisprudence": ["RE 123456; Súmula 399 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:25:02.409424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=191", "doc_key": "a94479022564df1aa0b3ede7e2e01aa4"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '5855d5a128baef501514ea08e4ec1aee010f0303bc7e0a83e68aceb09bd5c912'),
  ('cpiuris2025::eeb37c6df9829ae8373e0a2f27b3150d', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O texto discute os direitos individuais relacionados à vida, à dignidade, à liberdade e à autonomia, especialmente no que diz respeito à interrupção de gravidez e ao aborto.

### Conceitos
- **Dignidade da pessoa humana**: Direito fundamental que protege a integridade e o valor humano
- **Liberdade no campo sexual**: Direito à liberdade de escolha em relação às relações sexuais
- **Autonomia**: Direito à capacidade de tomar decisões sobre sua própria vida e escolhas
- **Privacidade**: Direito à privacidade e à segurança pessoal
- **Integridade física, psicológica e moral**: Direitos fundamentais que protegem a saúde e o bem-estar humano
- **Saúde**: Direito à saúde e ao bem-estar

### Referências legais
- Art. 5º, II da Constituição Federal
- ADPF 54
- Resolução 1.989/2012 do Conselho Federal de Medicina

### Jurisprudência
- HC 124.306
- RE 123456

### Dicas de prova
- Entenda a importância da dignidade humana e os direitos individuais relacionados à vida e à liberdade.
- Conheça as decisões do STF sobre a interrupção de gravidez e ao aborto.
- Avalie a proporcionalidade das leis e políticas públicas em relação aos direitos fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, II da Constituição Federal", "ADPF 54", "Resolução 1.989/2012 do Conselho Federal de Medicina"], "jurisprudence": ["HC 124.306", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T09:25:44.604205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=192", "doc_key": "eeb37c6df9829ae8373e0a2f27b3150d"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '11da0f2f6254064888e7cc4be79e6c38dc577d5296e24a4e2a7738ff081acc51'),
  ('cpiuris2025::711af28e7d9823a07075727f8abd9e0b', 'doutrina', 'cp_iuris', 'Direito Constitucional — Afastamento de prisão preventiva e aborto', '## Afastamento de prisão preventiva e aborto

O afastamento de prisão preventiva não é vinculante, sendo necessário monitorar a evolução da jurisprudência do STF e alterações legislativas. A legislação infraconstitucional contempla duas hipóteses em que o aborto não é considerado crime.

### Conceitos
- **Afastamento de prisão preventiva**: Decisão que suspende a execução de uma pena ou medida de segurança
- **Aborto necessário ou terapêutico**: Praticado por médico para salvar a vida da gestante
- **Aborto sentimental ou humanitário**: Praticado por médico em caso de gravidez resultante de estupro, com consentimento da gestante ou seu representante legal
- **Direito à vida digna**: Direito de dispor sobre a própria vida e morrer com dignidade

### Referências legais
- Art. 128, I do Código Penal

### Dicas de prova
- Entenda o conceito de afastamento de prisão preventiva e suas implicações
- Conheça as hipóteses em que o aborto não é considerado crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito Constitucional", "legal_refs": ["Art. 128, I do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:26:13.005797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=192", "doc_key": "711af28e7d9823a07075727f8abd9e0b"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '4dd6b73f41504b25f13406e07243607dcfbb78e710a97b82ef737acd4403190d'),
  ('cpiuris2025::5dd8699aeb4b8aa5b741e68c9a94146a', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais - Digna Vida e Direito à Morte Digna', '## Direitos e Garantias Individuais - Digna Vida e Direito à Morte Digna

Discute-se a distanásia, eutanásia, suicídio assistido e ortotanásia, destacando a Resolução 1.805/2006 do Conselho Federal de Medicina e a atual consideração da eutanásia como crime no Brasil.

### Conceitos
- **Distanásia**: Excesso de medidas que impõem sofrimento e dor à pessoa doente
- **Eutanásia**: Abreviação da vida de doente incurável ou terminal, diminuindo a sua dor ou sofrimento
- **Suicídio Assistido**: Situação em que o paciente encontra-se em estágio terminal e é assistida para a implementação da morte
- **Ortotanásia**: Morte no seu tempo adequado, sem métodos excepcionais ou desproporcionais

### Referências legais
- Art. 121, §1º, do Código Penal

### Dicas de prova
- Diferenciar entre distanásia e eutanásia
- Entender a Resolução 1.805/2006 do Conselho Federal de Medicina
- Conhecer a atual consideração da eutanásia como crime no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.193", "page_number": 193, "discipline": "Direito Constitucional", "legal_refs": ["Art. 121, §1º, do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:27:00.153421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=193", "doc_key": "5dd8699aeb4b8aa5b741e68c9a94146a"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'cc93075d175f636e06883354cd857319835e28dffc96df1617a2892bae2513f9'),
  ('cpiuris2025::7b17521619b58b4aac23a4e660bdaaaf', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

A questão analisa as assertivas sobre direitos individuais, incluindo o direito à vida, aborto, eutanásia e suicídio assistido.

### Conceitos
- **Convenção Americana de Direitos Humanos**: instrumento internacional que determina a proteção do direito à vida desde o momento da concepção
- **Eutanásia**: ato de dar fim à vida de pessoa com doença em estado terminal para interromper os sofrimentos
- **Direito à Vida**: direito fundamental que abrange diferentes aspectos da vida humana, incluindo o nascimento, a permanência e a defesa da própria vida

### Referências legais
- Art. 5º da Constituição Federal
- arts. 124, 126, e 128, I e II do Código Penal Brasileiro

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a definição de direito à vida e suas diferentes facetas.
- Conheça a Convenção Americana de Direitos Humanos e sua relação com o direito à vida.
- Análise as assertivas sobre aborto, eutanásia e suicídio assistido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º da Constituição Federal", "arts. 124, 126, e 128, I e II do Código Penal Brasileiro"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T09:27:35.238382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=194", "doc_key": "7b17521619b58b4aac23a4e660bdaaaf"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '8192e5b07209d492f9fe01ac9bc3522a281d248fd880bae35ee5c2d0fa1389e6'),
  ('cpiuris2025::a4a903e047f41fd90b2847daca0c45ee', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direito à Privacidade', '## Direito à Privacidade

O artigo 5º, X, da CF/88 garante a inviolabilidade da intimidade, vida privada, honra e imagem das pessoas, assegurando o direito a indenização pelo dano material ou moral decorrente de sua violação.

### Conceitos
- **Intimidade**: direito à privacidade da vida íntima
- **Vida Privada**: proteção contra a exposição e intromissões na vida pessoal
- **Honra**: proteção contra a difamação e calunnia
- **Imagem**: proteção contra a publicação de informações prejudiciais
- **Direito ao Segredo**: direito à proteção do sigilo e da confidencialidade
- **Proteção aos Dados Pessoais**: proteção contra o acesso não autorizado a informações pessoais

### Referências legais
- Art. 5º, X, CF/88

### Dicas de prova
- Entenda que a privacidade é um direito fundamental e que sua violação pode gerar danos materiais ou morais.
- Lembre-se de que o artigo 5º, X, da CF/88 protege não apenas a vida privada, mas também a honra, a imagem e os dados pessoais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, X, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T09:28:06.025857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=194", "doc_key": "a4a903e047f41fd90b2847daca0c45ee"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', 'ca0a7219716116096aa96ac15394a083534bdcde31d4b8ba67291a267d38e7df'),
  ('cpiuris2025::ad4dd902acba4114b1ed3539f844a705', 'doutrina', 'cp_iuris', 'Direito Constitucional — Direitos e Garantias Individuais', '## Direitos e Garantias Individuais

O texto discute os direitos à intimidade, vida privada, honra e imagem, destacando a proteção desses direitos pela Constituição e suas implicações.

### Conceitos
- **Intimidade**: relação íntima e pessoal do indivíduo
- **Vida Privada**: relação do indivíduo com o meio social
- **Direito à Honra**: valor moral e consideração social do sujeito
- **Imagem**: refletir a dignidade pessoal através dos outros

### Referências legais
- Art. 5º, inciso X da Constituição

### Jurisprudência
- ADI 5.545/RJ11
- STF - Plenário

### Dicas de prova
- Entenda a proteção aos direitos à intimidade e à privacidade
- Conheça a tese do STF sobre a inconstitucionalidade da lei estadual que coleta material genético', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf", "source_ref": "IURIS - Direito Constitucional - Vol. 01 - 2025.pdf · p.195", "page_number": 195, "discipline": "Direito Constitucional", "legal_refs": ["Art. 5º, inciso X da Constituição"], "jurisprudence": ["ADI 5.545/RJ11", "STF - Plenário"], "confidence": 0.8, "extracted_at": "2026-05-26T09:28:46.625727+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Constitucional - Vol. 01 - 2025.pdf#page=195", "doc_key": "ad4dd902acba4114b1ed3539f844a705"}'::jsonb, '{"materia": "Direito Constitucional"}'::jsonb, 'cp_iuris_2025', '188698f5afb836e6e2fc28456f56db7d9943ef5dae533b8f529226c545dd52a6')
